//! C API for the `rr_dr60` RR-DR60 signal-chain emulator.
//!
//! This is the language-neutral integration surface (spec FR-023, FR-024) for
//! C, Swift and other languages. The header `include/rr_dr60.h` is generated by
//! cbindgen. The contract is in `specs/001-pipeline-skeleton/contracts/c-api.md`.
//!
//! This is the only crate in the workspace that may use `unsafe`. Every
//! `unsafe` block carries a `// SAFETY:` comment, and every entry point catches
//! panics so that none unwinds into the host.
//!
//! # Rules (contracts/c-api.md)
//!
//! 1. Errors are values. No function aborts or unwinds into C. A caught panic returns
//!    [`RrDr60Status::InternalError`] and poisons the handle until `rr_dr60_reset` succeeds.
//! 2. A failed call changes nothing: out-parameters are left untouched and pipeline state is
//!    unchanged, apart from poisoning. The one exception is the info struct of
//!    `rr_dr60_process`, `rr_dr60_process_with_events`, `rr_dr60_record`,
//!    `rr_dr60_stop_recording` and `rr_dr60_play`, which is always written when not NULL
//!    (spec 003 contracts/c-api.md › Rule 2 amendment; extended by spec 006).
//! 3. The caller owns all buffers. The library never keeps a pointer after a call returns.
//! 4. A handle must not be used by two threads at the same time.
//! 5. `RrDr60Settings` only grows at the end. Callers set `struct_size`.
//!
//! # Real-time safety (spec 006 FR-017)
//!
//! Real-time safe: `rr_dr60_process`, `rr_dr60_process_with_events`, `rr_dr60_max_events`,
//! `rr_dr60_reset`, `rr_dr60_latency_samples`, `rr_dr60_settings_validate`,
//! `rr_dr60_start_recording`, `rr_dr60_record`, `rr_dr60_max_record_events`,
//! `rr_dr60_stop_recording`, `rr_dr60_start_playback`, `rr_dr60_play`,
//! `rr_dr60_stop_playback`, `rr_dr60_set_route`, `rr_dr60_get_route`, `rr_dr60_set_volume`,
//! `rr_dr60_get_volume`, `rr_dr60_set_battery_volts`, `rr_dr60_get_battery_volts`,
//! `rr_dr60_battery_ceiling_factor`, `rr_dr60_battery_ceiling_db`,
//! `rr_dr60_battery_trajectory_row` (spec 018), `rr_dr60_set_playback_speed`, `rr_dr60_get_playback_speed`,
//! `rr_dr60_playback_length_samples`, `rr_dr60_meters` (spec 016), the scheduled changes
//! (`rr_dr60_schedule_change`, `rr_dr60_pending_changes`, `rr_dr60_stream_position`,
//! `rr_dr60_clear_schedule`, `rr_dr60_process_with_events_and_changes`,
//! `rr_dr60_play_with_changes`, `rr_dr60_recording_counter`, `rr_dr60_speed_landing`; spec 015;
//! `rr_dr60_input_position`, `rr_dr60_record_with_changes`,
//! `rr_dr60_stop_recording_with_changes`, `rr_dr60_clock_of`, `rr_dr60_record_landing`; spec
//! 017), `rr_dr60_get_state`,
//! `rr_dr60_memory_status`, `rr_dr60_recording_length`, `rr_dr60_export_len`, the three
//! latency and drain reads and `rr_dr60_footprint_bytes`. Not real-time safe:
//! `rr_dr60_create`, `rr_dr60_destroy`, `rr_dr60_reconfigure` (allocate), `rr_dr60_erase`,
//! `rr_dr60_erase_all` (a bounded memmove), `rr_dr60_export`, `rr_dr60_import` (a CRC over
//! the recording).

use std::ffi::c_char;
use std::panic::{AssertUnwindSafe, catch_unwind};

use rr_dr60::{
    BlockInfo, ChangeEntry, Error, Pipeline, PlayInfo, RecordInfo, Route, Setting, Settings, State,
    StopOutcome, StopReason, StopResult, Stream, Tap, VasEvent, VasMode,
};

/// Library major version (equal to the Rust crate's).
pub const RR_DR60_VERSION_MAJOR: u32 = 0;
/// Library minor version.
pub const RR_DR60_VERSION_MINOR: u32 = 20;
/// Library patch version.
pub const RR_DR60_VERSION_PATCH: u32 = 0;

/// Result of every fallible C API call.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Status {
    /// Success.
    Ok = 0,
    /// A required pointer was NULL.
    NullPointer = 1,
    /// `host_rate_hz` is not a supported host rate.
    UnsupportedHostRate = 2,
    /// Invalid tap value, too-small `struct_size`, or partially overlapping buffers.
    InvalidArgument = 3,
    /// An internal error (a caught panic). The handle is poisoned until `rr_dr60_reset`.
    InternalError = 4,
    /// An AGC, VAS or memory setting is out of range or not finite (spec 002 FR-011, spec 003
    /// FR-012, spec 006 FR-010: a memory capacity of 0 is "capacity too small").
    /// `rr_dr60_settings_validate` names it.
    InvalidSetting = 5,
    /// A recording is in progress (spec 006 FR-003, FR-013, FR-019).
    RecordingInProgress = 6,
    /// A playback is in progress (spec 006 FR-003, FR-019).
    PlaybackInProgress = 7,
    /// `rr_dr60_record` or `rr_dr60_stop_recording` while not recording (spec 006).
    NotRecording = 8,
    /// `rr_dr60_play` or `rr_dr60_stop_playback` while not playing (spec 006).
    NotPlaying = 9,
    /// No recorded time remains, so a recording cannot start (spec 006 FR-012; S-001 "FULL").
    MemoryFull = 10,
    /// The recording count is at its capacity (spec 006 FR-012; S-001: 99 items).
    NoRecordingSlots = 11,
    /// No recording has this number (spec 006 FR-013).
    NoSuchRecording = 12,
    /// An import exceeds the remaining time or slots; the memory is unchanged (spec 006 FR-014).
    DoesNotFit = 13,
    /// The bytes are not an exported recording of this engine (spec 006 FR-014).
    UnknownForm = 14,
    /// The bytes carry a form version this engine does not read (spec 006 FR-014).
    UnsupportedFormVersion = 15,
    /// The bytes are truncated, altered or inconsistent (spec 006 FR-014).
    Damaged = 16,
    /// `rr_dr60_reconfigure` to a configuration the stored recordings do not fit: a capacity
    /// below what is stored (spec 006 FR-019), or the other `speech_codec_enabled` while
    /// recordings are present (one memory holds one encoding, spec 008 FR-012); unchanged.
    StoredExceedsCapacity = 17,
    /// The recording store could not be reserved (spec 006 FR-017).
    AllocationFailed = 18,
    /// `rr_dr60_export` into a buffer shorter than the recording's byte form; nothing written,
    /// the needed length reported (spec 006 FR-014).
    BufferTooSmall = 19,
    /// A stage manifest number that is 0 or above the stage count (spec 007 FR-017).
    NoSuchStage = 20,
    /// An import whose encoding (frames or samples) differs from the engine's configuration
    /// (spec 008 FR-012).
    EncodingDiffers = 21,
    /// The bytes carry speech-codec frames of a model version this release cannot decode
    /// (spec 008 FR-010, FR-011).
    UnsupportedCodecModelVersion = 22,
    /// `rr_dr60_set_volume` with a position outside 0 … 1 or not finite; the position is
    /// unchanged (spec 009 FR-003).
    InvalidVolume = 23,
    /// A processing call with `RR_DR60_TAP_AFTER_SPEAKER` or `RR_DR60_TAP_AFTER_EARPHONE` while
    /// the other route is selected; nothing processed (spec 009 FR-011).
    TapNotOnRoute = 24,
    /// `rr_dr60_set_playback_speed` or `rr_dr60_playback_length_samples` with a level other
    /// than 1 … 5; the level is unchanged (spec 013 FR-001).
    InvalidSpeedLevel = 25,
    /// A control-manifest read with an index past its list: the entry index at or past
    /// `rr_dr60_control_count()`, or an option, source or assumption index past the entry's
    /// count; nothing is written (spec 014 FR-013).
    NoSuchControl = 26,
    /// `rr_dr60_schedule_change` on a stream whose schedule already holds
    /// `RR_DR60_SCHEDULE_CAPACITY` pending changes; nothing stored (spec 015 FR-002).
    ScheduleFull = 27,
    /// `rr_dr60_schedule_change` with a control that is not a live control of the stream (the
    /// route, the volume, or on the playback stream the speed; a record-side value on the
    /// record stream or the one-pass, spec 017 FR-001), or any stream call with an unknown
    /// stream value; nothing changes (spec 015 FR-001).
    ControlNotOnStream = 28,
    /// A position read in a clock the stream does not have (spec 017 D2):
    /// `rr_dr60_stream_position` on the record stream (it has only the input clock) or
    /// `rr_dr60_input_position` on the playback stream (it has only the output clock); nothing
    /// is written.
    NoSuchClock = 29,
    /// `rr_dr60_set_battery_volts`, or `rr_dr60_schedule_change` of the battery value, with a
    /// voltage outside `RR_DR60_BATTERY_VOLTS_MIN` … `RR_DR60_BATTERY_VOLTS_MAX` or not finite;
    /// the value is unchanged and nothing is stored (spec 018 FR-001).
    InvalidBatteryVolts = 30,
    /// A processing record whose form version this library does not read: 0, or above
    /// `RR_DR60_PROCESSING_RECORD_VERSION` (spec 020 D4).
    UnknownRecordVersion = 31,
    /// A processing record with a line that is not `name = value`, a name version 1 does not
    /// define, a value that does not parse, or no final line end (spec 020 FR-002).
    MalformedRecord = 32,
    /// A processing record lacking a line its origin requires (spec 020 FR-002).
    MissingRecordField = 33,
    /// A processing record whose last line's checksum does not match its bytes (truncated or
    /// altered; spec 020 FR-002).
    RecordChecksumMismatch = 34,
    /// The run data handed to the processing-record writer is inconsistent with the recording:
    /// out of order, past the recording, from another stream, or more rows than the engine
    /// counted (spec 020 D10, FR-001).
    InconsistentRun = 35,
}

/// Names the offending field for `rr_dr60_settings_validate` (spec 002 US2 AS5).
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60SettingField {
    /// The settings are valid.
    None = 0,
    /// `host_rate_hz` is not a supported rate.
    HostRate = 1,
    /// `tap` is not an `RrDr60Tap` value (status `INVALID_ARGUMENT`).
    Tap = 2,
    /// `struct_size` is smaller than `sizeof(RrDr60Settings)` of this library version.
    StructSize = 3,
    /// `agc_knee_dbfs` is outside -40 to 3, or not finite (spec 005; value 4 named the 0.4
    /// target level).
    AgcKneeDbfs = 4,
    // 5 and 6 (AGC max gain / max attenuation) retired in 0.5; never reused. The fields they
    // named are `reserved_agc_1` and `reserved_agc_2`, which are ignored.
    /// `agc_attack_ms` is outside 1 to 50, or not finite (spec 005). Values 5 and 6 are retired
    /// (the 0.4 AGC maximum gain and maximum attenuation) and are never returned.
    AgcAttackMs = 7,
    /// `agc_release_ms` is outside 200 to 10000, or not finite (spec 005).
    AgcReleaseMs = 8,
    /// `vas_mode` is not an `RrDr60VasMode` value (status `INVALID_ARGUMENT`; spec 003).
    VasMode = 9,
    /// `vas_sensitivity` is outside 1 to 5 (spec 003).
    VasSensitivity = 10,
    /// `vas_threshold_dbfs` is outside -60 to 0, or not finite (spec 003).
    VasThresholdDbfs = 11,
    /// `vas_hang_ms` is outside 50 to 10000, or not finite (spec 003).
    VasHangMs = 12,
    /// `vas_onset_ms` is outside 0 to 200, or not finite (spec 003).
    VasOnsetMs = 13,
    /// `memory_capacity_s` is outside 1 to 86 400 (spec 006 FR-010; 0 is "capacity too small").
    MemoryCapacityS = 14,
    /// `memory_max_recordings` is outside 1 to 9 999 (spec 006 FR-010).
    MemoryMaxRecordings = 15,
    /// `mic_hiss_offset_db` is outside −18 to +12, or not finite; checked whether or not the
    /// capsule is on (spec 012 FR-003). Appended in 0.12.
    MicHissOffsetDb = 16,
}

/// Output tap point, passed as `uint32_t` in [`RrDr60Settings::tap`].
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Tap {
    /// After signal-chain stage 4 (record band-limit).
    AfterRecord = 0,
    /// After signal-chain stage 10 (playback band-limit). The default through 0.8; never
    /// bounded by the output clamp (spec 010 FR-003: the option is inert in the one-pass here).
    AfterPlayback = 1,
    /// After signal-chain stage 3 (the limiter), at the host rate: the limiter's output sample
    /// for sample. No rate conversion, no later stage, latency 0, no events (spec 005 FR-001).
    AfterAgc = 2,
    /// After signal-chain stage 5 (VAS). Stage 10 is not run (spec 003 FR-003).
    AfterVas = 3,
    /// After signal-chain stage 9 (the speech decoder), before stage 10 (spec 008 FR-015).
    /// Appended in 0.8.
    AfterDecoder = 4,
    /// The selected route's output: after the speaker (stage 12) or the earphone output (stage
    /// 13), at the route's full swing (spec 009 FR-011; A-042). The default since 0.9; to keep
    /// 0.8's output set `RR_DR60_TAP_AFTER_PLAYBACK`. Appended in 0.9. With
    /// `output_clamp_enabled` the only tap that is bounded (spec 010 FR-003); the selected
    /// route's last per-stage tap then differs from it wherever a sample was bounded.
    RouteOutput = 5,
    /// After signal-chain stage 11 (the volume control and power amplifier) on either route
    /// (spec 009 FR-011). Appended in 0.9. Never bounded by the output clamp (spec 010).
    AfterVolumeAmp = 6,
    /// After signal-chain stage 12 (the speaker template); refused with
    /// `RR_DR60_STATUS_TAP_NOT_ON_ROUTE` while the earphone route is selected (spec 009
    /// FR-011). Appended in 0.9. Never bounded by the output clamp (spec 010).
    AfterSpeaker = 7,
    /// After signal-chain stage 13 (the earphone output); refused with
    /// `RR_DR60_STATUS_TAP_NOT_ON_ROUTE` while the speaker route is selected (spec 009
    /// FR-011). Appended in 0.9. Never bounded by the output clamp (spec 010).
    AfterEarphone = 8,
    /// After signal-chain stage 1 (the capsule), at the host rate: the input plus the capsule's
    /// unshaped hiss. Nothing after it runs; latency 0, no events (spec 012 FR-008). Appended
    /// in 0.12.
    AfterMicCapsule = 9,
    /// After signal-chain stage 2 (the microphone amplifier), at the host rate. Nothing after
    /// it runs; latency 0, no events (spec 012 FR-008). Appended in 0.12.
    AfterMicAmp = 10,
}

/// `RR_DR60_TAP_AFTER_PLAYBACK` under the stage's name: after stage 10, before the output chain
/// (version 0.8's default output; spec 009 FR-011).
pub const RR_DR60_TAP_AFTER_STAGE_10: RrDr60Tap = RrDr60Tap::AfterPlayback;

/// What the VAS does with paused audio, passed as `uint32_t` in [`RrDr60Settings::vas_mode`]
/// (spec 003 FR-004).
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60VasMode {
    /// Removed, so the output can be shorter than the input. The default (S-001, A-008).
    Drop = 0,
    /// Replaced by silence, so the output keeps the input's length. An emulator option.
    Mute = 1,
}

/// The result of one `rr_dr60_process` call (spec 003 FR-004, FR-005).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60BlockInfo {
    /// Output samples written to `output[0 .. produced)`. Never more than `frames`. With the VAS
    /// in drop mode (the default) it can be smaller, or 0.
    pub produced: usize,
    /// VAS events this block generated (splices in drop mode, muted regions in mute mode).
    pub events: usize,
    /// The VAS is paused at the end of the block.
    pub paused: bool,
    /// Speech-codec frames encoded in this block (spec 008 FR-008); 0 with the codec bypassed.
    /// Appended in 0.8 (24 → 32 bytes on 64-bit targets).
    pub frames: usize,
}

/// A VAS splice (drop mode) or muted region (mute mode), from `rr_dr60_process_with_events`
/// (spec 003 FR-005).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60VasEvent {
    /// Drop mode: stream output index of the first sample after the splice. Mute mode: stream
    /// output index of the region's first muted sample. Counted from create, reset or
    /// reconfigure, so it does not depend on block sizes.
    pub output_position: u64,
    /// Drop mode: host input samples removed at this splice. Mute mode: the region's length.
    pub input_length: u64,
}

/// The output route (spec 006 FR-015), passed as `uint32_t`: a label in this version, the two
/// routes produce identical output until stages 11–13 are modeled.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Route {
    /// The built-in speaker (the default).
    Speaker = 0,
    /// The earphone jack (S-001; its path bypasses the power amplifier, A-032).
    Earphone = 1,
}

/// The stream a control change is scheduled on (spec 015 D2; spec 017 D2), passed as
/// `uint32_t`: the playback stream (its **output** clock counts the samples the current
/// playback has produced since `rr_dr60_start_playback`, the drain included), the one-pass
/// stream (its output clock counts the samples produced since construction, `rr_dr60_reset` or
/// `rr_dr60_reconfigure`, the clock the VAS events use; its **input** clock the input samples
/// processed since then) or the record stream (the recorder: its input clock counts the host
/// samples fed since `rr_dr60_start_recording`, the stop's silence included; it carries the
/// eight record-side values only). A control whose manifest paths include the record path is
/// positioned in the input clock (`rr_dr60_clock_of`).
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Stream {
    /// The player.
    Playback = 0,
    /// The one-pass processing.
    OnePass = 1,
    /// The recorder (spec 017).
    Record = 2,
}

/// Which clock a control's positions count in (spec 017 D2), written by `rr_dr60_clock_of` as
/// `uint32_t`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Clock {
    /// Host input samples the stream has processed (the record-side values).
    Input = 0,
    /// Host output samples the stream has produced (the route, the volume, the speed).
    Output = 1,
}

/// One applied control change (spec 015 FR-005), from `rr_dr60_process_with_events_and_changes`
/// or `rr_dr60_play_with_changes`: the host output index it landed on (the stream's clock), the
/// value the stream last applied for the control (`before`; chained: each entry's `before` is
/// the previous entry's `after` for that control on that stream, or the stream's starting
/// value), the value applied (`after`), the schedule call's `tag` (**0 means a plain setter**:
/// `rr_dr60_set_route`, `rr_dr60_set_volume`, `rr_dr60_set_playback_speed`; tag your own from
/// 1), and the control manifest's index of the control (resolve it by identifier through
/// `rr_dr60_control`, never assume it). Values are the control's own as doubles: a route 0 or 1,
/// a volume position (rounded to single precision), a level 1 … 5. 40 bytes, no size field
/// (the pre-1.0 ABI pass); `reserved` is 0.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct RrDr60ChangeEntry {
    /// The index the change landed on: a host output sample for the route, the volume and the
    /// speed; a host input sample for a record-side value (spec 017; `rr_dr60_clock_of`).
    pub position: u64,
    /// The stream's last applied value for the control.
    pub before: f64,
    /// The value applied.
    pub after: f64,
    /// The schedule call's tag; 0 for a plain setter.
    pub tag: u64,
    /// The control manifest's index.
    pub control: u32,
    /// The stream word since 0.20 (spec 020 D9): 0 none (an entry from before 0.20 or a
    /// default), 1 playback, 2 one-pass, 3 record. (Named `reserved` since 0.16; unchanged in
    /// size and position.)
    pub reserved: u32,
}

/// Pending changes each stream's schedule holds (spec 015 D4). Equal to the Rust
/// `changes::SCHEDULE_CAPACITY`.
pub const RR_DR60_SCHEDULE_CAPACITY: usize = 64; // 015 D4: equal to `rr_dr60::changes::SCHEDULE_CAPACITY` (a literal so cbindgen emits the define; the unit test pins it)

/// A `changes_capacity` that is always enough for one call (spec 015 FR-005). Equal to the
/// Rust `changes::MAX_CHANGES_PER_CALL`.
pub const RR_DR60_MAX_CHANGES_PER_CALL: usize = 139; // 015 FR-005; 017 FR-005: equal to `rr_dr60::changes::MAX_CHANGES_PER_CALL` (a literal so cbindgen emits the define; the unit test pins it)

/// The engine's state (spec 006 FR-003), in `RrDr60EngineState.state`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60State {
    /// Neither recording nor playing.
    Idle = 0,
    /// A recording is in progress; the speaker is muted (S-002).
    Recording = 1,
    /// A playback is in progress toward the selected route.
    Playing = 2,
}

/// Why a recording stopped by itself (spec 006 FR-012), in `RrDr60RecordInfo.stop_reason`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60StopReason {
    /// It did not stop by itself.
    None = 0,
    /// The stored total reached the time capacity (S-001 "FULL"; the partial recording is
    /// kept, A-039).
    MemoryFull = 1,
}

/// The engine's readable state, from `rr_dr60_get_state` (spec 006 FR-003, FR-015).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60EngineState {
    /// An `RrDr60State` value.
    pub state: u32,
    /// An `RrDr60Route` value: the selected output route.
    pub route: u32,
    /// The number of the recording in progress (the count plus one) or being played; 0 when
    /// idle.
    pub current_recording: u32,
    /// The speaker is muted: while recording (S-002). A label in this version.
    pub speaker_muted: bool,
}

/// The report of one `rr_dr60_record` call, and of the stop flush (spec 006 FR-006, FR-012).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60RecordInfo {
    /// Device samples appended to the recording by this call.
    pub stored: usize,
    /// VAS events this call generated; `rr_dr60_max_record_events` sizes the event buffer.
    pub events: usize,
    /// The VAS is paused at the end of the call.
    pub paused: bool,
    /// The recording stopped by itself during this call: the engine is idle and the recording
    /// is kept (a following `rr_dr60_stop_recording` is `NOT_RECORDING`).
    pub stopped: bool,
    /// An `RrDr60StopReason` value; `NONE` unless `stopped`.
    pub stop_reason: u32,
    /// Speech-codec frames appended to the recording in this call (spec 008 FR-008); 0 with the
    /// codec bypassed. Appended in 0.8.
    pub frames: usize,
    /// Speech-codec frames in the recording so far, this call's included (spec 008 FR-008).
    /// Appended in 0.8 (the struct grows 24 → 40 bytes on 64-bit targets).
    pub frames_total: u64,
}

/// The result of `rr_dr60_stop_recording` (spec 006 FR-005, FR-012; spec 008 FR-013).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60StopOutcome {
    /// The stop flush's report (all zeros when the flush was skipped).
    pub flush: RrDr60RecordInfo,
    /// The recording is in the memory; false when no input was fed and it was discarded as
    /// empty (A-039).
    pub kept: bool,
    /// Its number (1 to the count) when kept, else 0.
    pub number: u32,
    /// Its length in device samples (÷ 6000 for seconds, A-026) when kept, else 0; a whole
    /// number of frames with the speech codec on (spec 008 FR-013).
    pub length_samples: u64,
    /// Post-VAS device samples of silence produced after the last represented input sample
    /// (spec 008 FR-013): the padding to the frame boundary plus the 60-sample look-ahead; 0
    /// with the codec bypassed or when the recording was discarded. Appended in 0.8 (the struct
    /// grows 40 → 64 bytes on 64-bit targets, `flush` included). "Silence" is zero-valued
    /// input (spec 012 FR-009): with the capsule (stage 1) on, the recording's tail there
    /// carries the hiss.
    pub silence_fed_samples: u64,
    /// The record stream's input position when the stop was called (spec 020 D9): the host
    /// samples fed before it; a re-render feeds exactly this many and calls the same stop.
    /// Since 0.20 (the struct grew 64 → 80 bytes; it has no size field: the pre-1.0 ABI pass).
    pub stop_input_position: u64,
    /// The kept device sample at which the speech codec's padding begins (spec 020 D9): the
    /// recording's length without padding. Since 0.20.
    pub padding_start_sample: u64,
}

/// The report of one `rr_dr60_play` call (spec 006 FR-006, FR-008; spec 008 FR-008).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60PlayInfo {
    /// Host samples written to `output[0 .. produced)`.
    pub produced: usize,
    /// The recording and its drain ended in this call; the engine is idle.
    pub finished: bool,
    /// Speech-codec frames decoded in this call (spec 008 FR-008); 0 with the codec bypassed.
    /// Appended in 0.8.
    pub frames: usize,
    /// The index (0-based) of the frame whose decoded samples are entering the playback path at
    /// the end of the call, held at the last frame during the drain; 0 with the codec bypassed
    /// (spec 008 FR-008). Appended in 0.8 (the struct grows 16 → 32 bytes on 64-bit targets).
    /// Since 0.13 it is ⌊place ÷ 120⌋ with the codec on (the same values at speed level 3).
    pub frame_index: u64,
    /// The place in the recording, in whole stored device samples, of the last device sample
    /// computed in this call (the playback speed control's place), and the recording's length
    /// once the place has reached its end; 0 before any (spec 013 FR-009). Appended in 0.13 (the struct grows 32 → 40 bytes
    /// on 64-bit targets: rebuild against this header).
    pub place: u64,
}

/// How the memory stores recordings, from `rr_dr60_get_encoding` (spec 008 FR-010, FR-012),
/// passed as `uint32_t`; the values are the exported form's encoding field.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Encoding {
    /// Speech-codec frames (the codec on, the default).
    Frames = 1,
    /// Device-rate samples (the codec bypassed: not a device configuration).
    Samples = 2,
}

/// The speech codec's constants, from `rr_dr60_speech_codec_info` (spec 008 FR-003, FR-008):
/// the same layout as the Rust `SpeechCodecInfo` (24 bytes).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60SpeechCodecInfo {
    /// Device samples per frame: 120 (20 ms; A-040).
    pub frame_samples: u32,
    /// Frame length in milliseconds: 20.
    pub frame_ms: u32,
    /// Bits per frame: 80 (50 frames/s × 80 = 4000 bit/s, S-002).
    pub bits_per_frame: u32,
    /// The codec's delay in device samples: 180 (30 ms), carried by the record path and the
    /// one-pass processing (spec 008 FR-004).
    pub delay_samples: u32,
    /// The codec model version (major, minor, patch) the exported form carries (spec 008
    /// FR-010, FR-011).
    pub model_version: [u16; 3],
    /// Reserved; 0.
    pub reserved: u16,
}

// spec 008 contracts/c-api.md: the C mirror and the Rust struct share one layout.
const _: () = assert!(size_of::<RrDr60SpeechCodecInfo>() == 24);
const _: () = assert!(
    size_of::<RrDr60SpeechCodecInfo>() == size_of::<rr_dr60::speech_codec::SpeechCodecInfo>()
);

/// The memory's figures, from `rr_dr60_memory_status` (spec 006 FR-011), in device samples:
/// divide by 6000 for seconds (A-026); C has no seconds helpers.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RrDr60MemoryStatus {
    /// The configured capacity (`memory_capacity_s` × 6000).
    pub capacity_samples: u64,
    /// Device samples stored, the recording in progress included.
    pub used_samples: u64,
    /// `capacity_samples − used_samples`.
    pub remaining_samples: u64,
    /// The configured recording count.
    pub max_recordings: u32,
    /// Recordings in the memory (the one in progress not counted).
    pub count: u32,
    /// `max_recordings − count`.
    pub slots_remaining: u32,
}

/// Pipeline settings. Start from `rr_dr60_settings_default` and change fields as needed.
///
/// Levels use the AES17 convention (a full-scale sine is 0 dBFS; full scale is the codec's,
/// A-030). AGC ranges are inclusive; out-of-range or non-finite values are rejected even when
/// the AGC is off. Layout (0.6, 88 bytes): the 0.5 offsets are kept (`agc_knee_dbfs` at 28,
/// the two reserved slots at 32 and 36, `adc_clamp_enabled` at 72) and the two memory fields
/// are appended at 76 and 80 (spec 006 contracts/c-api.md).
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RrDr60Settings {
    /// Must be `sizeof(RrDr60Settings)`: 120 since 0.12 (112 in 0.10 and 0.11, 104 in 0.9, 96 in 0.8, 88 in 0.6 and 0.7, 80 in
    /// 0.5, 72 in 0.3 and 0.4, rejected as `STRUCT_SIZE`). Lets the struct grow in later
    /// versions.
    pub struct_size: u32,
    /// Host sample rate in Hz: 6000, 8000, 16000, 44100, 48000, 88200 or 96000 (spec 004
    /// FR-002; 6000 is the device rate, A-026, and needs no rate conversion).
    pub host_rate_hz: u32,
    /// Signal-chain stage 4 on (true, default) or bypassed.
    pub record_stage_enabled: bool,
    /// Signal-chain stage 10 on (true, default) or bypassed.
    pub playback_stage_enabled: bool,
    /// An `RrDr60Tap` value.
    pub tap: u32,
    /// Seed for stochastic stages: since 0.12 the capsule's hiss (stage 1; spec 012 FR-009,
    /// A-049), one deterministic stream per recording keyed by the seed and the recording
    /// counter. No effect with `mic_capsule_enabled` false.
    pub seed: u64,
    /// Signal-chain stage 3 (the limiter) on (true, default; assumed always active, A-020) or
    /// bypassed. Below its knee the limiter is the identity; above it the output is held at the
    /// knee level after a dead time of a few ms (spec 005; modeled on the circuit, A-028).
    pub agc_enabled: bool,
    /// The limiter's knee in dBFS: where it begins to act and the level it holds. Default -1,
    /// just below the codec's full scale (A-028). Range -40 to 3. (Offset 28; was
    /// `agc_target_dbfs` in 0.4.)
    pub agc_knee_dbfs: f32,
    /// Ignored; reserved since 0.5 (was `agc_max_gain_db`). Write 0.
    pub reserved_agc_1: f32,
    /// Ignored; reserved since 0.5 (was `agc_max_attenuation_db`). Write 0.
    pub reserved_agc_2: f32,
    /// Attack as the dead time, in ms, at 10 dB over the knee: how long a loud onset passes at
    /// full level before the limiter acts. Default 3 (A-034). Range 1 to 50.
    pub agc_attack_ms: f32,
    /// Release, in ms: time to return within 1 dB of unity from 10 dB of attenuation. Default
    /// 1370 (A-035). Range 200 to 10000.
    pub agc_release_ms: f32,
    /// Signal-chain stage 5 (VAS) on (true, default; the device has no VAS switch, S-001, A-008)
    /// or bypassed.
    pub vas_enabled: bool,
    /// An `RrDr60VasMode` value. Default `RR_DR60_VAS_MODE_DROP`: paused audio is removed, so
    /// read `RrDr60BlockInfo.produced`.
    pub vas_mode: u32,
    /// Microphone sensitivity level. Default 3 (S-001, A-021). Range 1 to 5. Moves only the VAS
    /// threshold in this version, 3 dB per level (A-022).
    pub vas_sensitivity: u32,
    /// VAS threshold at sensitivity 3, dBFS (sine peak). Default -40 (A-022, revised by spec
    /// 005). Range -60 to 0.
    pub vas_threshold_dbfs: f32,
    /// VAS hang time in ms. Default 1000 (A-023). Range 50 to 10000.
    pub vas_hang_ms: f32,
    /// VAS onset time in ms. Default 20 (A-024). Range 0 to 200.
    pub vas_onset_ms: f32,
    /// The ADC's full-scale clamp after stage 4: output beyond ±1.0 is saturated (true,
    /// default; A-030) or passed unchanged. Appended in 0.5 at offset 72 (spec 005 FR-008).
    pub adc_clamp_enabled: bool,
    /// The memory's capacity in seconds of recorded device time. Default 3600 (S-001: 60
    /// minutes). Range 1 to 86 400; above 3600 is not the device's. Appended in 0.6 at offset
    /// 76 (spec 006 FR-010).
    pub memory_capacity_s: u32,
    /// The most recordings the memory holds. Default 99 (S-001). Range 1 to 9 999. Appended in
    /// 0.6 at offset 80 (spec 006 FR-010).
    pub memory_max_recordings: u32,
    /// Ignored; reserved since 0.8 (it fills the 0.7 layout's tail padding so that the next field
    /// sits at offset 88). Write 0.
    pub reserved_008: u32,
    /// Signal-chain stages 7 and 9, the speech codec (encoder and decoder together), on (true,
    /// default; the device has no bypass, A-004) or bypassed. Also fixes the memory's encoding:
    /// frames when on, device-rate samples when bypassed (spec 008 FR-002, FR-012). Appended in
    /// 0.8 at offset 88.
    pub speech_codec_enabled: bool,
    /// Ignored; reserved since 0.9 (the 0.8 layout's tail padding, offsets 89 – 95, kept empty
    /// so that a 0.8 caller's `struct_size = 96` is refused instead of reading settings from
    /// uninitialized bytes). Write 0.
    pub reserved_009: [u8; 7],
    /// Signal-chain stage 11, the volume control and power amplifier, on (true, default; A-031)
    /// or bypassed (unity gain at the codec's scale; the volume position retained and ignored).
    /// Appended in 0.9 at offset 96 (spec 009 FR-002, FR-014).
    pub output_volume_amp_enabled: bool,
    /// Signal-chain stage 12, a template of a small speaker (A-010, low confidence), on (true,
    /// default) or bypassed. Appended in 0.9 at offset 97.
    pub output_speaker_enabled: bool,
    /// Signal-chain stage 13, the earphone output's two coupling corners (A-032), on (true,
    /// default) or bypassed. Appended in 0.9 at offset 98.
    pub output_earphone_enabled: bool,
    /// Ignored; reserved since 0.10 (the 0.9 layout's tail padding, offsets 99 – 103, made
    /// explicit so that a 0.9 caller's `struct_size = 104` is refused instead of the option
    /// being read from uninitialized bytes; spec 010 FR-008). Write 0.
    pub reserved_010: [u8; 5],
    /// The **output clamp** (spec 010 FR-001): when `true`, every sample at
    /// `RR_DR60_TAP_ROUTE_OUTPUT` above +1.0 is replaced by +1.0 and every sample below −1.0 by
    /// −1.0 (the route's full scale, A-042), on both routes, also when every output stage is
    /// bypassed; the play calls always return the route output, so they are always bounded.
    /// The taps after stages 11, 12 and 13, `RR_DR60_TAP_AFTER_PLAYBACK` and every earlier tap
    /// are never bounded. **Off by default** (`false`): an emulator convenience, not a device
    /// behavior, for hosts writing integer buffers (+1.0 maps to 32767 in a 16-bit conversion);
    /// on material above the bound it adds distortion of its own that the device does not
    /// have. Appended in 0.10 at offset 104.
    pub output_clamp_enabled: bool,
    /// Ignored; reserved since 0.10 (this layout's tail, offsets 105 – 111, explicit so that
    /// the next version can append at 112 and refuse 112). Write 0.
    pub reserved_010_tail: [u8; 7],
    /// Signal-chain stage 1, the capsule's self-noise (the hiss, A-048), on (true, default) or
    /// bypassed (spec 012). Appended in 0.12 at offset 112.
    pub mic_capsule_enabled: bool,
    /// Signal-chain stage 2, the microphone amplifier (the input high-pass, the clipper, the
    /// output coupling and the roll-off; A-046, A-047, A-051), on (true, default) or bypassed
    /// (spec 012). Appended in 0.12 at offset 113.
    pub mic_amp_enabled: bool,
    /// Ignored; reserved since 0.12 (offsets 114 – 115, explicit). Write 0.
    pub reserved_012: [u8; 2],
    /// The hiss level offset in dB, −18 to +12, default 0 (spec 012 FR-003); validated whether
    /// or not the capsule is on. Appended in 0.12 at offset 116.
    pub mic_hiss_offset_db: f32,
}

// spec 006 contracts/c-api.md: the 0.6 layout is 88 bytes; the 0.5 offsets are kept and the two
// memory fields sit at 76 and 80 (the unit tests assert every offset).
const _: () = assert!(size_of::<RrDr60Settings>() == 120); // spec 012 contracts/c-api.md: 112 → 120
// Spec 010 FR-008: the struct is 8-aligned (`seed: u64`); the explicit tail ends it, so no
// implicit padding can hide a stale caller's uninitialized byte again.
const _: () = assert!(align_of::<RrDr60Settings>() == 8);
const _: () = assert!(core::mem::offset_of!(RrDr60Settings, reserved_010_tail) + 7 == 112);
// Spec 012 contracts/c-api.md: the 0.12 fields at their recorded offsets, the f32 ending the
// struct with no implicit padding.
const _: () = assert!(core::mem::offset_of!(RrDr60Settings, mic_capsule_enabled) == 112);
const _: () = assert!(core::mem::offset_of!(RrDr60Settings, mic_amp_enabled) == 113);
const _: () = assert!(core::mem::offset_of!(RrDr60Settings, reserved_012) == 114);
const _: () = assert!(core::mem::offset_of!(RrDr60Settings, mic_hiss_offset_db) == 116);
const _: () = assert!(
    core::mem::offset_of!(RrDr60Settings, mic_hiss_offset_db) + 4 == size_of::<RrDr60Settings>()
);
// spec 003 contracts/c-api.md: the C event type and the core's `repr(C)` `VasEvent` share one
// layout, so `rr_dr60_process_with_events` can pass the caller's buffer straight through.
const _: () = assert!(
    size_of::<VasEvent>() == size_of::<RrDr60VasEvent>()
        && align_of::<VasEvent>() == align_of::<RrDr60VasEvent>()
        && size_of::<ChangeEntry>() == size_of::<RrDr60ChangeEntry>()
        && align_of::<ChangeEntry>() == align_of::<RrDr60ChangeEntry>()
        && size_of::<RrDr60ChangeEntry>() == 40
);

/// Opaque pipeline handle.
pub struct RrDr60Pipeline {
    inner: Pipeline,
    poisoned: bool,
    /// `paused` from the last processed block, reported by calls that return early.
    last_paused: bool,
    #[cfg(feature = "ffi-test-panic")]
    force_panic: bool,
}

const SETTINGS_SIZE: u32 = size_of::<RrDr60Settings>() as u32;

/// Checks `struct_size` before anything else is read, and only then forms a reference to the
/// whole struct. A caller built against an older, smaller layout passes a smaller `struct_size`
/// (contract rule 5), and the memory past its struct may not be readable, so the first field is
/// read on its own through the raw pointer.
///
/// # Safety
///
/// `settings` must be non-null and point to at least a readable `u32` at offset 0; when that
/// value is at least `sizeof(RrDr60Settings)`, the whole struct must be valid.
unsafe fn check_struct_size<'a>(
    settings: *const RrDr60Settings,
) -> Result<&'a RrDr60Settings, (RrDr60Status, RrDr60SettingField)> {
    // SAFETY: `struct_size` is the first field of a `repr(C)` struct, so it sits at offset 0,
    // and the caller guarantees that much is readable. `read_unaligned` makes no alignment
    // assumption about the caller's storage.
    let size = unsafe { settings.cast::<u32>().read_unaligned() };
    if size < SETTINGS_SIZE {
        return Err((
            RrDr60Status::InvalidArgument,
            RrDr60SettingField::StructSize,
        ));
    }
    // SAFETY: the caller's struct is at least as large as ours, and the caller guarantees it is
    // valid; no mutable reference to it exists during the call.
    Ok(unsafe { &*settings })
}

/// Maps a caught panic to a status (contract rule 1). Every entry point routes its panic
/// arm through here; the `ffi-test-panic` tests exercise it.
fn panic_to_status(pipeline: Option<&mut RrDr60Pipeline>) -> RrDr60Status {
    if let Some(p) = pipeline {
        p.poisoned = true;
    }
    RrDr60Status::InternalError
}

fn status_from_error(e: Error) -> RrDr60Status {
    error_to_status_and_field(e).0
}

/// Maps a core error to the C status and the field it names (spec 002 R-09).
fn error_to_status_and_field(e: Error) -> (RrDr60Status, RrDr60SettingField) {
    match e {
        Error::UnsupportedHostRate { .. } => (
            RrDr60Status::UnsupportedHostRate,
            RrDr60SettingField::HostRate,
        ),
        Error::InvalidSetting { setting } => {
            let field = match setting {
                Setting::AgcKneeDbfs => RrDr60SettingField::AgcKneeDbfs,
                Setting::AgcAttackMs => RrDr60SettingField::AgcAttackMs,
                Setting::AgcReleaseMs => RrDr60SettingField::AgcReleaseMs,
                Setting::VasSensitivity => RrDr60SettingField::VasSensitivity,
                Setting::VasThresholdDbfs => RrDr60SettingField::VasThresholdDbfs,
                Setting::VasHangMs => RrDr60SettingField::VasHangMs,
                Setting::VasOnsetMs => RrDr60SettingField::VasOnsetMs,
                Setting::MemoryCapacityS => RrDr60SettingField::MemoryCapacityS,
                Setting::MemoryMaxRecordings => RrDr60SettingField::MemoryMaxRecordings,
                Setting::MicHissOffsetDb => RrDr60SettingField::MicHissOffsetDb, // 012 FR-012
                _ => RrDr60SettingField::None,
            };
            (RrDr60Status::InvalidSetting, field)
        }
        // Spec 006 contracts/c-api.md: statuses 6–19, one per refusal reason.
        Error::RecordingInProgress => (RrDr60Status::RecordingInProgress, RrDr60SettingField::None),
        Error::PlaybackInProgress => (RrDr60Status::PlaybackInProgress, RrDr60SettingField::None),
        Error::NotRecording => (RrDr60Status::NotRecording, RrDr60SettingField::None),
        Error::NotPlaying => (RrDr60Status::NotPlaying, RrDr60SettingField::None),
        Error::MemoryFull => (RrDr60Status::MemoryFull, RrDr60SettingField::None),
        Error::NoRecordingSlots => (RrDr60Status::NoRecordingSlots, RrDr60SettingField::None),
        Error::NoSuchRecording { .. } => (RrDr60Status::NoSuchRecording, RrDr60SettingField::None),
        Error::DoesNotFit => (RrDr60Status::DoesNotFit, RrDr60SettingField::None),
        Error::UnknownForm => (RrDr60Status::UnknownForm, RrDr60SettingField::None),
        Error::UnsupportedFormVersion { .. } => (
            RrDr60Status::UnsupportedFormVersion,
            RrDr60SettingField::None,
        ),
        Error::Damaged => (RrDr60Status::Damaged, RrDr60SettingField::None),
        Error::StoredExceedsCapacity => (
            RrDr60Status::StoredExceedsCapacity,
            RrDr60SettingField::None,
        ),
        Error::AllocationFailed => (RrDr60Status::AllocationFailed, RrDr60SettingField::None),
        Error::BufferTooSmall { .. } => (RrDr60Status::BufferTooSmall, RrDr60SettingField::None),
        // Spec 008 contracts/c-api.md: statuses 21 and 22.
        Error::EncodingDiffers => (RrDr60Status::EncodingDiffers, RrDr60SettingField::None),
        Error::UnsupportedCodecModelVersion { .. } => (
            RrDr60Status::UnsupportedCodecModelVersion,
            RrDr60SettingField::None,
        ),
        // Spec 009 contracts/c-api.md: statuses 23 and 24.
        Error::InvalidVolume { .. } => (RrDr60Status::InvalidVolume, RrDr60SettingField::None),
        Error::TapNotOnRoute { .. } => (RrDr60Status::TapNotOnRoute, RrDr60SettingField::None),
        // Spec 015 contracts/api.md: statuses 27 – 28; a bad route value is an argument error.
        Error::ScheduleFull { .. } => (RrDr60Status::ScheduleFull, RrDr60SettingField::None),
        Error::ControlNotOnStream { .. } | Error::ReservedStream { .. } => {
            (RrDr60Status::ControlNotOnStream, RrDr60SettingField::None)
        }
        Error::InvalidControlValue { .. } => {
            (RrDr60Status::InvalidArgument, RrDr60SettingField::None)
        }
        // Spec 017 contracts/api.md: status 29; a bad control index is the manifest's status.
        Error::NoSuchClock { .. } => (RrDr60Status::NoSuchClock, RrDr60SettingField::None),
        Error::InvalidBatteryVolts { .. } => {
            (RrDr60Status::InvalidBatteryVolts, RrDr60SettingField::None) // spec 018
        }
        // Spec 020 contracts/api.md: statuses 31 – 35.
        Error::UnknownRecordVersion { .. } => {
            (RrDr60Status::UnknownRecordVersion, RrDr60SettingField::None)
        }
        Error::MalformedRecord { .. } => (RrDr60Status::MalformedRecord, RrDr60SettingField::None),
        Error::MissingRecordField { .. } => {
            (RrDr60Status::MissingRecordField, RrDr60SettingField::None)
        }
        Error::RecordChecksumMismatch => {
            (RrDr60Status::RecordChecksumMismatch, RrDr60SettingField::None)
        }
        Error::InconsistentRun { .. } => (RrDr60Status::InconsistentRun, RrDr60SettingField::None),
        Error::NoSuchControl { .. } => (RrDr60Status::NoSuchControl, RrDr60SettingField::None),
        // Spec 013 contracts/c-api.md: status 25.
        Error::InvalidSpeedLevel { .. } => {
            (RrDr60Status::InvalidSpeedLevel, RrDr60SettingField::None)
        }
        _ => (RrDr60Status::InvalidArgument, RrDr60SettingField::None),
    }
}

/// The one validator behind `rr_dr60_create`, `rr_dr60_reconfigure` and
/// `rr_dr60_settings_validate`, so their status and named field always agree (spec 002 R-09).
/// Order: struct size → tap → VAS mode → host rate → AGC fields → VAS fields, in struct order.
fn validate_c(s: &RrDr60Settings) -> Result<Settings, (RrDr60Status, RrDr60SettingField)> {
    if s.struct_size < SETTINGS_SIZE {
        return Err((
            RrDr60Status::InvalidArgument,
            RrDr60SettingField::StructSize,
        ));
    }
    let settings = to_settings(s)?;
    settings.validate().map_err(error_to_status_and_field)?;
    Ok(settings)
}

/// Converts C settings to Rust settings, validating `struct_size`, `tap` and `vas_mode`, and
/// naming the failing field (spec 003 contracts/c-api.md › Conversion rules). The two reserved
/// AGC slots are ignored (spec 005 contracts/c-api.md).
fn to_settings(s: &RrDr60Settings) -> Result<Settings, (RrDr60Status, RrDr60SettingField)> {
    let invalid = |field| (RrDr60Status::InvalidArgument, field);
    if s.struct_size < SETTINGS_SIZE {
        return Err(invalid(RrDr60SettingField::StructSize));
    }
    let tap = match s.tap {
        0 => Tap::AfterRecord,
        1 => Tap::AfterPlayback,
        2 => Tap::AfterAgc,
        3 => Tap::AfterVas,
        4 => Tap::AfterDecoder,
        5 => Tap::RouteOutput,
        6 => Tap::AfterVolumeAmp,
        7 => Tap::AfterSpeaker,
        8 => Tap::AfterEarphone,
        9 => Tap::AfterMicCapsule, // 012 FR-012
        10 => Tap::AfterMicAmp,    // 012 FR-012
        _ => return Err(invalid(RrDr60SettingField::Tap)),
    };
    let vas_mode = match s.vas_mode {
        0 => VasMode::Drop,
        1 => VasMode::Mute,
        _ => return Err(invalid(RrDr60SettingField::VasMode)),
    };
    let mut out = Settings::new(s.host_rate_hz);
    out.record_stage_enabled = s.record_stage_enabled;
    out.playback_stage_enabled = s.playback_stage_enabled;
    out.adc_clamp_enabled = s.adc_clamp_enabled;
    out.tap = tap;
    out.seed = s.seed;
    out.agc.enabled = s.agc_enabled;
    out.agc.knee_dbfs = s.agc_knee_dbfs;
    out.agc.attack_ms = s.agc_attack_ms;
    out.agc.release_ms = s.agc_release_ms;
    out.vas.enabled = s.vas_enabled;
    out.vas.mode = vas_mode;
    // A value such as 259 must not wrap to a valid level (spec 003 plan review, finding 8).
    out.vas.sensitivity = u8::try_from(s.vas_sensitivity).unwrap_or(u8::MAX);
    out.vas.threshold_dbfs = s.vas_threshold_dbfs;
    out.vas.hang_ms = s.vas_hang_ms;
    out.vas.onset_ms = s.vas_onset_ms;
    out.memory.capacity_s = s.memory_capacity_s;
    out.memory.max_recordings = s.memory_max_recordings;
    out.speech_codec_enabled = s.speech_codec_enabled;
    out.output.volume_amp_enabled = s.output_volume_amp_enabled; // 009 FR-002
    out.output.speaker_enabled = s.output_speaker_enabled;
    out.output.earphone_enabled = s.output_earphone_enabled;
    out.output.clamp_enabled = s.output_clamp_enabled; // 010 FR-008
    out.mic.capsule_enabled = s.mic_capsule_enabled; // 012 FR-012
    out.mic.amp_enabled = s.mic_amp_enabled;
    out.mic.hiss_offset_db = s.mic_hiss_offset_db;
    Ok(out)
}

/// Default settings for `host_rate_hz` (not validated): the limiter and the VAS on with the
/// modeled device values, both band-limit stages and the ADC clamp on, the speech codec on,
/// the output chain on, the tap at the route output (`RR_DR60_TAP_ROUTE_OUTPUT`, since 0.9;
/// 0.8's output is `RR_DR60_TAP_AFTER_PLAYBACK`), seed 0, the reserved slots 0, the memory at
/// the device's 60 minutes and 99 recordings. Never fails.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_settings_default(host_rate_hz: u32) -> RrDr60Settings {
    let agc = rr_dr60::AgcSettings::DEVICE; // A-020, A-028, A-034, A-035
    let vas = rr_dr60::VasSettings::DEVICE; // S-001, A-008, A-021 – A-024 (A-022 revised)
    let memory = rr_dr60::MemorySettings::DEVICE; // S-001: 60 min, 99 items (006 FR-010)
    let defaults = Settings::new(host_rate_hz);
    RrDr60Settings {
        struct_size: SETTINGS_SIZE,
        host_rate_hz,
        record_stage_enabled: defaults.record_stage_enabled,
        playback_stage_enabled: defaults.playback_stage_enabled,
        tap: RrDr60Tap::RouteOutput as u32, // 009 FR-010
        seed: 0,
        agc_enabled: agc.enabled,
        agc_knee_dbfs: agc.knee_dbfs,
        reserved_agc_1: 0.0,
        reserved_agc_2: 0.0,
        agc_attack_ms: agc.attack_ms,
        agc_release_ms: agc.release_ms,
        vas_enabled: vas.enabled,
        vas_mode: RrDr60VasMode::Drop as u32,
        vas_sensitivity: u32::from(vas.sensitivity),
        vas_threshold_dbfs: vas.threshold_dbfs,
        vas_hang_ms: vas.hang_ms,
        vas_onset_ms: vas.onset_ms,
        adc_clamp_enabled: defaults.adc_clamp_enabled, // A-030
        memory_capacity_s: memory.capacity_s,
        memory_max_recordings: memory.max_recordings,
        reserved_008: 0,
        speech_codec_enabled: defaults.speech_codec_enabled, // A-004 adopted (008 FR-002)
        reserved_009: [0; 7],
        output_volume_amp_enabled: defaults.output.volume_amp_enabled, // A-031 (009 FR-002)
        output_speaker_enabled: defaults.output.speaker_enabled,       // A-010 (009 FR-002)
        output_earphone_enabled: defaults.output.earphone_enabled,     // A-032 (009 FR-002)
        reserved_010: [0; 5],
        output_clamp_enabled: defaults.output.clamp_enabled, // false (010 FR-002)
        reserved_010_tail: [0; 7],
        mic_capsule_enabled: defaults.mic.capsule_enabled, // A-048 (012 FR-012)
        mic_amp_enabled: defaults.mic.amp_enabled,         // A-046, A-047, A-051 (012 FR-012)
        reserved_012: [0; 2],
        mic_hiss_offset_db: defaults.mic.hiss_offset_db, // 0 (012 FR-003)
    }
}

/// Creates a pipeline. On success, writes the new handle to `*out_pipeline`. Not real-time
/// safe (allocates).
///
/// # Safety
///
/// `settings` must be NULL or point to a valid `RrDr60Settings`. `out_pipeline` must be NULL
/// or point to writable storage for one pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_create(
    settings: *const RrDr60Settings,
    out_pipeline: *mut *mut RrDr60Pipeline,
) -> RrDr60Status {
    if settings.is_null() || out_pipeline.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: checked non-null above; the caller guarantees it points to a valid struct of at
    // least its own `struct_size`.
    let settings = match unsafe { check_struct_size(settings) } {
        Ok(s) => s,
        Err((status, _)) => return status,
    };
    let result = catch_unwind(|| {
        let s = validate_c(settings).map_err(|(status, _)| status)?;
        let inner = Pipeline::new(s).map_err(status_from_error)?;
        Ok(Box::new(RrDr60Pipeline {
            inner,
            poisoned: false,
            last_paused: false,
            #[cfg(feature = "ffi-test-panic")]
            force_panic: false,
        }))
    });
    match result {
        Ok(Ok(handle)) => {
            // SAFETY: out_pipeline is non-null and writable (caller contract).
            unsafe { *out_pipeline = Box::into_raw(handle) };
            RrDr60Status::Ok
        }
        Ok(Err(status)) => status,
        Err(_) => panic_to_status(None),
    }
}

/// Destroys a pipeline. NULL is a no-op.
///
/// # Safety
///
/// `pipeline` must be NULL or a handle from `rr_dr60_create` that has not been destroyed.
/// It must not be used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_destroy(pipeline: *mut RrDr60Pipeline) {
    if !pipeline.is_null() {
        // SAFETY: the handle came from Box::into_raw in rr_dr60_create (caller contract).
        drop(unsafe { Box::from_raw(pipeline) });
    }
}

/// Writes `info` to `out_info` unless it is NULL.
///
/// # Safety
///
/// `out_info` must be NULL or writable.
unsafe fn put_info(out_info: *mut RrDr60BlockInfo, info: RrDr60BlockInfo) {
    if !out_info.is_null() {
        // SAFETY: non-null and writable (caller contract).
        unsafe { *out_info = info };
    }
}

fn c_info(info: BlockInfo) -> RrDr60BlockInfo {
    RrDr60BlockInfo {
        produced: info.produced,
        events: info.events,
        paused: info.paused,
        frames: info.frames,
    }
}

/// Processes `frames` samples from `input` into `output`. Real-time safe.
///
/// Only `output[0 .. produced)` holds output: with the VAS in drop mode (the default), pauses
/// are removed, so `produced` can be smaller than `frames`, or 0 (spec 003 FR-004).
/// `out_info` may be NULL. When it is not, it is always written: on an error, a poisoned handle
/// or `frames == 0` it gets `produced = 0`, `events = 0` and the current `paused` value
/// (`false` for a NULL handle).
///
/// `input == output` processes in place. Any other overlap returns
/// [`RrDr60Status::InvalidArgument`]. With `frames == 0`, both buffers may be NULL.
///
/// # Safety
///
/// `pipeline` must be a live handle. When `frames > 0`, `input` must be readable and
/// `output` writable for `frames` floats. `out_info` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_process(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60BlockInfo,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `process_block`, with no events.
    unsafe {
        process_block(
            pipeline,
            input,
            output,
            frames,
            out_info,
            std::ptr::null_mut(),
            0,
            std::ptr::null_mut(),
            0,
            std::ptr::null_mut(),
        )
    }
}

/// As `rr_dr60_process`, and writes the block's VAS events (splices in drop mode, muted
/// regions in mute mode) to `events`: the first `events_capacity` of them, in order.
/// `out_info->events` counts all of them, so a count above `events_capacity` means some were
/// not written; `rr_dr60_max_events` gives a capacity that is always enough. `events` may be
/// NULL only when `events_capacity` is 0. Real-time safe (spec 003 FR-005, FR-014).
///
/// # Safety
///
/// As `rr_dr60_process`; additionally, when `events_capacity > 0`, `events` must be writable
/// for that many `RrDr60VasEvent` values.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_process_with_events(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60BlockInfo,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `process_block`.
    unsafe {
        process_block(
            pipeline,
            input,
            output,
            frames,
            out_info,
            events,
            events_capacity,
            std::ptr::null_mut(),
            0,
            std::ptr::null_mut(),
        )
    }
}

/// As `rr_dr60_process_with_events`, and writes the control changes the one-pass stream
/// applied in this call to `changes`: the first `changes_capacity` of them, in order, each an
/// `RrDr60ChangeEntry` at the output index it landed on (spec 015 FR-005); `*out_change_count`
/// (NULL allowed) receives how many the call applied, so a count above `changes_capacity` means
/// some were not written; `RR_DR60_MAX_CHANGES_PER_CALL` is always enough. `changes` may be
/// NULL only when `changes_capacity` is 0. Real-time safe.
///
/// # Safety
///
/// As `rr_dr60_process_with_events`; additionally, when `changes_capacity > 0`, `changes`
/// must be writable for that many `RrDr60ChangeEntry` values, and `out_change_count` must be
/// NULL or writable.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)] // the C surface: two caller buffers with their capacities and the count
pub unsafe extern "C" fn rr_dr60_process_with_events_and_changes(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60BlockInfo,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
    changes: *mut RrDr60ChangeEntry,
    changes_capacity: usize,
    out_change_count: *mut usize,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `process_block`.
    unsafe {
        process_block(
            pipeline,
            input,
            output,
            frames,
            out_info,
            events,
            events_capacity,
            changes,
            changes_capacity,
            out_change_count,
        )
    }
}

/// Writes to `*out_capacity` an `events_capacity` that is always enough for a block of `frames`
/// input samples with the pipeline's current settings (spec 003 research R-07). Never
/// allocates; real-time safe. On a non-OK status `*out_capacity` is untouched (rule 2).
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_capacity` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_max_events(
    pipeline: *const RrDr60Pipeline,
    frames: usize,
    out_capacity: *mut usize,
) -> RrDr60Status {
    if pipeline.is_null() || out_capacity.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    // SAFETY: out_capacity is non-null and writable (caller contract).
    unsafe { *out_capacity = p.inner.max_events(frames) };
    RrDr60Status::Ok
}

/// The one block loop behind `rr_dr60_process` and `rr_dr60_process_with_events`.
///
/// # Safety
///
/// As `rr_dr60_process_with_events`.
#[allow(clippy::too_many_arguments)] // the one-pass call's full surface (events and changes)
unsafe fn process_block(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60BlockInfo,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
    changes: *mut RrDr60ChangeEntry,
    changes_capacity: usize,
    out_change_count: *mut usize,
) -> RrDr60Status {
    if pipeline.is_null() {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put_info(out_info, RrDr60BlockInfo::default()) };
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract); no other reference exists during the call.
    let p = unsafe { &mut *pipeline };
    let idle = RrDr60BlockInfo {
        paused: p.last_paused,
        ..RrDr60BlockInfo::default()
    };
    let early = |status| {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put_info(out_info, idle) };
        status
    };
    if p.poisoned {
        return early(RrDr60Status::InternalError);
    }
    if frames == 0 {
        return early(RrDr60Status::Ok);
    }
    // The one-pass is refused while a recording or playback is in progress (spec 006 FR-009):
    // the Rust in-place calls produce nothing, so the C status must carry the reason.
    match p.inner.state().state {
        State::Recording => return early(RrDr60Status::RecordingInProgress),
        State::Playing => return early(RrDr60Status::PlaybackInProgress),
        _ => {}
    }
    // Spec 009 FR-011: a named route tap with the other route selected is refused before
    // anything runs (the in-place core call has no error channel, so the check is here).
    if matches!(
        (p.inner.settings().tap, p.inner.route()),
        (Tap::AfterSpeaker, Route::Earphone) | (Tap::AfterEarphone, Route::Speaker)
    ) {
        return early(RrDr60Status::TapNotOnRoute);
    }
    if input.is_null()
        || output.is_null()
        || (events.is_null() && events_capacity > 0)
        || (changes.is_null() && changes_capacity > 0)
    {
        return early(RrDr60Status::NullPointer);
    }
    let (in_start, out_start) = (input as usize, output as usize);
    let bytes = frames.saturating_mul(size_of::<f32>());
    let in_place = in_start == out_start;
    if !in_place
        && in_start < out_start.saturating_add(bytes)
        && out_start < in_start.saturating_add(bytes)
    {
        return early(RrDr60Status::InvalidArgument);
    }
    let result = catch_unwind(AssertUnwindSafe(|| {
        #[cfg(feature = "ffi-test-panic")]
        if p.force_panic {
            p.force_panic = false;
            panic!("rr_dr60__test_force_panic");
        }
        // SAFETY: `VasEvent` is `repr(C)` with the same two `u64` fields in the same order as
        // `RrDr60VasEvent`, so their layouts are identical (checked by the const assert below
        // `RrDr60Settings`); the slice is rebuilt from the caller's storage, which is writable
        // for `events_capacity` values (or empty).
        let slots: &mut [VasEvent] = if events_capacity == 0 {
            &mut []
        } else {
            unsafe { std::slice::from_raw_parts_mut(events.cast::<VasEvent>(), events_capacity) }
        };
        // SAFETY: `ChangeEntry` is `repr(C)` with the layout of `RrDr60ChangeEntry` (the const
        // assert below `RrDr60Settings`); the slice is the caller's storage, writable for
        // `changes_capacity` values (or empty).
        let log: &mut [ChangeEntry] = if changes_capacity == 0 {
            &mut []
        } else {
            unsafe {
                std::slice::from_raw_parts_mut(changes.cast::<ChangeEntry>(), changes_capacity)
            }
        };
        if in_place {
            // SAFETY: output is non-null and writable for `frames` floats; it is the only
            // reference to that memory during the call.
            let buf = unsafe { std::slice::from_raw_parts_mut(output, frames) };
            p.inner
                .process_in_place_with_events_and_changes(buf, slots, log)
        } else {
            // SAFETY: both are non-null, valid for `frames` floats, and checked not to overlap.
            let (x, y) = unsafe {
                (
                    std::slice::from_raw_parts(input, frames),
                    std::slice::from_raw_parts_mut(output, frames),
                )
            };
            // Lengths are equal by construction, the transport is idle and the tap is on the
            // route (all checked above), so this cannot fail.
            p.inner
                .process_with_events_and_changes(x, y, slots, log)
                .unwrap_or_default()
        }
    }));
    match result {
        Ok(info) => {
            p.last_paused = info.paused;
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put_info(out_info, c_info(info)) };
            // SAFETY: out_change_count is NULL or writable (caller contract).
            unsafe { put(out_change_count, info.changes) };
            RrDr60Status::Ok
        }
        Err(_) => {
            let status = panic_to_status(Some(p));
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put_info(out_info, idle) };
            status
        }
    }
}

/// Writes the pipeline's fixed latency, in host-rate samples, to `*out_samples`.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_latency_samples(
    pipeline: *const RrDr60Pipeline,
    out_samples: *mut u32,
) -> RrDr60Status {
    if pipeline.is_null() || out_samples.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    // SAFETY: out_samples is non-null and writable (caller contract).
    unsafe { *out_samples = p.inner.latency_samples() };
    RrDr60Status::Ok
}

/// Returns the pipeline to idle with its path state cleared and clears a poisoned handle
/// (spec 006 FR-019): a recording in progress is discarded without flush, a playback stops
/// without drain, the memory's contents and the route are kept. Allowed in any state.
/// Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_reset(pipeline: *mut RrDr60Pipeline) -> RrDr60Status {
    if pipeline.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &mut *pipeline };
    match catch_unwind(AssertUnwindSafe(|| p.inner.reset())) {
        Ok(()) => {
            p.poisoned = false;
            p.last_paused = false;
            RrDr60Status::Ok
        }
        Err(_) => panic_to_status(Some(p)),
    }
}

/// Applies new settings and resets the path state; the memory's contents and the route are
/// kept (spec 006 FR-019). On success a poisoned handle becomes usable again. On error the
/// pipeline is unchanged. Not real-time safe (allocates).
///
/// Statuses: `RECORDING_IN_PROGRESS`, `PLAYBACK_IN_PROGRESS` (allowed only when idle);
/// `STORED_EXCEEDS_CAPACITY` when the stored recordings would not fit the new capacity;
/// `ALLOCATION_FAILED`; the settings statuses of `rr_dr60_create`.
///
/// # Safety
///
/// `pipeline` must be a live handle. `settings` must be NULL or point to a valid
/// `RrDr60Settings`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_reconfigure(
    pipeline: *mut RrDr60Pipeline,
    settings: *const RrDr60Settings,
) -> RrDr60Status {
    if pipeline.is_null() || settings.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null; the caller guarantees a valid struct of at least its own `struct_size`.
    let settings = match unsafe { check_struct_size(settings) } {
        Ok(s) => s,
        Err((status, _)) => return status,
    };
    // SAFETY: non-null live handle (caller contract); no other reference exists during the call.
    let p = unsafe { &mut *pipeline };
    let result = catch_unwind(AssertUnwindSafe(|| {
        let s = validate_c(settings).map_err(|(status, _)| status)?;
        p.inner.reconfigure(s).map_err(status_from_error)
    }));
    match result {
        Ok(Ok(())) => {
            p.poisoned = false;
            p.last_paused = false;
            RrDr60Status::Ok
        }
        Ok(Err(status)) => status,
        Err(_) => panic_to_status(Some(p)),
    }
}

/// Checks `settings` without creating a pipeline. Returns exactly the status
/// `rr_dr60_create` would return for them and, if `out_field` is not NULL, writes the field
/// at fault there (`RR_DR60_SETTING_FIELD_NONE` when the status is OK). Fields are checked in
/// the order struct size, tap, VAS mode, host rate, the AGC fields, then the VAS fields. Never allocates; real-time safe.
///
/// # Safety
///
/// `settings` must be NULL or point to a valid `RrDr60Settings`. `out_field` must be NULL or
/// writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_settings_validate(
    settings: *const RrDr60Settings,
    out_field: *mut RrDr60SettingField,
) -> RrDr60Status {
    if settings.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: checked non-null above; the caller guarantees a valid struct of at least its own
    // `struct_size`.
    let (status, field) = match unsafe { check_struct_size(settings) } {
        Err(fault) => fault,
        Ok(settings) => match catch_unwind(|| validate_c(settings)) {
            Ok(Ok(_)) => (RrDr60Status::Ok, RrDr60SettingField::None),
            Ok(Err(fault)) => fault,
            Err(_) => (panic_to_status(None), RrDr60SettingField::None),
        },
    };
    if !out_field.is_null() {
        // SAFETY: out_field is non-null and writable (caller contract).
        unsafe { *out_field = field };
    }
    status
}

// ---- Spec 006: the record and playback paths, the memory, the route, export and import
// (contracts/c-api.md). Every call: NULL handle → NULL_POINTER; poisoned → INTERNAL_ERROR; a
// caught panic poisons the handle; a non-OK status leaves the required out-parameters
// untouched, except the info structs, which are always written when not NULL.

/// Writes `value` to `out` unless it is NULL.
///
/// # Safety
///
/// `out` must be NULL or writable.
unsafe fn put<T>(out: *mut T, value: T) {
    if !out.is_null() {
        // SAFETY: non-null and writable (caller contract).
        unsafe { *out = value };
    }
}

/// The live handle, or the status for a NULL or poisoned one.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle, with no other reference during the call.
unsafe fn live<'a>(pipeline: *mut RrDr60Pipeline) -> Result<&'a mut RrDr60Pipeline, RrDr60Status> {
    if pipeline.is_null() {
        return Err(RrDr60Status::NullPointer);
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &mut *pipeline };
    if p.poisoned {
        return Err(RrDr60Status::InternalError);
    }
    Ok(p)
}

/// The caller's event buffer as the core's slice.
///
/// # Safety
///
/// When `events_capacity > 0`, `events` must be non-null and writable for that many values.
unsafe fn event_slots<'a>(
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
) -> &'a mut [VasEvent] {
    if events_capacity == 0 {
        &mut []
    } else {
        // SAFETY: the two types share one layout (the const assert below `RrDr60Settings`);
        // the storage is writable for `events_capacity` values (caller contract).
        unsafe { std::slice::from_raw_parts_mut(events.cast::<VasEvent>(), events_capacity) }
    }
}

/// Runs `f` on the pipeline with panics caught: a panic poisons the handle (rule 1).
fn guarded<T>(
    p: &mut RrDr60Pipeline,
    f: impl FnOnce(&mut Pipeline) -> Result<T, Error>,
) -> Result<T, RrDr60Status> {
    match catch_unwind(AssertUnwindSafe(|| f(&mut p.inner))) {
        Ok(r) => r.map_err(status_from_error),
        Err(_) => Err(panic_to_status(Some(p))),
    }
}

/// Test-only: whether the next call was asked to panic (`rr_dr60__test_force_panic`).
fn take_forced_panic(p: &mut RrDr60Pipeline) -> bool {
    #[cfg(feature = "ffi-test-panic")]
    {
        let forced = p.force_panic;
        p.force_panic = false;
        forced
    }
    #[cfg(not(feature = "ffi-test-panic"))]
    {
        let _ = p;
        false
    }
}

fn c_record_info(i: RecordInfo) -> RrDr60RecordInfo {
    RrDr60RecordInfo {
        stored: i.stored,
        events: i.events,
        paused: i.paused,
        stopped: i.stopped.is_some(),
        stop_reason: match i.stopped {
            Some(StopReason::MemoryFull) => RrDr60StopReason::MemoryFull as u32,
            _ => RrDr60StopReason::None as u32,
        },
        frames: i.frames,
        frames_total: i.frames_total,
    }
}

fn c_outcome(o: StopOutcome) -> RrDr60StopOutcome {
    let (kept, number, length_samples) = match o.result {
        StopResult::Kept { number, length } => (true, number, length),
        _ => (false, 0, 0),
    };
    RrDr60StopOutcome {
        flush: c_record_info(o.flush),
        kept,
        number,
        length_samples,
        silence_fed_samples: o.silence_fed_samples,
        stop_input_position: o.stop_input_position,
        padding_start_sample: o.padding_start_sample,
    }
}

fn c_play_info(i: PlayInfo) -> RrDr60PlayInfo {
    RrDr60PlayInfo {
        produced: i.produced,
        finished: i.finished,
        frames: i.frames,
        frame_index: i.frame_index,
        place: i.place,
    }
}

fn route_to_c(route: Route) -> u32 {
    match route {
        Route::Speaker => RrDr60Route::Speaker as u32,
        Route::Earphone => RrDr60Route::Earphone as u32,
        _ => RrDr60Route::Speaker as u32,
    }
}

fn route_from_c(value: u32) -> Option<Route> {
    match value {
        0 => Some(Route::Speaker),
        1 => Some(Route::Earphone),
        _ => None,
    }
}

/// Starts a recording (spec 006 FR-003, FR-004, FR-012): the record path starts from its reset
/// state and the recording in progress is number `count + 1`. Real-time safe.
///
/// Statuses: `RECORDING_IN_PROGRESS`, `PLAYBACK_IN_PROGRESS`, `MEMORY_FULL`,
/// `NO_RECORDING_SLOTS`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_start_recording(pipeline: *mut RrDr60Pipeline) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match guarded(p, |inner| inner.start_recording()) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Feeds `frames` host samples to the record path and appends what it produces to the
/// recording in progress; writes the block's VAS events (positions in the recording's device
/// samples from its start) to `events`, the first `events_capacity` of them (spec 006 FR-001,
/// FR-006). The recording stops by itself at the exact sample at which the memory fills
/// (`out_info->stopped`, FR-012). `out_info` is always written when not NULL (zeros on an
/// error). `events` may be NULL only when `events_capacity` is 0; `input` may be NULL only when
/// `frames` is 0. Real-time safe.
///
/// With the speech codec on, `out_info.frames` and `frames_total` count the frames completed
/// (spec 008 FR-008), and a VAS event reported in the block that fills the memory may name a
/// position up to the look-ahead (60 device samples) past the stored length: the recording
/// closes on the push that completes the frame filling the memory, and the look-ahead samples
/// kept after that frame are not represented (spec 008 FR-014).
///
/// Statuses: `NOT_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle. When `frames > 0`, `input` must be readable for `frames`
/// floats. `out_info` must be NULL or writable. When `events_capacity > 0`, `events` must be
/// writable for that many values.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_record(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    frames: usize,
    out_info: *mut RrDr60RecordInfo,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put(out_info, RrDr60RecordInfo::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if (input.is_null() && frames > 0) || (events.is_null() && events_capacity > 0) {
        return early(RrDr60Status::NullPointer);
    }
    let forced = take_forced_panic(p);
    let result = guarded(p, |inner| {
        if forced {
            panic!("rr_dr60__test_force_panic");
        }
        // SAFETY: input is readable for `frames` floats, or `frames` is 0 (caller contract).
        let x: &[f32] = if frames == 0 {
            &[]
        } else {
            unsafe { std::slice::from_raw_parts(input, frames) }
        };
        // SAFETY: the caller's event storage (caller contract).
        let slots = unsafe { event_slots(events, events_capacity) };
        inner.record(x, slots)
    });
    match result {
        Ok(info) => {
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put(out_info, c_record_info(info)) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// Writes to `*out_capacity` an `events_capacity` that is always enough for a `rr_dr60_record`
/// block of `frames` host samples with the current settings. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_capacity` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_max_record_events(
    pipeline: *mut RrDr60Pipeline,
    frames: usize,
    out_capacity: *mut usize,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_capacity.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_capacity is non-null and writable (caller contract).
    unsafe { *out_capacity = p.inner.max_record_events(frames) };
    RrDr60Status::Ok
}

/// Stops the recording (spec 006 FR-005): flushes the record path's own latency of silence
/// through it (its events go to `events`), and keeps the recording (`kept`, its number and
/// length) or, when nothing was fed since the start, discards it as empty (A-039).
/// `out_outcome` is always written when not NULL (zeros on an error). Real-time safe.
///
/// Statuses: `NOT_RECORDING` (including after a memory-full stop).
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_outcome` must be NULL or writable. When
/// `events_capacity > 0`, `events` must be writable for that many values.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_stop_recording(
    pipeline: *mut RrDr60Pipeline,
    out_outcome: *mut RrDr60StopOutcome,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_outcome is NULL or writable (caller contract).
        unsafe { put(out_outcome, RrDr60StopOutcome::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if events.is_null() && events_capacity > 0 {
        return early(RrDr60Status::NullPointer);
    }
    let result = guarded(p, |inner| {
        // SAFETY: the caller's event storage (caller contract).
        let slots = unsafe { event_slots(events, events_capacity) };
        inner.stop_recording(slots)
    });
    match result {
        Ok(outcome) => {
            // SAFETY: out_outcome is NULL or writable (caller contract).
            unsafe { put(out_outcome, c_outcome(outcome)) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// Starts playback of recording `number` (1 to the count) through the playback path, from its
/// reset state (spec 006 FR-002, FR-004). Real-time safe.
///
/// Statuses: `RECORDING_IN_PROGRESS`, `PLAYBACK_IN_PROGRESS`, `NO_SUCH_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_start_playback(
    pipeline: *mut RrDr60Pipeline,
    number: u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match guarded(p, |inner| inner.start_playback(number)) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Produces the next block of host samples of the recording being played into
/// `output[0 .. produced)` (spec 006 FR-002, FR-008): the recording, then its drain, then
/// `finished` and idle. `out_info` is always written when not NULL (zeros on an error).
/// `frames == 0` is OK (`output` may then be NULL). Real-time safe.
///
/// Statuses: `NOT_PLAYING`.
///
/// # Safety
///
/// `pipeline` must be a live handle. When `frames > 0`, `output` must be writable for `frames`
/// floats. `out_info` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_play(
    pipeline: *mut RrDr60Pipeline,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60PlayInfo,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put(out_info, RrDr60PlayInfo::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if output.is_null() && frames > 0 {
        return early(RrDr60Status::NullPointer);
    }
    let forced = take_forced_panic(p);
    let result = guarded(p, |inner| {
        if forced {
            panic!("rr_dr60__test_force_panic");
        }
        // SAFETY: output is writable for `frames` floats, or `frames` is 0 (caller contract);
        // it is the only reference to that memory during the call.
        let y: &mut [f32] = if frames == 0 {
            &mut []
        } else {
            unsafe { std::slice::from_raw_parts_mut(output, frames) }
        };
        inner.play(y)
    });
    match result {
        Ok(info) => {
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put(out_info, c_play_info(info)) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// Stops the playback at once, without the drain (spec 006 FR-008). Real-time safe.
///
/// Statuses: `NOT_PLAYING`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_stop_playback(pipeline: *mut RrDr60Pipeline) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match guarded(p, |inner| inner.stop_playback()) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// As `rr_dr60_play`, and writes the control changes the playback stream applied in this call
/// to `changes`: the first `changes_capacity` of them, in order (spec 015 FR-005);
/// `*out_change_count` (NULL allowed) receives how many the call applied;
/// `RR_DR60_MAX_CHANGES_PER_CALL` is always enough. `changes` may be NULL only when
/// `changes_capacity` is 0. Real-time safe.
///
/// Statuses: as `rr_dr60_play`.
///
/// # Safety
///
/// As `rr_dr60_play`; additionally, when `changes_capacity > 0`, `changes` must be writable
/// for that many `RrDr60ChangeEntry` values, and `out_change_count` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_play_with_changes(
    pipeline: *mut RrDr60Pipeline,
    output: *mut f32,
    frames: usize,
    out_info: *mut RrDr60PlayInfo,
    changes: *mut RrDr60ChangeEntry,
    changes_capacity: usize,
    out_change_count: *mut usize,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put(out_info, RrDr60PlayInfo::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if (output.is_null() && frames > 0) || (changes.is_null() && changes_capacity > 0) {
        return early(RrDr60Status::NullPointer);
    }
    let forced = take_forced_panic(p);
    let result = guarded(p, |inner| {
        if forced {
            panic!("rr_dr60__test_force_panic");
        }
        // SAFETY: output is writable for `frames` floats, or `frames` is 0 (caller contract);
        // it is the only reference to that memory during the call.
        let y: &mut [f32] = if frames == 0 {
            &mut []
        } else {
            unsafe { std::slice::from_raw_parts_mut(output, frames) }
        };
        // SAFETY: `ChangeEntry` has the layout of `RrDr60ChangeEntry` (the const assert); the
        // slice is the caller's storage, writable for `changes_capacity` values (or empty).
        let log: &mut [ChangeEntry] = if changes_capacity == 0 {
            &mut []
        } else {
            unsafe {
                std::slice::from_raw_parts_mut(changes.cast::<ChangeEntry>(), changes_capacity)
            }
        };
        inner.play_with_changes(y, log)
    });
    match result {
        Ok(info) => {
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put(out_info, c_play_info(info)) };
            // SAFETY: out_change_count is NULL or writable (caller contract).
            unsafe { put(out_change_count, info.changes) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// The core stream for a C stream value (spec 015): the two streams, the reserved one (which
/// the core refuses), or `None` for an unknown value.
fn stream_from_c(stream: u32) -> Option<Stream> {
    match stream {
        0 => Some(Stream::Playback),
        1 => Some(Stream::OnePass),
        2 => Some(Stream::Record),
        _ => None,
    }
}

/// Schedules a change of a live control at `position` of `stream`'s clock (spec 015 FR-001;
/// D2, D3): output sample `position` is the first the change affects (a volume transition
/// starts there, the route switches there with the new branch from rest, a speed level applies
/// from device-rate sample `rr_dr60_speed_landing(position)`); a position at or before the
/// stream's `rr_dr60_stream_position` lands on the next sample produced. `control` is the
/// control manifest's index of `route`, `volume` or `playback_speed` (resolve it by identifier
/// through `rr_dr60_control`); `value` the control's own value (a route 0 or 1, a volume
/// position, rounded to single precision, a level 1 … 5); `tag` is echoed in the change entry
/// (**0 means a plain setter**: tag from 1). Each stream holds up to
/// `RR_DR60_SCHEDULE_CAPACITY` pending changes, applied in position order (ties in submission
/// order); the playback schedule is kept by `rr_dr60_start_playback` and cleared when a playback
/// ends by any path, both by `rr_dr60_reset` and `rr_dr60_reconfigure`. Accepted in every engine
/// state; real-time safe. Positioning a change on a sample is a feature of the emulator's API,
/// not a device behavior (spec 015 D8).
///
/// Statuses, nothing stored on any: `CONTROL_NOT_ON_STREAM` (a reserved or unknown stream, a
/// control that is not one of the three, the speed on the one-pass stream); `INVALID_VOLUME`,
/// `INVALID_SPEED_LEVEL`, or `INVALID_ARGUMENT` for a route value not 0 or 1; `TAP_NOT_ON_ROUTE`
/// for a route the one-pass's named-route tap cannot read; `SCHEDULE_FULL`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_schedule_change(
    pipeline: *mut RrDr60Pipeline,
    stream: u32,
    position: u64,
    control: u32,
    value: f64,
    tag: u64,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    let Some(stream) = stream_from_c(stream) else {
        return RrDr60Status::ControlNotOnStream;
    };
    match guarded(p, |inner| {
        inner.schedule_change(stream, position, control, value, tag)
    }) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Writes to `*out_count` the pending changes on `stream`'s schedules (spec 015 FR-002; spec
/// 017 FR-002: the one-pass's two, one per clock, summed). Real-time safe.
///
/// Statuses: `CONTROL_NOT_ON_STREAM` for an unknown stream (nothing written).
///
/// # Safety
///
/// `pipeline` must be a live handle; `out_count` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_pending_changes(
    pipeline: *const RrDr60Pipeline,
    stream: u32,
    out_count: *mut u32,
) -> RrDr60Status {
    if pipeline.is_null() || out_count.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    let Some(stream) = stream_from_c(stream) else {
        return RrDr60Status::ControlNotOnStream;
    };
    match p.inner.pending_changes(stream) {
        Ok(n) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_count, n) };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// Writes to `*out_position` `stream`'s **output** position (spec 015 D2): the host output
/// samples it has produced; the next sample produced has this index. Real-time safe.
///
/// Statuses: `NO_SUCH_CLOCK` for the record stream (it has only the input clock,
/// `rr_dr60_input_position`); `CONTROL_NOT_ON_STREAM` for an unknown stream (nothing
/// written).
///
/// # Safety
///
/// `pipeline` must be a live handle; `out_position` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_stream_position(
    pipeline: *const RrDr60Pipeline,
    stream: u32,
    out_position: *mut u64,
) -> RrDr60Status {
    if pipeline.is_null() || out_position.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    let Some(stream) = stream_from_c(stream) else {
        return RrDr60Status::ControlNotOnStream;
    };
    match p.inner.stream_position(stream) {
        Ok(n) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_position, n) };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// Drops every pending change on `stream`'s schedules (spec 015 FR-002; both of the one-pass's,
/// spec 017); nothing already applied is affected. Real-time safe.
///
/// Statuses: `CONTROL_NOT_ON_STREAM` for an unknown stream.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_clear_schedule(
    pipeline: *mut RrDr60Pipeline,
    stream: u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    let Some(stream) = stream_from_c(stream) else {
        return RrDr60Status::ControlNotOnStream;
    };
    match guarded(p, |inner| inner.clear_schedule(stream)) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Writes to `*out_counter` the recording counter (spec 015 D9; spec 012 FR-009, A-049):
/// successful recording starts since construction, never rewound. A one-pass replay reproduces
/// the microphone hiss only with the same seed and the same counter. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle; `out_counter` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_recording_counter(
    pipeline: *const RrDr60Pipeline,
    out_counter: *mut u64,
) -> RrDr60Status {
    if pipeline.is_null() || out_counter.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    // SAFETY: non-null and writable (caller contract).
    unsafe { put(out_counter, p.inner.recording_counter()) };
    RrDr60Status::Ok
}

/// Writes to `*out_index` the device-rate output index at which a speed change scheduled at
/// host output `position` lands (spec 015 D3): d(0) = 0, d(P) = ⌊(P − 1) · 6000 ÷ rate⌋ + 1 (P at
/// 6 kHz); the audible effect follows after `rr_dr60_playback_latency_samples`. No handle.
///
/// Statuses: `INVALID_ARGUMENT` for a rate not in the supported list (nothing written).
///
/// # Safety
///
/// `out_index` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_speed_landing(
    position: u64,
    host_rate_hz: u32,
    out_index: *mut u64,
) -> RrDr60Status {
    if out_index.is_null() {
        return RrDr60Status::NullPointer;
    }
    match rr_dr60::changes::speed_landing(position, host_rate_hz) {
        Ok(d) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_index, d) };
            RrDr60Status::Ok
        }
        Err(_) => RrDr60Status::InvalidArgument,
    }
}

/// Writes to `*out_clock` the clock `control`'s positions count in (spec 017 D2), an
/// `RrDr60Clock` value: `INPUT` for a control whose control manifest paths include the record
/// path (the eight record-side values), `OUTPUT` otherwise (the route, the volume, the speed).
/// No handle. Real-time safe.
///
/// Statuses: `NO_SUCH_CONTROL` for an index at or past `rr_dr60_control_count()` (nothing
/// written).
///
/// # Safety
///
/// `out_clock` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_clock_of(control: u32, out_clock: *mut u32) -> RrDr60Status {
    if out_clock.is_null() {
        return RrDr60Status::NullPointer;
    }
    match rr_dr60::changes::clock_of(control) {
        Ok(c) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_clock, c as u32) };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// Writes to `*out_index` the device sample at which a gate value (`vas.*`) scheduled at input
/// sample `position` takes effect (spec 017 D3): k(0) = 0, k(P) = ⌈P · 6000 ÷ rate⌉ (P at
/// 6 kHz). The limiter's and the hiss's values act on input sample P itself. No handle.
///
/// Statuses: `INVALID_ARGUMENT` for a rate not in the supported list (nothing written).
///
/// # Safety
///
/// `out_index` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_record_landing(
    position: u64,
    host_rate_hz: u32,
    out_index: *mut u64,
) -> RrDr60Status {
    if out_index.is_null() {
        return RrDr60Status::NullPointer;
    }
    match rr_dr60::changes::record_landing(position, host_rate_hz) {
        Ok(k) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_index, k) };
            RrDr60Status::Ok
        }
        Err(_) => RrDr60Status::InvalidArgument,
    }
}

/// Writes to `*out_position` `stream`'s **input** position (spec 017 D2): the host input
/// samples it has processed; the next sample fed has this index. The record stream's count
/// starts at 0 at `rr_dr60_start_recording`, counts the stop's fed silence and reads 0 while
/// idle; the one-pass's starts at construction, `rr_dr60_reset` and `rr_dr60_reconfigure`.
/// Real-time safe.
///
/// Statuses: `NO_SUCH_CLOCK` for the playback stream (it has only the output clock,
/// `rr_dr60_stream_position`); `CONTROL_NOT_ON_STREAM` for an unknown stream (nothing
/// written).
///
/// # Safety
///
/// `pipeline` must be a live handle; `out_position` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_input_position(
    pipeline: *const RrDr60Pipeline,
    stream: u32,
    out_position: *mut u64,
) -> RrDr60Status {
    if pipeline.is_null() || out_position.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: non-null live handle (caller contract).
    let p = unsafe { &*pipeline };
    if p.poisoned {
        return RrDr60Status::InternalError;
    }
    let Some(stream) = stream_from_c(stream) else {
        return RrDr60Status::ControlNotOnStream;
    };
    match p.inner.input_position(stream) {
        Ok(n) => {
            // SAFETY: non-null and writable (caller contract).
            unsafe { put(out_position, n) };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// As `rr_dr60_record`, and writes the record-side changes this call applied to `changes`
/// (spec 017 FR-005): the first `changes_capacity` of them, each an `RrDr60ChangeEntry` at the
/// **input** index it landed on; `*out_change_count` (NULL allowed) receives how many the call
/// applied (`RR_DR60_MAX_CHANGES_PER_CALL` is always enough) and `*out_input_samples_total`
/// (NULL allowed) the record stream's input position after the call (after a self-stop, the
/// recording's final input position). `changes` may be NULL only when `changes_capacity` is
/// 0. Real-time safe.
///
/// Statuses: as `rr_dr60_record`.
///
/// # Safety
///
/// As `rr_dr60_record`; additionally, when `changes_capacity > 0`, `changes` must be writable
/// for that many `RrDr60ChangeEntry` values; `out_change_count` and `out_input_samples_total`
/// must be NULL or writable.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)] // the C surface: two caller buffers with their capacities and the two counts
pub unsafe extern "C" fn rr_dr60_record_with_changes(
    pipeline: *mut RrDr60Pipeline,
    input: *const f32,
    frames: usize,
    out_info: *mut RrDr60RecordInfo,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
    changes: *mut RrDr60ChangeEntry,
    changes_capacity: usize,
    out_change_count: *mut usize,
    out_input_samples_total: *mut u64,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_info is NULL or writable (caller contract).
        unsafe { put(out_info, RrDr60RecordInfo::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if (input.is_null() && frames > 0)
        || (events.is_null() && events_capacity > 0)
        || (changes.is_null() && changes_capacity > 0)
    {
        return early(RrDr60Status::NullPointer);
    }
    let result = guarded(p, |inner| {
        // SAFETY: input is readable for `frames` floats, or `frames` is 0 (caller contract).
        let x: &[f32] = if frames == 0 {
            &[]
        } else {
            unsafe { std::slice::from_raw_parts(input, frames) }
        };
        // SAFETY: the caller's event storage (caller contract).
        let slots = unsafe { event_slots(events, events_capacity) };
        // SAFETY: `ChangeEntry` has the layout of `RrDr60ChangeEntry` (the const assert); the
        // slice is the caller's storage, writable for `changes_capacity` values (or empty).
        let log: &mut [ChangeEntry] = if changes_capacity == 0 {
            &mut []
        } else {
            unsafe {
                std::slice::from_raw_parts_mut(changes.cast::<ChangeEntry>(), changes_capacity)
            }
        };
        inner.record_with_changes(x, slots, log)
    });
    match result {
        Ok(info) => {
            // SAFETY: out_info is NULL or writable (caller contract).
            unsafe { put(out_info, c_record_info(info)) };
            // SAFETY: NULL or writable (caller contract).
            unsafe { put(out_change_count, info.changes) };
            // SAFETY: NULL or writable (caller contract).
            unsafe { put(out_input_samples_total, info.input_samples_total) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// As `rr_dr60_stop_recording`, and writes the record-side changes the stop's feed applied to
/// `changes` (spec 017 FR-005; the schedule applies during the flush and is cleared at the
/// end); `*out_change_count` (NULL allowed) receives how many, `*out_input_samples_total` (NULL
/// allowed) the recording's final input position: every host sample fed since the start, the
/// stop's silence included (a change at or past it was dropped without an entry). Both are 0
/// when the flush was skipped. Real-time safe.
///
/// Statuses: as `rr_dr60_stop_recording`.
///
/// # Safety
///
/// As `rr_dr60_stop_recording`; additionally, when `changes_capacity > 0`, `changes` must be
/// writable for that many values; `out_change_count` and `out_input_samples_total` must be
/// NULL or writable.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)] // the C surface: two caller buffers with their capacities and the two counts
pub unsafe extern "C" fn rr_dr60_stop_recording_with_changes(
    pipeline: *mut RrDr60Pipeline,
    out_outcome: *mut RrDr60StopOutcome,
    events: *mut RrDr60VasEvent,
    events_capacity: usize,
    changes: *mut RrDr60ChangeEntry,
    changes_capacity: usize,
    out_change_count: *mut usize,
    out_input_samples_total: *mut u64,
) -> RrDr60Status {
    let early = |status| {
        // SAFETY: out_outcome is NULL or writable (caller contract).
        unsafe { put(out_outcome, RrDr60StopOutcome::default()) };
        status
    };
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return early(status),
    };
    if (events.is_null() && events_capacity > 0) || (changes.is_null() && changes_capacity > 0) {
        return early(RrDr60Status::NullPointer);
    }
    let result = guarded(p, |inner| {
        // SAFETY: the caller's event storage (caller contract).
        let slots = unsafe { event_slots(events, events_capacity) };
        // SAFETY: as in `rr_dr60_record_with_changes`.
        let log: &mut [ChangeEntry] = if changes_capacity == 0 {
            &mut []
        } else {
            unsafe {
                std::slice::from_raw_parts_mut(changes.cast::<ChangeEntry>(), changes_capacity)
            }
        };
        inner.stop_recording_with_changes(slots, log)
    });
    match result {
        Ok(outcome) => {
            // SAFETY: out_outcome is NULL or writable (caller contract).
            unsafe { put(out_outcome, c_outcome(outcome)) };
            // SAFETY: NULL or writable (caller contract).
            unsafe { put(out_change_count, outcome.changes) };
            // SAFETY: NULL or writable (caller contract).
            unsafe { put(out_input_samples_total, outcome.input_samples_total) };
            RrDr60Status::Ok
        }
        Err(status) => early(status),
    }
}

/// Selects the output route, an `RrDr60Route` value (spec 006 FR-015): at any time, during
/// playback too; it survives `rr_dr60_reset` and `rr_dr60_reconfigure`. Real-time safe.
///
/// Statuses: `INVALID_ARGUMENT` for a value that is not a route (the route is unchanged).
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_set_route(
    pipeline: *mut RrDr60Pipeline,
    route: u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    let Some(route) = route_from_c(route) else {
        return RrDr60Status::InvalidArgument;
    };
    p.inner.set_route(route);
    RrDr60Status::Ok
}

/// Writes the selected route, an `RrDr60Route` value, to `*out_route`. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_route` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_route(
    pipeline: *mut RrDr60Pipeline,
    out_route: *mut u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_route.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_route is non-null and writable (caller contract).
    unsafe { *out_route = route_to_c(p.inner.route()) };
    RrDr60Status::Ok
}

/// The volume control's default position (spec 009 FR-003; A-043): the reference position at
/// which a full-scale codec output just reaches the amplifier's clip ceiling under the loaded
/// law, about 0.1335. Equal to the Rust `output::VOLUME_REFERENCE`. In the C header it is a
/// double literal: cast it to `float` (`(float)RR_DR60_VOLUME_REFERENCE`), whose nearest value
/// is the engine's default bit for bit.
pub const RR_DR60_VOLUME_REFERENCE: f32 = 0.133_451_74; // A-043: equal to `rr_dr60::output::VOLUME_REFERENCE` bit for bit (a literal so cbindgen emits the define; the unit test pins it)

/// The length of a volume transition in milliseconds (spec 011 FR-002; A-045): a valid
/// `rr_dr60_set_volume` change moves the knob to the new position over this time at every host
/// rate. Equal to the Rust `output::VOLUME_TRANSITION_MS`. A read-only constant, not a setting.
pub const RR_DR60_VOLUME_TRANSITION_MS: u32 = 20; // A-045: equal to `rr_dr60::output::VOLUME_TRANSITION_MS` (a literal so cbindgen emits the define; the unit test pins it)

/// Sets the volume position (spec 009 FR-003; A-043, A-044): the control's wiper fraction,
/// 0 (silence) to 1 (maximum), at any time including during playback; it takes effect at the
/// next processing call or `rr_dr60_play` block and survives `rr_dr60_reset` and
/// `rr_dr60_reconfigure`. Since 0.11 a change is a 20 ms volume transition
/// (`RR_DR60_VOLUME_TRANSITION_MS`; spec 011, A-045): from the next block the knob moves from
/// where it is to `position`, starting and ending at rest, the gain following the loaded law
/// and never passing either end; a change during a transition starts a new 20 ms movement from
/// the knob's current position, from rest, so the knob trails a stream of updates (about 19 ms
/// at 60 Hz, about 105 ms if the position changes every 64-sample block at 48 kHz): send a
/// position when the control moves, at most once per UI frame. The first block that produces
/// output after `rr_dr60_create`, `rr_dr60_reset`, `rr_dr60_reconfigure` or
/// `rr_dr60_start_playback`, and the first after a route change, take the position at once.
/// The one-pass processing and the playback each keep their own knob position. Default
/// `RR_DR60_VOLUME_REFERENCE`; positions above it clip
/// full-scale material on the speaker route. Real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_VOLUME` for a non-finite position or one outside 0 … 1; the
/// position is then unchanged.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_set_volume(
    pipeline: *mut RrDr60Pipeline,
    position: f32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match p.inner.set_volume(position) {
        Ok(()) => RrDr60Status::Ok,
        Err(e) => status_from_error(e),
    }
}

/// Writes the volume position to `*out_position` (spec 009 FR-003): the last valid setting, not
/// the knob's position during a volume transition (spec 011 FR-011). Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_position` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_volume(
    pipeline: *mut RrDr60Pipeline,
    out_position: *mut f32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_position.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_position is non-null and writable (caller contract).
    unsafe { *out_position = p.inner.volume() };
    RrDr60Status::Ok
}

/// The lowest battery value `rr_dr60_set_battery_volts` accepts, volts of the cell pair (spec
/// 018 FR-001; A-056): where the device would show its low-battery indicator and stop. Equal to
/// the Rust `battery::BATTERY_VOLTS_RANGE.0`. A double literal: cast to `float`.
pub const RR_DR60_BATTERY_VOLTS_MIN: f32 = 2.2; // 018 FR-001: equal to `rr_dr60::battery::BATTERY_VOLTS_RANGE.0` (a literal so cbindgen emits the define; the unit test pins it)
/// The highest battery value accepted: fresh cells (spec 018 FR-001; A-056). Equal to the Rust
/// `battery::BATTERY_VOLTS_RANGE.1`.
pub const RR_DR60_BATTERY_VOLTS_MAX: f32 = 3.0; // 018 FR-001: equal to `rr_dr60::battery::BATTERY_VOLTS_RANGE.1` (pinned)
/// The default battery value, the nominal mark (V+ 2.8 V of S-002; spec 018 FR-001): the
/// ceiling factor is exactly 1 and every output equals 0.17's. An app's "fresh" is this value,
/// not the trajectory's first row. Equal to the Rust `battery::DEFAULT_BATTERY_VOLTS`.
pub const RR_DR60_BATTERY_VOLTS_DEFAULT: f32 = 3.0; // 018 FR-001: equal to `rr_dr60::battery::DEFAULT_BATTERY_VOLTS` (pinned)
/// A steady NiMH pair's voltage, a preset value (A-056; spec 018 FR-006). Equal to the Rust
/// `battery::NIMH_PAIR_VOLTS`.
pub const RR_DR60_BATTERY_NIMH_PAIR_VOLTS: f32 = 2.45; // A-056 (018 FR-006): equal to `rr_dr60::battery::NIMH_PAIR_VOLTS` (pinned)
/// The rows of the alkaline reference trajectory `rr_dr60_battery_trajectory_row` reads (spec
/// 018 FR-006; A-056, S-017). Equal to the Rust `battery::ALKALINE_TRAJECTORY.len()`.
pub const RR_DR60_BATTERY_TRAJECTORY_ROWS: u32 = 7; // 018 FR-006: equal to `rr_dr60::battery::ALKALINE_TRAJECTORY.len()` (pinned)

/// Sets the battery value, volts of the played unit's cell pair (spec 018 FR-001; A-056), at
/// any time including during playback: the speaker amplifier runs on the raw battery, so its
/// clip ceiling scales by the static law `rr_dr60_battery_ceiling_factor` (exactly 1 at the
/// default `RR_DR60_BATTERY_VOLTS_DEFAULT`, where every output equals 0.17's); below the clip
/// knee the output is unchanged; the earphone route and the record path do not move. A change
/// takes effect at the next processing call or `rr_dr60_play` block and moves the factor over a
/// 20 ms transition (`RR_DR60_VOLUME_TRANSITION_MS`; A-045), at once on a stream's first sample,
/// with stage 11 bypassed, on the earphone route and at a route change; it survives
/// `rr_dr60_reset` and `rr_dr60_reconfigure`. The value describes the played unit's cells and
/// is set by the user: never drive it from the host device's battery, a sensor or a timer. Modeled
/// on the circuit (S-002) and the amplifier's datasheet (S-006), not measured. Real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_BATTERY_VOLTS` for a value outside
/// `RR_DR60_BATTERY_VOLTS_MIN` … `RR_DR60_BATTERY_VOLTS_MAX` or not finite; the value is then
/// unchanged.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_set_battery_volts(
    pipeline: *mut RrDr60Pipeline,
    volts: f32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match p.inner.set_battery_volts(volts) {
        Ok(()) => RrDr60Status::Ok,
        Err(e) => status_from_error(e),
    }
}

/// Writes the battery value to `*out_volts` (spec 018 FR-001): the last valid setting or the last
/// landed scheduled change, not the factor during a transition (`rr_dr60_meters` reads that).
/// Real-time safe.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle. `out_volts` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_battery_volts(
    pipeline: *mut RrDr60Pipeline,
    out_volts: *mut f32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_volts.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_volts is non-null and writable (caller contract).
    unsafe { *out_volts = p.inner.battery_volts() };
    RrDr60Status::Ok
}

/// Writes the static law's ceiling factor for a battery value to `*out_factor` (spec 018 FR-006;
/// A-056): `(volts − 1.8) / 1.2`, the speaker amplifier's clip ceiling relative to the model's
/// 1.15 V at the nominal 3.0 V (V+ = volts − 0.2 V through Q9; the swing limits V+ − 1.6 V of
/// S-006). Total: any finite value is accepted, also outside the setter's range (the register's
/// own figures at 2.96 … 2.22 V, or a 1.8 V pair reading 0). No handle; real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_ARGUMENT` for a non-finite value; nothing is written.
///
/// # Safety
///
/// `out_factor` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_battery_ceiling_factor(
    volts: f32,
    out_factor: *mut f32,
) -> RrDr60Status {
    if out_factor.is_null() {
        return RrDr60Status::NullPointer;
    }
    if !volts.is_finite() {
        return RrDr60Status::InvalidArgument;
    }
    // SAFETY: out_factor is non-null and writable (caller contract).
    unsafe { *out_factor = rr_dr60::battery::ceiling_factor(volts) };
    RrDr60Status::Ok
}

/// Writes the static law's ceiling change in decibels to `*out_db` (spec 018 FR-006):
/// `20·log10` of `rr_dr60_battery_ceiling_factor`, the level by which a clipped tone comes out
/// lower than at the nominal value (−1.6 dB at 2.8 V, −6.0 dB at 2.4 V, −9.5 dB at 2.2 V;
/// `-INFINITY` at or below 1.8 V). No handle; real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_ARGUMENT` for a non-finite value; nothing is written.
///
/// # Safety
///
/// `out_db` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_battery_ceiling_db(volts: f32, out_db: *mut f32) -> RrDr60Status {
    if out_db.is_null() {
        return RrDr60Status::NullPointer;
    }
    if !volts.is_finite() {
        return RrDr60Status::InvalidArgument;
    }
    // SAFETY: out_db is non-null and writable (caller contract).
    unsafe { *out_db = rr_dr60::battery::ceiling_db(volts) };
    RrDr60Status::Ok
}

/// Writes row `i` of the alkaline reference trajectory (spec 018 FR-006; A-056, S-017 with
/// S-001's battery life) to `*out_hours` and `*out_volts`: the cell pair's voltage under the
/// device's load after that many hours of **recording**, `RR_DR60_BATTERY_TRAJECTORY_ROWS` rows
/// from 0 h at 2.96 V to 10 h at 2.22 V (row 0 is a loaded-cell reading, not a fresher state
/// than the default 3.0 V). Preset values for an app, never a drain: the engine never moves the
/// battery value on its own. No handle; real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_ARGUMENT` for `i` at or past the row count; nothing is
/// written.
///
/// # Safety
///
/// `out_hours` and `out_volts` must each be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_battery_trajectory_row(
    i: u32,
    out_hours: *mut f32,
    out_volts: *mut f32,
) -> RrDr60Status {
    if out_hours.is_null() || out_volts.is_null() {
        return RrDr60Status::NullPointer;
    }
    let Some(&(hours, volts)) = rr_dr60::battery::ALKALINE_TRAJECTORY.get(i as usize) else {
        return RrDr60Status::InvalidArgument;
    };
    // SAFETY: both out-pointers are non-null and writable (caller contract).
    unsafe {
        *out_hours = hours;
        *out_volts = volts;
    }
    RrDr60Status::Ok
}

/// The meter read-out of the last non-empty processing call (spec 016 FR-001 – FR-003;
/// contracts/api.md): the figures `rr_dr60_meters` fills. 64 bytes since 0.18 (56 in 0.16 and
/// 0.17: spec 018 appended `amp_clip_count` and `battery_ceiling`), 8-aligned; the caller sets
/// `struct_size` to `sizeof(RrDr60Meters)`. Every peak is linear full-scale (20·log10 for
/// dBFS), the largest absolute sample at its point, and may exceed 1.0. A figure whose point
/// the call did not reach keeps its rest value: 0 (`vas_paused` 0), except
/// `hang_remaining_samples`, whose rest is the configured hang length, and `battery_ceiling`,
/// whose rest is the factor of the battery value in force at the last non-empty call (a value
/// set since shows in the next call's read-out; the Rust `rest_meters()` follows it at once).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct RrDr60Meters {
    /// Set by the caller to `sizeof(RrDr60Meters)` (64 in this version; 56 in 0.16 and 0.17).
    /// Below 56 is refused (`RR_DR60_STATUS_INVALID_ARGUMENT`); 56 … 63 fills the 56 bytes of
    /// the 0.16 fields and touches nothing else (a 0.17 binary keeps working); 64 and above
    /// fills every field and zeroes the bytes past 64.
    pub struct_size: u32,
    /// The largest absolute input sample after the engine's sanitizing of non-finite samples.
    pub input_peak: f32,
    /// The largest absolute sample entering the limiter (stage 2's output; the input with
    /// stages 1 – 2 bypassed; A-046, A-051). May exceed 1.0.
    pub limiter_input_peak: f32,
    /// The deepest attenuation the limiter applied in the call, dB ≥ 0 (A-028, A-034, A-035;
    /// modeled on the circuit, not measured).
    pub gain_reduction_db: f32,
    /// The limiter's hold capacitor at the end of the call, 0 – 1 of the model's deepest
    /// attenuation (40 dB, an engineering target): about 0.13 the unity floor, 0.73 one decibel
    /// of attenuation, 0.84 ten, 0.90 twenty. A state: a silent call reads the decaying hold.
    pub hold_charge: f32,
    /// The largest absolute device sample after stage 4's record band-limit (A-027), before the
    /// converter's full-scale clamp (A-030): above 1.0 whenever the clamp bounded samples.
    pub record_filter_peak: f32,
    /// The device samples of the call the converter's full-scale clamp changed
    /// (`adc_clamp_enabled`).
    pub adc_clamp_count: u32,
    /// 1 when the voice activation's own state is paused at the end of the call, else 0.
    pub vas_paused: u32,
    /// The further non-sound device samples the gate keeps before pausing (A-023; ÷ 6000 for
    /// seconds); the full hang length when the last sample was sound or the gate is bypassed;
    /// 0 while paused.
    pub hang_remaining_samples: u64,
    /// The largest absolute host sample after stage 10 and the conversion, before the output
    /// chain.
    pub reconstruction_peak: f32,
    /// The largest absolute sample at the selected route's output before the optional output
    /// clamp (1.0 is the amplifier's clip ceiling on the speaker route, the earphone scale on
    /// the earphone route; A-042). The speaker route reads up to about 2.3.
    pub route_peak: f32,
    /// The host samples of the call the optional output clamp bounded (0 with the option off;
    /// an emulator option, spec 010).
    pub output_clamp_count: u32,
    /// Explicit tail padding, written 0.
    pub reserved_016: u32,
    /// The host samples of the call in the speaker amplifier's clip region, above the clipper's
    /// start (0.85 of the ceiling at the battery value in force; A-031, A-056), on the speaker
    /// route with stage 11 on; 0 on the earphone route, with stage 11 bypassed and at a tap
    /// before stage 11 (spec 018 FR-010).
    pub amp_clip_count: u32,
    /// The battery's ceiling factor in force at the end of the call (spec 018 FR-010; A-056):
    /// `rr_dr60_battery_ceiling_factor` of the value, 1.0 at the default 3.0 V, moving over the
    /// 20 ms transition after a change; 20·log10 for dB. Reported on both routes.
    pub battery_ceiling: f32,
}

const METERS_SIZE: u32 = size_of::<RrDr60Meters>() as u32;
const _: () = assert!(size_of::<RrDr60Meters>() == 64); // 56 before spec 018
const _: () = assert!(align_of::<RrDr60Meters>() == 8);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, struct_size) == 0);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, input_peak) == 4);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, limiter_input_peak) == 8);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, gain_reduction_db) == 12);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, hold_charge) == 16);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, record_filter_peak) == 20);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, adc_clamp_count) == 24);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, vas_paused) == 28);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, hang_remaining_samples) == 32);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, reconstruction_peak) == 40);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, route_peak) == 44);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, output_clamp_count) == 48);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, reserved_016) == 52);
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, amp_clip_count) == 56); // spec 018
const _: () = assert!(core::mem::offset_of!(RrDr60Meters, battery_ceiling) == 60); // spec 018
/// The read-out's size in 0.16 and 0.17: the smallest `struct_size` accepted (spec 018 FR-010,
/// the compatible prefix-fill rule).
const METERS_SIZE_016: u32 = 56;
const _: () = assert!(METERS_SIZE == 64 && METERS_SIZE_016 < METERS_SIZE);

impl RrDr60Meters {
    fn from_core(m: rr_dr60::Meters, struct_size: u32) -> Self {
        Self {
            struct_size,
            input_peak: m.input_peak,
            limiter_input_peak: m.limiter_input_peak,
            gain_reduction_db: m.gain_reduction_db,
            hold_charge: m.hold_charge,
            record_filter_peak: m.record_filter_peak,
            adc_clamp_count: m.adc_clamp_count,
            vas_paused: u32::from(m.vas_paused),
            hang_remaining_samples: m.hang_remaining_samples,
            reconstruction_peak: m.reconstruction_peak,
            route_peak: m.route_peak,
            output_clamp_count: m.output_clamp_count,
            reserved_016: 0,
            amp_clip_count: m.amp_clip_count,   // spec 018
            battery_ceiling: m.battery_ceiling, // spec 018
        }
    }
}

/// Copies the meter read-out of the last non-empty processing call into `*out` (spec 016
/// FR-001, FR-009): the figures of the last `rr_dr60_process*`, `rr_dr60_record`,
/// `rr_dr60_play` or `rr_dr60_stop_recording` call that processed samples; the rest state
/// before any, after `rr_dr60_reset` and after `rr_dr60_reconfigure`. Real-time safe; never
/// changes the engine. `out->struct_size` is read first (the compatible prefix-fill rule, spec
/// 018 FR-010): below 56 (the size of 0.16 and 0.17) → `RR_DR60_STATUS_INVALID_ARGUMENT` and
/// nothing written; 56 … 63 → the 56 bytes of the 0.16 fields filled and nothing else touched;
/// 64 and above → the 64 bytes filled and the bytes `[64, struct_size)` zeroed (no upper cap).
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle. `out` must be NULL or 8-aligned with
/// `out->struct_size` bytes writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_meters(
    pipeline: *mut RrDr60Pipeline,
    out: *mut RrDr60Meters,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: `struct_size` is the first field of a `repr(C)` struct, at offset 0; the caller
    // guarantees that much is readable. `read_unaligned` assumes nothing about alignment.
    let size = unsafe { out.cast::<u32>().read_unaligned() };
    if size < METERS_SIZE_016 {
        return RrDr60Status::InvalidArgument;
    }
    let m = RrDr60Meters::from_core(p.inner.meters(), size);
    // Hardware review B5: a 0.17-sized request (56 … 63) receives exactly the 0.16 fields, never
    // a partial appended field.
    let filled = if size < METERS_SIZE {
        METERS_SIZE_016 as usize
    } else {
        METERS_SIZE as usize
    };
    // SAFETY: `out` is non-null and at least `size` ≥ 56 bytes writable (caller contract); the
    // first 56 or 64 bytes of the filled struct are copied byte by byte (a `repr(C)` struct
    // with no uninitialized padding: `reserved_016` is explicit), so a 0.17-sized buffer
    // receives exactly its 56 bytes; the tail `[64, size)` is zero-filled.
    unsafe {
        core::ptr::copy_nonoverlapping(
            (&m as *const RrDr60Meters).cast::<u8>(),
            out.cast::<u8>(),
            filled,
        );
        if size > METERS_SIZE {
            core::ptr::write_bytes(
                out.cast::<u8>().add(METERS_SIZE as usize),
                0,
                (size - METERS_SIZE) as usize,
            );
        }
    }
    RrDr60Status::Ok
}

/// The crossfade at a playback speed-level change, in milliseconds (spec 019 FR-002): from the
/// device sample a change lands on, the old level fades out at its own place and pitch while the
/// new level fades in, over 20 ms (120 device samples); a request made during a blend lands when
/// the blend ends, at most this much later (plus at most four device samples for a change into
/// level 3) and before `rr_dr60_playback_latency_samples`. **An engine convention, not a device
/// behavior** (A-054). Equal to the Rust `speed::CROSSFADE_MS`.
pub const RR_DR60_SPEED_CROSSFADE_MS: u32 = 20; // 019 FR-002: equal to `rr_dr60::speed::CROSSFADE_MS` (a literal so cbindgen emits the define; the unit test pins it)

/// The number of playback speed levels (spec 013 FR-001; S-001). Equal to the Rust
/// `speed::LEVEL_COUNT`.
pub const RR_DR60_SPEED_LEVEL_COUNT: u32 = 5; // 013 FR-001: equal to `rr_dr60::speed::LEVEL_COUNT` (a literal so cbindgen emits the define; the unit test pins it)

/// The default playback speed level: normal speed (spec 013 FR-001; S-001: level 3).
pub const RR_DR60_SPEED_DEFAULT_LEVEL: u32 = 3; // 013 FR-001: equal to `rr_dr60::speed::DEFAULT_LEVEL` (pinned)

/// The denominator of every playback speed ratio (spec 013 FR-002): level n plays at
/// `RR_DR60_SPEED_RATIO_NUMERATOR_n` / 5 of normal speed.
pub const RR_DR60_SPEED_RATIO_DENOMINATOR: u32 = 5; // 013 FR-002: equal to `rr_dr60::speed::RATIO_DENOMINATOR` (pinned)

/// Level 1's speed ratio numerator: 3/5, the slowest (A-054; spec 013 FR-002).
pub const RR_DR60_SPEED_RATIO_NUMERATOR_1: u32 = 3; // A-054 (013 FR-002; pinned)
/// Level 2's speed ratio numerator: 4/5 (A-054).
pub const RR_DR60_SPEED_RATIO_NUMERATOR_2: u32 = 4; // A-054 (013 FR-002; pinned)
/// Level 3's speed ratio numerator: 5/5, normal speed, the identity (A-054).
pub const RR_DR60_SPEED_RATIO_NUMERATOR_3: u32 = 5; // A-054 (013 FR-002; pinned)
/// Level 4's speed ratio numerator: 6/5 (A-054).
pub const RR_DR60_SPEED_RATIO_NUMERATOR_4: u32 = 6; // A-054 (013 FR-002; pinned)
/// Level 5's speed ratio numerator: 7/5, the fastest (A-054).
pub const RR_DR60_SPEED_RATIO_NUMERATOR_5: u32 = 7; // A-054 (013 FR-002; pinned)

/// Sets the playback speed level (spec 013 FR-001; A-054): 1 (slowest) … 5 (fastest), 3 normal,
/// the default, at 3/5, 4/5, 1, 6/5 and 7/5 of normal speed with the pitch moving with the speed
/// (the modeled default; not measured). At level 3 a playback is bit-identical to 0.12's. Live:
/// at any time; from the first device sample an `rr_dr60_play` call computes after it, the
/// playback continues at the new level from the place it reached (a change into level 3 waits
/// until the place is a whole stored sample, at most 4 device samples). Applies to
/// `rr_dr60_play` only. Survives `rr_dr60_reset` and `rr_dr60_reconfigure`. Real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_SPEED_LEVEL` for 0 or a level above 5; the level is then
/// unchanged.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_set_playback_speed(
    pipeline: *mut RrDr60Pipeline,
    level: u8,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match p.inner.set_playback_speed(level) {
        Ok(()) => RrDr60Status::Ok,
        Err(e) => status_from_error(e),
    }
}

/// Writes the playback speed level to `*out_level` (spec 013 FR-001): the last valid setting,
/// default 3. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_level` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_playback_speed(
    pipeline: *mut RrDr60Pipeline,
    out_level: *mut u8,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_level.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_level is non-null and writable (caller contract).
    unsafe { *out_level = p.inner.playback_speed() };
    RrDr60Status::Ok
}

/// Writes to `*out_samples` the host samples `rr_dr60_play` produces for recording `number`
/// played at a constant speed `level` (spec 013 FR-009): the recording's own part, the speed
/// control's tail (at most 46 device samples, none at level 3) and the drain. Real-time safe.
///
/// Returns `RR_DR60_STATUS_INVALID_SPEED_LEVEL` (checked first) or
/// `RR_DR60_STATUS_NO_SUCH_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_playback_length_samples(
    pipeline: *mut RrDr60Pipeline,
    number: u32,
    level: u8,
    out_samples: *mut u64,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_samples.is_null() {
        return RrDr60Status::NullPointer;
    }
    match p.inner.playback_length_samples(number, level) {
        Ok(len) => {
            // SAFETY: out_samples is non-null and writable (caller contract).
            unsafe { *out_samples = len };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// The speaker route's gain in dB at a volume position under the circuit's loaded law (spec
/// 009 FR-003; A-044): 22.7 dB at 1, about 9.6 dB at 0.5, −∞ at 0; in volts of amplifier output
/// per volt of codec output, for a host's volume display. Needs no handle; real-time safe.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_speaker_gain_db(position: f32) -> f32 {
    rr_dr60::output::speaker_gain_db(position)
}

/// The earphone route's gain in dB at a volume position under the loaded law (spec 009 FR-003;
/// A-044): 0 dB at 1, about −9.4 dB at 0.5, about −19.2 dB at `RR_DR60_VOLUME_REFERENCE`, −∞ at
/// 0. Needs no handle; real-time safe.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_earphone_gain_db(position: f32) -> f32 {
    rr_dr60::output::earphone_gain_db(position)
}

/// Writes the engine's state (idle, recording or playing), the route, the current recording's
/// number and whether the speaker is muted to `*out_state` (spec 006 FR-003). Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_state` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_state(
    pipeline: *mut RrDr60Pipeline,
    out_state: *mut RrDr60EngineState,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_state.is_null() {
        return RrDr60Status::NullPointer;
    }
    let st = p.inner.state();
    let state = RrDr60EngineState {
        state: match st.state {
            State::Idle => RrDr60State::Idle as u32,
            State::Recording => RrDr60State::Recording as u32,
            State::Playing => RrDr60State::Playing as u32,
            _ => RrDr60State::Idle as u32,
        },
        route: route_to_c(st.route),
        current_recording: st.current.unwrap_or(0),
        speaker_muted: st.speaker_muted,
    };
    // SAFETY: out_state is non-null and writable (caller contract).
    unsafe { *out_state = state };
    RrDr60Status::Ok
}

/// Writes the memory's figures to `*out_status`, in device samples (÷ 6000 for seconds,
/// A-026; spec 006 FR-011). Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_status` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_memory_status(
    pipeline: *mut RrDr60Pipeline,
    out_status: *mut RrDr60MemoryStatus,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_status.is_null() {
        return RrDr60Status::NullPointer;
    }
    let m = p.inner.memory_status();
    let status = RrDr60MemoryStatus {
        capacity_samples: m.capacity_samples,
        used_samples: m.used_samples,
        remaining_samples: m.remaining_samples,
        max_recordings: m.max_recordings,
        count: m.count,
        slots_remaining: m.slots_remaining,
    };
    // SAFETY: out_status is non-null and writable (caller contract).
    unsafe { *out_status = status };
    RrDr60Status::Ok
}

/// Writes the length of recording `number` in device samples (÷ 6000 for seconds, A-026) to
/// `*out_samples`. Real-time safe.
///
/// Statuses: `NO_SUCH_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_recording_length(
    pipeline: *mut RrDr60Pipeline,
    number: u32,
    out_samples: *mut u64,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_samples.is_null() {
        return RrDr60Status::NullPointer;
    }
    match p.inner.recording_length(number) {
        Ok(len) => {
            // SAFETY: out_samples is non-null and writable (caller contract).
            unsafe { *out_samples = len };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// Erases recording `number` (spec 006 FR-013; S-001): its time returns to "remaining" and
/// the later recordings move down by one. Erasing the recording being played, or erasing all,
/// stops the playback first; erasing a lower number renumbers the played item. **Not real-time
/// safe** (a memmove bounded by the store's size; no allocation).
///
/// Statuses: `RECORDING_IN_PROGRESS`, `NO_SUCH_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_erase(pipeline: *mut RrDr60Pipeline, number: u32) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match guarded(p, |inner| inner.erase(number)) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Erases every recording (spec 006 FR-013; S-001 "erase all"); a playback stops first; the
/// capacity is kept. Not real-time safe.
///
/// Statuses: `RECORDING_IN_PROGRESS`.
///
/// # Safety
///
/// `pipeline` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_erase_all(pipeline: *mut RrDr60Pipeline) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    match guarded(p, |inner| inner.erase_all()) {
        Ok(()) => RrDr60Status::Ok,
        Err(status) => status,
    }
}

/// Writes the exported length of recording `number`, in bytes, to `*out_len`, so the caller
/// can size the buffer for `rr_dr60_export` (spec 006 FR-014). Real-time safe.
///
/// Statuses: `NO_SUCH_RECORDING`.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_len` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_export_len(
    pipeline: *mut RrDr60Pipeline,
    number: u32,
    out_len: *mut usize,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_len.is_null() {
        return RrDr60Status::NullPointer;
    }
    match p.inner.export_len(number) {
        Ok(len) => {
            // SAFETY: out_len is non-null and writable (caller contract).
            unsafe { *out_len = len };
            RrDr60Status::Ok
        }
        Err(e) => status_from_error(e),
    }
}

/// Writes recording `number` as an opaque byte sequence into `out_bytes` (`capacity` bytes)
/// and the bytes written to `*out_written` (spec 006 FR-014). The host stores or sends the
/// bytes unchanged and never parses them; the same recording exports to the same bytes every
/// time. The form is version 2 (spec 008 FR-010): it declares the recording's encoding, the
/// speech codec's frames or device-rate samples when the codec was bypassed, and for frames the
/// codec's model version, so an importer knows which decoder the bytes need. Allowed in any
/// state. Not real-time safe (a CRC over the recording; no allocation).
///
/// Statuses: `NO_SUCH_RECORDING`; `BUFFER_TOO_SMALL` leaves `out_bytes` untouched and writes
/// the needed length to `*out_written` when not NULL; `NULL_POINTER` for a NULL `out_bytes`
/// (size queries go through `rr_dr60_export_len`).
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_bytes` must be writable for `capacity` bytes.
/// `out_written` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_export(
    pipeline: *mut RrDr60Pipeline,
    number: u32,
    out_bytes: *mut u8,
    capacity: usize,
    out_written: *mut usize,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_bytes.is_null() {
        return RrDr60Status::NullPointer;
    }
    let result = guarded(p, |inner| {
        // SAFETY: out_bytes is non-null and writable for `capacity` bytes (caller contract).
        let out = unsafe { std::slice::from_raw_parts_mut(out_bytes, capacity) };
        inner.export(number, out)
    });
    match result {
        Ok(written) => {
            // SAFETY: out_written is NULL or writable (caller contract).
            unsafe { put(out_written, written) };
            RrDr60Status::Ok
        }
        Err(RrDr60Status::BufferTooSmall) => {
            if let Ok(needed) = p.inner.export_len(number) {
                // SAFETY: out_written is NULL or writable (caller contract).
                unsafe { put(out_written, needed) };
            }
            RrDr60Status::BufferTooSmall
        }
        Err(status) => status,
    }
}

/// Adds a recording from the `len` bytes of an export (this or another engine of the same
/// version configured with the same encoding, any host rate) and writes its number to
/// `*out_number` when not NULL (spec 006 FR-014; spec 008 FR-010, FR-012). Allowed while idle
/// or playing; refused while recording. Not real-time safe (validates the whole sequence; no
/// allocation).
///
/// Statuses, in the form contract's order: `RECORDING_IN_PROGRESS`, `UNKNOWN_FORM`,
/// `UNSUPPORTED_FORM_VERSION` (form version 1, the never-released samples form of 0.6 and 0.7,
/// any later version, or non-zero flags; spec 008 FR-011), `DAMAGED`,
/// `UNSUPPORTED_CODEC_MODEL_VERSION` (frames of a codec model version this release cannot
/// decode; from the 1.0 release every released model version keeps its decoder),
/// `ENCODING_DIFFERS` (frames into a bypassed engine or samples into a codec engine; checked
/// before the fit), `DOES_NOT_FIT` (the remaining time or slots); the memory is unchanged on
/// every error.
///
/// # Safety
///
/// `pipeline` must be a live handle. `bytes` must be readable for `len` bytes. `out_number`
/// must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_import(
    pipeline: *mut RrDr60Pipeline,
    bytes: *const u8,
    len: usize,
    out_number: *mut u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if bytes.is_null() {
        return RrDr60Status::NullPointer;
    }
    let result = guarded(p, |inner| {
        // SAFETY: bytes is non-null and readable for `len` bytes (caller contract).
        let b = unsafe { std::slice::from_raw_parts(bytes, len) };
        inner.import(b)
    });
    match result {
        Ok(number) => {
            // SAFETY: out_number is NULL or writable (caller contract).
            unsafe { put(out_number, number) };
            RrDr60Status::Ok
        }
        Err(status) => status,
    }
}

/// Reads a `u32` figure of the pipeline into `*out`.
///
/// # Safety
///
/// As the three latency functions.
unsafe fn read_u32(
    pipeline: *mut RrDr60Pipeline,
    out: *mut u32,
    f: impl FnOnce(&Pipeline) -> u32,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out is non-null and writable (caller contract).
    unsafe { *out = f(&p.inner) };
    RrDr60Status::Ok
}

/// Writes the record path's latency in host samples (input samples until the corresponding
/// device sample is stored; the stop flush is this long) to `*out_samples` (spec 006 FR-016).
/// Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_record_latency_samples(
    pipeline: *mut RrDr60Pipeline,
    out_samples: *mut u32,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `read_u32`.
    unsafe { read_u32(pipeline, out_samples, Pipeline::record_latency_samples) }
}

/// Writes the playback path's latency in host samples (output samples from the start of
/// playback until the first stored sample is represented) to `*out_samples` (spec 006 FR-016).
/// The two path latencies sum to `rr_dr60_latency_samples` within one sample. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_playback_latency_samples(
    pipeline: *mut RrDr60Pipeline,
    out_samples: *mut u32,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `read_u32`.
    unsafe { read_u32(pipeline, out_samples, Pipeline::playback_latency_samples) }
}

/// Writes the host samples `rr_dr60_play` produces after the recording's own (the playback
/// path's settling drain) to `*out_samples` (spec 006 FR-008). Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_samples` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_drain_samples(
    pipeline: *mut RrDr60Pipeline,
    out_samples: *mut u32,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `read_u32`.
    unsafe { read_u32(pipeline, out_samples, Pipeline::drain_samples) }
}

/// Writes the bytes reserved for the recording store and its span table to `*out_bytes`
/// (spec 006 FR-017, SC-007; spec 008 SC-007): about 1.8 MB at the default capacity with the
/// speech codec on, about 86 MB with it bypassed, virtual until recordings are written.
/// Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_bytes` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_footprint_bytes(
    pipeline: *mut RrDr60Pipeline,
    out_bytes: *mut usize,
) -> RrDr60Status {
    // SAFETY: NULL or a live handle (caller contract).
    let p = match unsafe { live(pipeline) } {
        Ok(p) => p,
        Err(status) => return status,
    };
    if out_bytes.is_null() {
        return RrDr60Status::NullPointer;
    }
    // SAFETY: out_bytes is non-null and writable (caller contract).
    unsafe { *out_bytes = p.inner.footprint_bytes() };
    RrDr60Status::Ok
}

/// Writes the speech codec's constants to `*out` (spec 008 FR-003, FR-008): frame samples 120,
/// frame ms 20, bits per frame 80, delay samples 180, the codec model version. Needs no handle;
/// real-time safe.
///
/// Statuses: `NULL_POINTER`.
///
/// # Safety
///
/// `out` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_speech_codec_info(
    out: *mut RrDr60SpeechCodecInfo,
) -> RrDr60Status {
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    let i = rr_dr60::speech_codec::info();
    // SAFETY: out is non-null and writable (caller contract).
    unsafe {
        *out = RrDr60SpeechCodecInfo {
            frame_samples: i.frame_samples,
            frame_ms: i.frame_ms,
            bits_per_frame: i.bits_per_frame,
            delay_samples: i.delay_samples,
            model_version: i.model_version,
            reserved: 0,
        };
    }
    RrDr60Status::Ok
}

/// Writes the memory's encoding to `*out_encoding` (an `RrDr60Encoding` value; spec 008
/// FR-012): frames with the speech codec on, device-rate samples with it bypassed. An import of
/// the other encoding is `ENCODING_DIFFERS`. Real-time safe.
///
/// # Safety
///
/// `pipeline` must be a live handle. `out_encoding` must be NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_get_encoding(
    pipeline: *mut RrDr60Pipeline,
    out_encoding: *mut u32,
) -> RrDr60Status {
    // SAFETY: the caller contract of this function is that of `read_u32`.
    unsafe {
        read_u32(pipeline, out_encoding, |p| match p.encoding() {
            rr_dr60::Encoding::Samples => RrDr60Encoding::Samples as u32,
            _ => RrDr60Encoding::Frames as u32,
        })
    }
}

/// The library version as a static NUL-terminated string, e.g. `"0.1.0"`. Never NULL; do not
/// free.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_version_string() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// Test-only: makes the next `rr_dr60_process`, `rr_dr60_record` or `rr_dr60_play` call on
/// `pipeline` panic, to exercise panic
/// catching and poisoning (FR-024; tasks.md T054). Only built with the `ffi-test-panic` feature.
///
/// # Safety
///
/// `pipeline` must be NULL or a live handle.
#[cfg(feature = "ffi-test-panic")]
#[doc(hidden)]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60__test_force_panic(pipeline: *mut RrDr60Pipeline) {
    if !pipeline.is_null() {
        // SAFETY: non-null live handle (caller contract).
        unsafe { (*pipeline).force_panic = true };
    }
}

// ---- Spec 007: the stage manifest (contracts/c-api.md) ----------------------------------------

/// Whether and on what basis the engine models a stage (spec 007 FR-004); carried in
/// `RrDr60StageEntry.status` as a `uint32_t`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60StageStatus {
    /// The engine passes the signal through or represents the stage as a label.
    NotModeled = 0,
    /// Modeled, at least one cited assumption open.
    Assumed = 1,
    /// Modeled, every cited assumption verified against a document (none today).
    Sourced = 2,
    /// Modeled, every cited assumption verified or measured, at least one measured against a
    /// real unit (none today).
    Checked = 3,
}

/// Which signal path a stage belongs to; carried in `RrDr60StageEntry.path` as a `uint32_t`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60StagePath {
    /// Microphone to memory.
    Record = 0,
    /// Memory to speaker or earphone.
    Playback = 1,
    /// Both paths.
    Both = 2,
}

/// The project's confidence in a modeled stage; carried in `RrDr60StageEntry.confidence` as a
/// `uint32_t`. `NOT_APPLICABLE` exactly for stages that are not modeled.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60Confidence {
    /// Not modeled.
    NotApplicable = 0,
    /// Low.
    Low = 1,
    /// Medium.
    Medium = 2,
    /// High.
    High = 3,
}

/// The stage manifest's header (spec 007 FR-003), filled by `rr_dr60_manifest_header`.
///
/// Every `const char *` is non-NULL, NUL-terminated UTF-8, points at static storage inside the
/// library and stays valid and unchanged for the life of the process: keep it by reference,
/// never free it. The struct grows only at the end.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RrDr60ManifestHeader {
    /// The library's version, e.g. `"0.7.0"`.
    pub library_version: *const c_char,
    /// The device's internal sample rate, 6000 Hz (A-026).
    pub device_rate_hz: u32,
    /// The number of stage entries, 15.
    pub stage_count: u32,
    /// Stages with status `RR_DR60_STAGE_STATUS_NOT_MODELED`.
    pub count_not_modeled: u32,
    /// Stages with status `RR_DR60_STAGE_STATUS_ASSUMED`.
    pub count_assumed: u32,
    /// Stages with status `RR_DR60_STAGE_STATUS_SOURCED`.
    pub count_sourced: u32,
    /// Stages with status `RR_DR60_STAGE_STATUS_CHECKED`; the four counts sum to `stage_count`.
    pub count_checked: u32,
    /// One neutral sentence on what the model rests on.
    pub basis: *const c_char,
    /// The hardware-evidence capture form.
    pub evidence_link: *const c_char,
    /// The assumption register page (append `#:~:text=A-028` to land on a row).
    pub assumptions_link: *const c_char,
    /// The source register page.
    pub sources_link: *const c_char,
}

impl Default for RrDr60ManifestHeader {
    fn default() -> Self {
        Self {
            library_version: std::ptr::null(),
            device_rate_hz: 0,
            stage_count: 0,
            count_not_modeled: 0,
            count_assumed: 0,
            count_sourced: 0,
            count_checked: 0,
            basis: std::ptr::null(),
            evidence_link: std::ptr::null(),
            assumptions_link: std::ptr::null(),
            sources_link: std::ptr::null(),
        }
    }
}

/// One stage of the manifest (spec 007 FR-002), filled by `rr_dr60_manifest_stage`.
///
/// Strings as in `RrDr60ManifestHeader`: static, NUL-terminated UTF-8, never NULL; an empty
/// note is `""`. The IDs are reached by index through `rr_dr60_manifest_stage_source` and
/// `rr_dr60_manifest_stage_assumption`. The struct grows only at the end.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RrDr60StageEntry {
    /// 1 to 15, the signal-chain table's row number.
    pub number: u32,
    /// The stable ASCII key (the key for localization).
    pub identifier: *const c_char,
    /// The display name.
    pub name: *const c_char,
    /// One sentence on what the stage does to sound on the device.
    pub description: *const c_char,
    /// `RrDr60StageStatus`.
    pub status: u32,
    /// `RrDr60StagePath`.
    pub path: u32,
    /// `RrDr60Confidence`.
    pub confidence: u32,
    /// How many source IDs `rr_dr60_manifest_stage_source` can return.
    pub source_count: u32,
    /// How many assumption IDs `rr_dr60_manifest_stage_assumption` can return.
    pub assumption_count: u32,
    /// What the engine leaves out at this stage (`""` when nothing or not modeled).
    pub coverage: *const c_char,
    /// The Rust API items that touch the stage (`""` when none).
    pub controls: *const c_char,
    /// The library version in which the stage's model last changed (`""` when not modeled).
    pub model_version: *const c_char,
}

impl Default for RrDr60StageEntry {
    fn default() -> Self {
        Self {
            number: 0,
            identifier: std::ptr::null(),
            name: std::ptr::null(),
            description: std::ptr::null(),
            status: 0,
            path: 0,
            confidence: 0,
            source_count: 0,
            assumption_count: 0,
            coverage: std::ptr::null(),
            controls: std::ptr::null(),
            model_version: std::ptr::null(),
        }
    }
}

/// A pointer into one of the core's NUL-terminated static twins (valid for the process).
fn manifest_cstr(bytes: &'static [u8]) -> *const c_char {
    bytes.as_ptr().cast()
}

/// Runs a manifest read under the crate's panic-catching convention (contracts/c-api.md): the
/// functions touch only static data, so the `Err` arm cannot be reached.
fn manifest_guard<T>(f: impl FnOnce() -> T) -> Result<T, RrDr60Status> {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(v) => Ok(v),
        // coverage: unreachable, static data (Constitution III)
        Err(_) => Err(panic_to_status(None)),
    }
}

/// The index of a stage number, or `None` for 0 or above the stage count.
fn manifest_stage_index(number: u32) -> Option<usize> {
    let n = number as usize;
    (1..=rr_dr60::manifest::STAGE_COUNT)
        .contains(&n)
        .then(|| n - 1)
}

fn manifest_entry_c(c: &'static rr_dr60::manifest::__c::StageEntryC) -> RrDr60StageEntry {
    RrDr60StageEntry {
        number: c.number,
        identifier: manifest_cstr(c.identifier),
        name: manifest_cstr(c.name),
        description: manifest_cstr(c.description),
        status: c.status,
        path: c.path,
        confidence: c.confidence,
        source_count: c.sources.len() as u32,
        assumption_count: c.assumptions.len() as u32,
        coverage: manifest_cstr(c.coverage),
        controls: manifest_cstr(c.controls),
        model_version: manifest_cstr(c.model_version),
    }
}

/// The number of stage entries in the manifest, 15 (spec 007 FR-017). Real-time safe.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_manifest_stage_count() -> u32 {
    rr_dr60::manifest::STAGE_COUNT as u32
}

/// Copies the manifest's header into `*out` (spec 007 FR-003, FR-017). Real-time safe; needs no
/// handle and may be called before any `rr_dr60_create`.
///
/// # Safety
///
/// `out` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`, nothing written) or point to a
/// writable `RrDr60ManifestHeader`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_manifest_header(out: *mut RrDr60ManifestHeader) -> RrDr60Status {
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    match manifest_guard(|| {
        let h = &rr_dr60::manifest::__c::HEADER;
        RrDr60ManifestHeader {
            library_version: manifest_cstr(h.library_version),
            device_rate_hz: h.device_rate_hz,
            stage_count: h.stage_count,
            count_not_modeled: h.count_not_modeled,
            count_assumed: h.count_assumed,
            count_sourced: h.count_sourced,
            count_checked: h.count_checked,
            basis: manifest_cstr(h.basis),
            evidence_link: manifest_cstr(h.evidence_link),
            assumptions_link: manifest_cstr(h.assumptions_link),
            sources_link: manifest_cstr(h.sources_link),
        }
    }) {
        Ok(v) => {
            // SAFETY: out is non-null and writable (caller contract).
            unsafe { put(out, v) };
            RrDr60Status::Ok
        }
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

/// Copies stage `number` (1 to 15) into `*out` (spec 007 FR-002, FR-017). Real-time safe.
/// Check order: NULL first, then the range; nothing is written on a refusal.
///
/// # Safety
///
/// `out` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable
/// `RrDr60StageEntry`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_manifest_stage(
    number: u32,
    out: *mut RrDr60StageEntry,
) -> RrDr60Status {
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    let Some(idx) = manifest_stage_index(number) else {
        return RrDr60Status::NoSuchStage;
    };
    match manifest_guard(|| manifest_entry_c(&rr_dr60::manifest::__c::STAGES[idx])) {
        Ok(v) => {
            // SAFETY: out is non-null and writable (caller contract).
            unsafe { put(out, v) };
            RrDr60Status::Ok
        }
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

/// Writes the `index`-th (0-based, ascending) source ID (`S-###`) of stage `number` into
/// `*out_id` (spec 007 FR-005, FR-017). `RR_DR60_STATUS_NO_SUCH_STAGE` for a number outside
/// 1 to 15, `RR_DR60_STATUS_INVALID_ARGUMENT` for `index >= source_count`; nothing written on
/// a refusal. Real-time safe.
///
/// # Safety
///
/// `out_id` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_manifest_stage_source(
    number: u32,
    index: u32,
    out_id: *mut *const c_char,
) -> RrDr60Status {
    // SAFETY: forwarded caller contract.
    unsafe { manifest_id(number, index, out_id, |c| c.sources) }
}

/// Writes the `index`-th (0-based, ascending) assumption ID (`A-###`) of stage `number` into
/// `*out_id` (spec 007 FR-005, FR-017); refusals as `rr_dr60_manifest_stage_source`. Real-time
/// safe.
///
/// # Safety
///
/// `out_id` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_manifest_stage_assumption(
    number: u32,
    index: u32,
    out_id: *mut *const c_char,
) -> RrDr60Status {
    // SAFETY: forwarded caller contract.
    unsafe { manifest_id(number, index, out_id, |c| c.assumptions) }
}

/// The shared body of the two ID accessors: NULL, then the stage, then the index.
///
/// # Safety
///
/// `out_id` must be NULL or point to a writable pointer.
unsafe fn manifest_id(
    number: u32,
    index: u32,
    out_id: *mut *const c_char,
    list: impl FnOnce(&'static rr_dr60::manifest::__c::StageEntryC) -> &'static [&'static [u8]],
) -> RrDr60Status {
    if out_id.is_null() {
        return RrDr60Status::NullPointer;
    }
    let Some(idx) = manifest_stage_index(number) else {
        return RrDr60Status::NoSuchStage;
    };
    match manifest_guard(|| {
        list(&rr_dr60::manifest::__c::STAGES[idx])
            .get(index as usize)
            .map(|id| manifest_cstr(id))
    }) {
        Ok(Some(ptr)) => {
            // SAFETY: out_id is non-null and writable (caller contract).
            unsafe { put(out_id, ptr) };
            RrDr60Status::Ok
        }
        Ok(None) => RrDr60Status::InvalidArgument,
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

// ---- Spec 014: the control manifest (contracts/api.md) ---------------------------------------

/// `RR_DR60_CONTROL_PATH_*` bit: the record path (spec 014 FR-013).
pub const RR_DR60_CONTROL_PATH_RECORD: u32 = 1; // 014 FR-013: rr_dr60::ControlPaths::RECORD (pinned)
/// `RR_DR60_CONTROL_PATH_*` bit: the playback path.
pub const RR_DR60_CONTROL_PATH_PLAYBACK: u32 = 2; // 014 FR-013: rr_dr60::ControlPaths::PLAYBACK (pinned)
/// `RR_DR60_CONTROL_PATH_*` bit: the one-pass engine (`rr_dr60_process`).
pub const RR_DR60_CONTROL_PATH_ONE_PASS: u32 = 4; // 014 FR-013: rr_dr60::ControlPaths::ONE_PASS (pinned)

/// What kind of adjustment a control is (spec 014 FR-003); carried in `RrDr60Control.kind`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60ControlKind {
    /// A control the owner's manual or the service manual gives the user.
    DeviceControl = 0,
    /// A physical state of one unit.
    UnitCondition = 1,
    /// A value the device has that its user cannot reach.
    ModelInternal = 2,
    /// Something the device cannot do.
    EmulatorOption = 3,
    /// Set by the host for reproducibility or by its audio session.
    HostParameter = 4,
}

/// When a control may change (spec 014 FR-004); carried in `RrDr60Control.timing`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60ControlTiming {
    /// Changes while the engine runs (a `rr_dr60_set_*` function).
    Live = 0,
    /// Applied by `rr_dr60_reconfigure` when nothing is recording or playing.
    Idle = 1,
    /// Idle, and refused while the stored recordings do not fit the new value.
    IdleMemoryDependent = 2,
    /// Set by the host to match its audio session.
    HostFixed = 3,
}

/// A control's value type (spec 014 FR-002); carried in `RrDr60Control.value_type`.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RrDr60ControlValueType {
    /// Off or on; the default in `int_default` (0 or 1).
    Switch = 0,
    /// An integer in `int_min ..= int_max`, step 1.
    Integer = 1,
    /// A continuous value in `float_min ..= float_max`, step 0 (continuous).
    Continuous = 2,
    /// One of `option_count` options (`rr_dr60_control_option`); the default's value in
    /// `choice_default` when `has_default` is 1.
    Choice = 3,
}

/// One control of the control manifest (spec 014 FR-002, FR-013), filled by
/// `rr_dr60_control`. Strings are static, NUL-terminated UTF-8, never NULL (an empty unit is
/// `""`). Fields of the value types the control does not have are zero. No size field and no
/// growth promise: the struct is on the pre-1.0 ABI-pass list (spec 014, owner decision 4).
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RrDr60Control {
    /// The stable identifier (the key for localization), e.g. `vas.sensitivity`.
    pub identifier: *const c_char,
    /// The display name.
    pub name: *const c_char,
    /// The unit, or `""`.
    pub unit: *const c_char,
    /// One sentence on what changing the control does to the sound.
    pub description: *const c_char,
    /// `RrDr60ControlKind`.
    pub kind: u32,
    /// `RrDr60ControlTiming`.
    pub timing: u32,
    /// `RR_DR60_CONTROL_PATH_*` bits.
    pub paths: u32,
    /// The signal-chain stage, 1 to 15, or 0 for none.
    pub stage: u32,
    /// `RrDr60ControlValueType`.
    pub value_type: u32,
    /// Explicit padding before the 64-bit fields (spec 010 lesson); always 0.
    pub reserved_014: u32,
    /// Integer minimum.
    pub int_min: u64,
    /// Integer maximum.
    pub int_max: u64,
    /// Integer default, or a switch's default (0 or 1).
    pub int_default: u64,
    /// Continuous minimum.
    pub float_min: f32,
    /// Continuous maximum.
    pub float_max: f32,
    /// Continuous default.
    pub float_default: f32,
    /// How many options `rr_dr60_control_option` can return.
    pub option_count: u32,
    /// The default option's value (when `has_default` is 1).
    pub choice_default: u32,
    /// 1 when the control has an engine default (the host rate has none).
    pub has_default: u32,
    /// How many source IDs `rr_dr60_control_source` can return.
    pub source_count: u32,
    /// How many assumption IDs `rr_dr60_control_assumption` can return.
    pub assumption_count: u32,
}

const _: () = assert!(
    std::mem::offset_of!(RrDr60Control, reserved_014) + 4
        == std::mem::offset_of!(RrDr60Control, int_min)
);
const _: () = assert!(std::mem::offset_of!(RrDr60Control, int_min) % 8 == 0);
const _: () = assert!(
    std::mem::offset_of!(RrDr60Control, assumption_count) + 4 == size_of::<RrDr60Control>()
);

impl Default for RrDr60Control {
    fn default() -> Self {
        Self {
            identifier: std::ptr::null(),
            name: std::ptr::null(),
            unit: std::ptr::null(),
            description: std::ptr::null(),
            kind: 0,
            timing: 0,
            paths: 0,
            stage: 0,
            value_type: 0,
            reserved_014: 0,
            int_min: 0,
            int_max: 0,
            int_default: 0,
            float_min: 0.0,
            float_max: 0.0,
            float_default: 0.0,
            option_count: 0,
            choice_default: 0,
            has_default: 0,
            source_count: 0,
            assumption_count: 0,
        }
    }
}

/// One option of a choice (spec 014 FR-002), filled by `rr_dr60_control_option`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RrDr60ControlOption {
    /// The stable identifier, e.g. `earphone`, `after_record`, `hz_48000`.
    pub identifier: *const c_char,
    /// The value the engine takes: the C enumeration value, or the rate in hertz.
    pub value: u32,
}

impl Default for RrDr60ControlOption {
    fn default() -> Self {
        Self {
            identifier: std::ptr::null(),
            value: 0,
        }
    }
}

fn control_c(index: usize) -> RrDr60Control {
    let e = &rr_dr60::controls()[index];
    let c = &rr_dr60::controls::__c::CONTROLS[index];
    let mut out = RrDr60Control {
        identifier: manifest_cstr(c.identifier),
        name: manifest_cstr(c.name),
        unit: manifest_cstr(c.unit),
        description: manifest_cstr(c.description),
        kind: e.kind as u32,
        timing: e.timing as u32,
        paths: u32::from(e.paths.bits()),
        stage: u32::from(e.stage),
        source_count: e.sources.len() as u32,
        assumption_count: e.assumptions.len() as u32,
        has_default: 1,
        ..RrDr60Control::default()
    };
    match e.value {
        rr_dr60::ControlValue::Switch { default } => {
            out.value_type = RrDr60ControlValueType::Switch as u32;
            out.int_max = 1;
            out.int_default = u64::from(default);
        }
        rr_dr60::ControlValue::Integer { min, max, default } => {
            out.value_type = RrDr60ControlValueType::Integer as u32;
            out.int_min = min;
            out.int_max = max;
            out.int_default = default;
        }
        rr_dr60::ControlValue::Continuous { min, max, default } => {
            out.value_type = RrDr60ControlValueType::Continuous as u32;
            out.float_min = min;
            out.float_max = max;
            out.float_default = default;
        }
        rr_dr60::ControlValue::Choice { options, default } => {
            out.value_type = RrDr60ControlValueType::Choice as u32;
            out.option_count = options.len() as u32;
            out.choice_default = default.unwrap_or(0);
            out.has_default = u32::from(default.is_some());
        }
        // coverage: unreachable, every value type is listed (Constitution III)
        _ => {}
    }
    out
}

/// The number of controls in the control manifest, 29 (spec 014 FR-013). Real-time safe.
#[unsafe(no_mangle)]
pub extern "C" fn rr_dr60_control_count() -> u32 {
    rr_dr60::controls::CONTROL_COUNT as u32
}

/// Copies control `index` (0-based, in the manifest's order) into `*out` (spec 014 FR-013).
/// Real-time safe; needs no handle. Check order: NULL first (`RR_DR60_STATUS_NULL_POINTER`),
/// then the index (`RR_DR60_STATUS_NO_SUCH_CONTROL`); nothing is written on a refusal.
///
/// # Safety
///
/// `out` must be NULL or point to a writable `RrDr60Control`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_control(index: u32, out: *mut RrDr60Control) -> RrDr60Status {
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    if index as usize >= rr_dr60::controls::CONTROL_COUNT {
        return RrDr60Status::NoSuchControl;
    }
    match manifest_guard(|| control_c(index as usize)) {
        Ok(v) => {
            // SAFETY: out is non-null and writable (caller contract).
            unsafe { put(out, v) };
            RrDr60Status::Ok
        }
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

/// Copies option `option` (0-based) of control `index` into `*out` (spec 014 FR-013).
/// `RR_DR60_STATUS_NO_SUCH_CONTROL` for an index past the controls or past the control's
/// `option_count` (0 unless a choice); nothing written on a refusal. Real-time safe.
///
/// # Safety
///
/// `out` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable
/// `RrDr60ControlOption`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_control_option(
    index: u32,
    option: u32,
    out: *mut RrDr60ControlOption,
) -> RrDr60Status {
    if out.is_null() {
        return RrDr60Status::NullPointer;
    }
    match manifest_guard(|| {
        let i = index as usize;
        let e = rr_dr60::controls().get(i)?;
        let rr_dr60::ControlValue::Choice { options, .. } = e.value else {
            return None;
        };
        let o = options.get(option as usize)?;
        let name = rr_dr60::controls::__c::CONTROLS[i].options[option as usize];
        Some(RrDr60ControlOption {
            identifier: manifest_cstr(name),
            value: o.value,
        })
    }) {
        Ok(Some(v)) => {
            // SAFETY: out is non-null and writable (caller contract).
            unsafe { put(out, v) };
            RrDr60Status::Ok
        }
        Ok(None) => RrDr60Status::NoSuchControl,
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

/// Writes the `i`-th (0-based, ascending) source ID of control `index` into `*out_id` (spec
/// 014 FR-013); `RR_DR60_STATUS_NO_SUCH_CONTROL` for an index past either list. Real-time safe.
///
/// # Safety
///
/// `out_id` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_control_source(
    index: u32,
    i: u32,
    out_id: *mut *const c_char,
) -> RrDr60Status {
    // SAFETY: forwarded caller contract.
    unsafe { control_id(index, i, out_id, |c| c.sources) }
}

/// Writes the `i`-th (0-based, ascending) assumption ID of control `index` into `*out_id`;
/// refusals as `rr_dr60_control_source`. Real-time safe.
///
/// # Safety
///
/// `out_id` must be NULL (then `RR_DR60_STATUS_NULL_POINTER`) or point to a writable pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rr_dr60_control_assumption(
    index: u32,
    i: u32,
    out_id: *mut *const c_char,
) -> RrDr60Status {
    // SAFETY: forwarded caller contract.
    unsafe { control_id(index, i, out_id, |c| c.assumptions) }
}

/// The shared body of the two control ID accessors: NULL, then the indices.
///
/// # Safety
///
/// `out_id` must be NULL or point to a writable pointer.
unsafe fn control_id(
    index: u32,
    i: u32,
    out_id: *mut *const c_char,
    list: impl FnOnce(&'static rr_dr60::controls::__c::ControlStringsC) -> &'static [&'static [u8]],
) -> RrDr60Status {
    if out_id.is_null() {
        return RrDr60Status::NullPointer;
    }
    match manifest_guard(|| {
        let c = rr_dr60::controls::__c::CONTROLS.get(index as usize)?;
        list(c).get(i as usize).map(|id| manifest_cstr(id))
    }) {
        Ok(Some(ptr)) => {
            // SAFETY: out_id is non-null and writable (caller contract).
            unsafe { put(out_id, ptr) };
            RrDr60Status::Ok
        }
        Ok(None) => RrDr60Status::NoSuchControl,
        // coverage: unreachable, static data (Constitution III)
        Err(status) => status,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn version_constants_match_crate_version() {
        let v = format!("{RR_DR60_VERSION_MAJOR}.{RR_DR60_VERSION_MINOR}.{RR_DR60_VERSION_PATCH}");
        assert_eq!(v, env!("CARGO_PKG_VERSION"));
        assert_eq!(v, rr_dr60::VERSION);
        // SAFETY: the version string is a static NUL-terminated string.
        let s = unsafe { std::ffi::CStr::from_ptr(rr_dr60_version_string()) };
        assert_eq!(s.to_str().unwrap(), v);
    }

    #[test]
    fn settings_validation() {
        let mut s = rr_dr60_settings_default(48_000);
        assert_eq!(s.struct_size as usize, size_of::<RrDr60Settings>());
        assert!(to_settings(&s).is_ok());
        s.tap = 11; // 0 – 10 are taps since 0.12 (spec 012 contracts/c-api.md)
        assert_eq!(
            to_settings(&s),
            Err((RrDr60Status::InvalidArgument, RrDr60SettingField::Tap))
        );
        s.tap = RrDr60Tap::AfterVas as u32;
        assert_eq!(to_settings(&s).unwrap().tap, Tap::AfterVas);
        // Spec 012 FR-012: the hiss offset maps to its own field when refused.
        let mut h = rr_dr60_settings_default(48_000);
        h.mic_hiss_offset_db = 13.0;
        let p = to_settings(&h).unwrap();
        assert_eq!(
            error_to_status_and_field(p.validate().unwrap_err()),
            (
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::MicHissOffsetDb
            )
        );
        assert_eq!(RrDr60SettingField::MicHissOffsetDb as u32, 16);
        s.vas_mode = 7;
        assert_eq!(
            to_settings(&s),
            Err((RrDr60Status::InvalidArgument, RrDr60SettingField::VasMode))
        );
        s.vas_mode = RrDr60VasMode::Mute as u32;
        assert_eq!(to_settings(&s).unwrap().vas.mode, VasMode::Mute);
        s.vas_sensitivity = 259; // must not wrap to 3
        assert_eq!(to_settings(&s).unwrap().vas.sensitivity, u8::MAX);
        assert_eq!(
            validate_c(&s),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::VasSensitivity
            ))
        );
        s.vas_sensitivity = 3;
        s.tap = RrDr60Tap::AfterRecord as u32;
        assert_eq!(to_settings(&s).unwrap().tap, Tap::AfterRecord);
        s.tap = RrDr60Tap::AfterAgc as u32;
        assert_eq!(to_settings(&s).unwrap().tap, Tap::AfterAgc);
        s.agc_release_ms = 3000.0;
        assert_eq!(to_settings(&s).unwrap().agc.release_ms, 3000.0);
        assert_eq!(
            to_settings(&rr_dr60_settings_default(48_000)).unwrap(),
            Settings::new(48_000)
        );
        s.struct_size = 48; // the 0.2 size
        assert_eq!(
            to_settings(&s),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
    }

    /// 005 T008 (spec 005 FR-015), restated by 006 T017 (spec 006 FR-020; contracts/c-api.md):
    /// the 0.6 layout is 88 bytes with every 0.5 offset kept and the two memory fields appended
    /// at 76 and 80.
    #[test]
    fn settings_layout_is_120_bytes_with_the_contract_offsets() {
        use std::mem::offset_of;
        assert_eq!(size_of::<RrDr60Settings>(), 120); // spec 012 contracts/c-api.md
        assert_eq!(align_of::<RrDr60Settings>(), 8); // `seed: u64`
        assert_eq!(offset_of!(RrDr60Settings, struct_size), 0);
        assert_eq!(offset_of!(RrDr60Settings, host_rate_hz), 4);
        assert_eq!(offset_of!(RrDr60Settings, record_stage_enabled), 8);
        assert_eq!(offset_of!(RrDr60Settings, playback_stage_enabled), 9);
        assert_eq!(offset_of!(RrDr60Settings, tap), 12);
        assert_eq!(offset_of!(RrDr60Settings, seed), 16);
        assert_eq!(offset_of!(RrDr60Settings, agc_enabled), 24);
        assert_eq!(offset_of!(RrDr60Settings, agc_knee_dbfs), 28);
        assert_eq!(offset_of!(RrDr60Settings, reserved_agc_1), 32);
        assert_eq!(offset_of!(RrDr60Settings, reserved_agc_2), 36);
        assert_eq!(offset_of!(RrDr60Settings, agc_attack_ms), 40);
        assert_eq!(offset_of!(RrDr60Settings, agc_release_ms), 44);
        assert_eq!(offset_of!(RrDr60Settings, vas_enabled), 48);
        assert_eq!(offset_of!(RrDr60Settings, vas_mode), 52);
        assert_eq!(offset_of!(RrDr60Settings, vas_sensitivity), 56);
        assert_eq!(offset_of!(RrDr60Settings, vas_threshold_dbfs), 60);
        assert_eq!(offset_of!(RrDr60Settings, vas_hang_ms), 64);
        assert_eq!(offset_of!(RrDr60Settings, vas_onset_ms), 68);
        assert_eq!(offset_of!(RrDr60Settings, adc_clamp_enabled), 72);
        assert_eq!(offset_of!(RrDr60Settings, memory_capacity_s), 76);
        assert_eq!(offset_of!(RrDr60Settings, memory_max_recordings), 80);
        // Spec 008 contracts/c-api.md: 88 → 96, the codec control at 88 behind a reserved word.
        assert_eq!(offset_of!(RrDr60Settings, reserved_008), 84);
        assert_eq!(offset_of!(RrDr60Settings, speech_codec_enabled), 88);
        // Spec 009 contracts/c-api.md: 96 → 104, the three output bools after the 0.8 size (the
        // 0.8 tail padding 89 – 95 stays reserved so a stale `struct_size = 96` is refused).
        assert_eq!(offset_of!(RrDr60Settings, reserved_009), 89);
        assert_eq!(offset_of!(RrDr60Settings, output_volume_amp_enabled), 96);
        assert_eq!(offset_of!(RrDr60Settings, output_speaker_enabled), 97);
        assert_eq!(offset_of!(RrDr60Settings, output_earphone_enabled), 98);
        // Spec 010 contracts/c-api.md: 104 → 112, the option at 104 behind the explicit 0.9
        // tail padding, followed by this layout's explicit tail.
        assert_eq!(offset_of!(RrDr60Settings, reserved_010), 99);
        assert_eq!(offset_of!(RrDr60Settings, output_clamp_enabled), 104);
        assert_eq!(offset_of!(RrDr60Settings, reserved_010_tail), 105);
        // Spec 012 contracts/c-api.md: 112 → 120, the microphone path's fields after the 0.11
        // size (the bools at 112 and 113, an explicit reserved pair, the offset at 116).
        assert_eq!(offset_of!(RrDr60Settings, mic_capsule_enabled), 112);
        assert_eq!(offset_of!(RrDr60Settings, mic_amp_enabled), 113);
        assert_eq!(offset_of!(RrDr60Settings, reserved_012), 114);
        assert_eq!(offset_of!(RrDr60Settings, mic_hiss_offset_db), 116);
        let d = rr_dr60_settings_default(48_000);
        assert!(!d.output_clamp_enabled); // 010 FR-002
        assert_eq!(d.reserved_010, [0; 5]);
        assert_eq!(d.reserved_010_tail, [0; 7]);
        assert_eq!(d.reserved_012, [0; 2]);
        assert_eq!(d.mic_hiss_offset_db, 0.0); // 012 FR-003
        assert_eq!(RR_DR60_VERSION_MINOR, 20);
        let mut stale = rr_dr60_settings_default(48_000);
        stale.struct_size = 112; // a 0.10 or 0.11 caller (spec 012 FR-012)
        assert_eq!(
            to_settings(&stale),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
        stale.struct_size = 104; // a 0.9 caller (spec 010 FR-008)
        assert_eq!(
            to_settings(&stale),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
        stale.struct_size = 96; // a 0.8 caller
        assert_eq!(
            to_settings(&stale),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
    }

    /// 009 T029 (spec 009 FR-014; contracts/c-api.md): the volume functions and the constant.
    /// `RR_DR60_VOLUME_REFERENCE` is the Rust constant bit for bit; the gain functions equal the
    /// Rust ones at six positions; `rr_dr60_set_volume` refuses 1.5, −1, NaN and ∞ with
    /// `INVALID_VOLUME` and leaves the position; a NULL out pointer is `NULL_POINTER` (the
    /// convention of every `rr_dr60_get_*`); `rr_dr60_process` with the speaker tap on the
    /// earphone route is `TAP_NOT_ON_ROUTE` with `produced` 0.
    #[test]
    fn volume_functions_and_route_tap_refusal() {
        assert_eq!(
            RR_DR60_VOLUME_REFERENCE.to_bits(),
            rr_dr60::output::VOLUME_REFERENCE.to_bits()
        );
        // Spec 011 T034: the transition's length is the Rust constant.
        assert_eq!(
            RR_DR60_VOLUME_TRANSITION_MS,
            rr_dr60::output::VOLUME_TRANSITION_MS
        );
        // Spec 013 T028: the speed defines are the Rust constants.
        assert_eq!(
            RR_DR60_SPEED_LEVEL_COUNT,
            u32::from(rr_dr60::speed::LEVEL_COUNT)
        );
        assert_eq!(
            RR_DR60_SPEED_DEFAULT_LEVEL,
            u32::from(rr_dr60::speed::DEFAULT_LEVEL)
        );
        assert_eq!(
            RR_DR60_SPEED_RATIO_DENOMINATOR,
            rr_dr60::speed::RATIO_DENOMINATOR
        );
        assert_eq!(
            [
                RR_DR60_SPEED_RATIO_NUMERATOR_1,
                RR_DR60_SPEED_RATIO_NUMERATOR_2,
                RR_DR60_SPEED_RATIO_NUMERATOR_3,
                RR_DR60_SPEED_RATIO_NUMERATOR_4,
                RR_DR60_SPEED_RATIO_NUMERATOR_5,
            ],
            rr_dr60::speed::RATIO_NUMERATORS
        );
        for p in [1.0f32, 0.5, 0.25, RR_DR60_VOLUME_REFERENCE, 0.1, 0.01] {
            assert_eq!(
                rr_dr60_speaker_gain_db(p).to_bits(),
                rr_dr60::output::speaker_gain_db(p).to_bits()
            );
            assert_eq!(
                rr_dr60_earphone_gain_db(p).to_bits(),
                rr_dr60::output::earphone_gain_db(p).to_bits()
            );
        }
        let s = rr_dr60_settings_default(48_000);
        let mut p: *mut RrDr60Pipeline = std::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut p) }, RrDr60Status::Ok);
        let mut v = -1.0f32;
        // SAFETY: live handle; valid out pointer.
        assert_eq!(unsafe { rr_dr60_get_volume(p, &mut v) }, RrDr60Status::Ok);
        assert_eq!(v, RR_DR60_VOLUME_REFERENCE);
        for bad in [1.5f32, -1.0, f32::NAN, f32::INFINITY] {
            // SAFETY: live handle.
            assert_eq!(
                unsafe { rr_dr60_set_volume(p, bad) },
                RrDr60Status::InvalidVolume,
                "{bad}"
            );
            // SAFETY: live handle; valid out pointer.
            assert_eq!(unsafe { rr_dr60_get_volume(p, &mut v) }, RrDr60Status::Ok);
            assert_eq!(v, RR_DR60_VOLUME_REFERENCE, "unchanged after {bad}");
        }
        // SAFETY: live handle.
        assert_eq!(unsafe { rr_dr60_set_volume(p, 0.5) }, RrDr60Status::Ok);
        // SAFETY: live handle; valid out pointer.
        assert_eq!(unsafe { rr_dr60_get_volume(p, &mut v) }, RrDr60Status::Ok);
        assert_eq!(v, 0.5);
        // SAFETY: live handle; a NULL out pointer must be refused.
        assert_eq!(
            unsafe { rr_dr60_get_volume(p, std::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
        // SAFETY: NULL handle.
        assert_eq!(
            unsafe { rr_dr60_set_volume(std::ptr::null_mut(), 0.5) },
            RrDr60Status::NullPointer
        );
        // SAFETY: live handle.
        unsafe { rr_dr60_destroy(p) };
        // The route-tap refusal through the processing call.
        let mut s = rr_dr60_settings_default(48_000);
        s.tap = RrDr60Tap::AfterSpeaker as u32;
        let mut p: *mut RrDr60Pipeline = std::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut p) }, RrDr60Status::Ok);
        // SAFETY: live handle.
        assert_eq!(
            unsafe { rr_dr60_set_route(p, RrDr60Route::Earphone as u32) },
            RrDr60Status::Ok
        );
        let x = [0.1f32; 64];
        let mut y = [0.0f32; 64];
        let mut info = RrDr60BlockInfo::default();
        // SAFETY: live handle; valid buffers.
        let status = unsafe { rr_dr60_process(p, x.as_ptr(), y.as_mut_ptr(), 64, &mut info) };
        assert_eq!(status, RrDr60Status::TapNotOnRoute);
        assert_eq!(info.produced, 0);
        // SAFETY: live handle.
        assert_eq!(
            unsafe { rr_dr60_set_route(p, RrDr60Route::Speaker as u32) },
            RrDr60Status::Ok
        );
        // SAFETY: live handle; valid buffers.
        let status = unsafe { rr_dr60_process(p, x.as_ptr(), y.as_mut_ptr(), 64, &mut info) };
        assert_eq!(status, RrDr60Status::Ok);
        // SAFETY: live handle.
        unsafe { rr_dr60_destroy(p) };
    }

    /// 009 T006 (spec 009 contracts/c-api.md): taps 0 – 8 convert both ways, 9 is refused, the
    /// stage-10 alias, the statuses 23 and 24, the defaults' three output bools and tap.
    #[test]
    fn output_chain_taps_statuses_and_defaults() {
        let mut s = rr_dr60_settings_default(48_000);
        assert_eq!(s.tap, RrDr60Tap::RouteOutput as u32); // 009 FR-010
        assert_eq!(RrDr60Tap::RouteOutput as u32, 5);
        assert_eq!(RrDr60Tap::AfterVolumeAmp as u32, 6);
        assert_eq!(RrDr60Tap::AfterSpeaker as u32, 7);
        assert_eq!(RrDr60Tap::AfterEarphone as u32, 8);
        assert_eq!(RR_DR60_TAP_AFTER_STAGE_10, RrDr60Tap::AfterPlayback);
        for (v, t) in [
            (0, Tap::AfterRecord),
            (1, Tap::AfterPlayback),
            (2, Tap::AfterAgc),
            (3, Tap::AfterVas),
            (4, Tap::AfterDecoder),
            (5, Tap::RouteOutput),
            (6, Tap::AfterVolumeAmp),
            (7, Tap::AfterSpeaker),
            (8, Tap::AfterEarphone),
        ] {
            s.tap = v;
            assert_eq!(to_settings(&s).unwrap().tap, t, "{v}");
        }
        // Spec 012 FR-012: taps 9 and 10 after the microphone stages; 11 is refused.
        for (v, t) in [(9, Tap::AfterMicCapsule), (10, Tap::AfterMicAmp)] {
            s.tap = v;
            assert_eq!(to_settings(&s).unwrap().tap, t, "{v}");
        }
        s.tap = 11;
        assert!(to_settings(&s).is_err());
        assert_eq!(RrDr60Status::InvalidVolume as u32, 23);
        assert_eq!(RrDr60Status::TapNotOnRoute as u32, 24);
        assert_eq!(RrDr60Status::InvalidSpeedLevel as u32, 25); // spec 013
        assert_eq!(
            status_from_error(Error::InvalidSpeedLevel { level: 0 }),
            RrDr60Status::InvalidSpeedLevel
        );
        assert_eq!(
            status_from_error(Error::InvalidVolume { position: 2.0 }),
            RrDr60Status::InvalidVolume
        );
        assert_eq!(
            status_from_error(Error::TapNotOnRoute {
                tap: Tap::AfterSpeaker,
                route: rr_dr60::Route::Earphone,
            }),
            RrDr60Status::TapNotOnRoute
        );
        let d = rr_dr60_settings_default(48_000);
        assert!(
            d.output_volume_amp_enabled && d.output_speaker_enabled && d.output_earphone_enabled
        );
        let mut off = d;
        off.output_speaker_enabled = false;
        assert!(!to_settings(&off).unwrap().output.speaker_enabled);
        assert!(to_settings(&off).unwrap().output.volume_amp_enabled);
    }

    /// 005 T008 (FR-010, FR-015), restated by 006 T017: the 0.5 defaults, the reserved slots at
    /// 0, the clamp on, and the memory at the device's figures (S-001).
    #[test]
    fn settings_default_has_the_0_6_values() {
        let s = rr_dr60_settings_default(48_000);
        assert_eq!(s.struct_size, 120); // spec 012
        assert_eq!(s.memory_capacity_s, 3600); // S-001: 60 minutes
        assert_eq!(s.memory_max_recordings, 99); // S-001: 99 items
        assert!(s.agc_enabled); // A-020
        assert_eq!(s.agc_knee_dbfs, -1.0); // A-028
        assert_eq!(s.reserved_agc_1, 0.0);
        assert_eq!(s.reserved_agc_2, 0.0);
        assert_eq!(s.agc_attack_ms, 3.0); // A-034
        assert_eq!(s.agc_release_ms, 1370.0); // A-035
        assert_eq!(s.vas_threshold_dbfs, -40.0); // A-022 (revised by spec 005)
        assert!(s.adc_clamp_enabled); // A-030
        assert_eq!(to_settings(&s).unwrap(), Settings::new(48_000));
        // The reserved slots are ignored, whatever they hold.
        let mut noisy = s;
        noisy.reserved_agc_1 = f32::NAN;
        noisy.reserved_agc_2 = f32::INFINITY;
        assert_eq!(validate_c(&noisy), Ok(Settings::new(48_000)));
        // The clamp setting round-trips.
        let mut off = s;
        off.adc_clamp_enabled = false;
        assert!(!to_settings(&off).unwrap().adc_clamp_enabled);
    }

    /// 005 T008 (contracts/c-api.md › RrDr60SettingField): 4 is the knee (was the target), 5
    /// and 6 are retired and never returned, 7 and 8 keep their numbers; 006 T017: 14 and 15
    /// name the memory fields, and a 0 capacity is `INVALID_SETTING` naming field 14.
    #[test]
    fn setting_field_numbers_are_stable() {
        assert_eq!(RrDr60SettingField::AgcKneeDbfs as u32, 4);
        assert_eq!(RrDr60SettingField::AgcAttackMs as u32, 7);
        assert_eq!(RrDr60SettingField::AgcReleaseMs as u32, 8);
        assert_eq!(RrDr60SettingField::VasMode as u32, 9);
        assert_eq!(RrDr60SettingField::MemoryCapacityS as u32, 14);
        assert_eq!(RrDr60SettingField::MemoryMaxRecordings as u32, 15);
        let mut m = rr_dr60_settings_default(48_000);
        m.memory_capacity_s = 0;
        assert_eq!(
            validate_c(&m),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::MemoryCapacityS
            ))
        );
        m.memory_capacity_s = 10;
        m.memory_max_recordings = 10_000;
        assert_eq!(
            validate_c(&m),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::MemoryMaxRecordings
            ))
        );
        m.memory_max_recordings = 3;
        assert_eq!(to_settings(&m).unwrap().memory.capacity_s, 10);
        assert_eq!(to_settings(&m).unwrap().memory.max_recordings, 3);
        let all = [
            RrDr60SettingField::None,
            RrDr60SettingField::HostRate,
            RrDr60SettingField::Tap,
            RrDr60SettingField::StructSize,
            RrDr60SettingField::AgcKneeDbfs,
            RrDr60SettingField::AgcAttackMs,
            RrDr60SettingField::AgcReleaseMs,
            RrDr60SettingField::VasMode,
            RrDr60SettingField::VasSensitivity,
            RrDr60SettingField::VasThresholdDbfs,
            RrDr60SettingField::VasHangMs,
            RrDr60SettingField::VasOnsetMs,
        ];
        assert!(all.iter().all(|f| *f as u32 != 5 && *f as u32 != 6));
        let mut s = rr_dr60_settings_default(48_000);
        s.agc_knee_dbfs = 4.0; // above the +3 dBFS cap (005 R-05)
        assert_eq!(
            validate_c(&s),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::AgcKneeDbfs
            ))
        );
        s.agc_knee_dbfs = -40.0;
        s.agc_attack_ms = 0.5; // below the 1 ms floor (005 R-05)
        assert_eq!(
            validate_c(&s),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::AgcAttackMs
            ))
        );
        s.agc_attack_ms = 50.0;
        s.agc_release_ms = 199.0;
        assert_eq!(
            validate_c(&s),
            Err((
                RrDr60Status::InvalidSetting,
                RrDr60SettingField::AgcReleaseMs
            ))
        );
    }

    /// 005 T008 (contracts/c-api.md), restated by 006 T017: a 0.5 caller's 80-byte struct (and
    /// a 0.4 caller's 72) is rejected after reading only `struct_size`, as `STRUCT_SIZE`.
    #[test]
    fn a_0_5_struct_size_is_rejected() {
        let mut s = rr_dr60_settings_default(48_000);
        s.struct_size = 80;
        assert_eq!(
            to_settings(&s),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
        s.struct_size = 72;
        assert_eq!(
            to_settings(&s),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
        // SAFETY: a valid struct; `check_struct_size` reads only its first field.
        let fault = unsafe { check_struct_size(&s) }.err();
        assert_eq!(
            fault,
            Some((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
    }

    /// Spec 006 FR-009 / FR-020 (coach review of US1, finding 1): `rr_dr60_process` reports
    /// `RECORDING_IN_PROGRESS` / `PLAYBACK_IN_PROGRESS` instead of silently producing nothing,
    /// writes the idle info and leaves the output untouched.
    #[test]
    fn process_is_refused_while_a_transport_is_active() {
        let mut s = rr_dr60_settings_default(48_000);
        s.memory_capacity_s = 1;
        let mut handle: *mut RrDr60Pipeline = std::ptr::null_mut();
        // SAFETY: both pointers are valid for the call.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut handle) }, RrDr60Status::Ok);
        let x = [0.25f32; 48];
        let mut y = [7.0f32; 48];
        let mut info = RrDr60BlockInfo {
            produced: 99,
            ..RrDr60BlockInfo::default()
        };
        // SAFETY: the handle is live (created above).
        unsafe {
            (*handle).inner.start_recording().unwrap();
            let fed = (*handle).inner.record(&x, &mut []).unwrap();
            assert!(fed.stopped.is_none());
        }
        // SAFETY: the buffers are valid for 48 floats and do not overlap.
        let status = unsafe { rr_dr60_process(handle, x.as_ptr(), y.as_mut_ptr(), 48, &mut info) };
        assert_eq!(status, RrDr60Status::RecordingInProgress);
        assert_eq!(info.produced, 0);
        assert!(y.iter().all(|&v| v == 7.0));
        // SAFETY: the handle is live.
        unsafe {
            let stop = (*handle).inner.stop_recording(&mut []).unwrap();
            assert!(matches!(
                stop.result,
                rr_dr60::StopResult::Kept { number: 1, .. }
            ));
            (*handle).inner.start_playback(1).unwrap();
        }
        // SAFETY: as above; in place this time.
        let status = unsafe { rr_dr60_process(handle, y.as_ptr(), y.as_mut_ptr(), 48, &mut info) };
        assert_eq!(status, RrDr60Status::PlaybackInProgress);
        assert!(y.iter().all(|&v| v == 7.0));
        // SAFETY: the handle is live and not used afterwards.
        unsafe { rr_dr60_destroy(handle) };
    }

    /// 006 T040 (contracts/c-api.md): statuses 6–19 by value and name, the three new enums'
    /// values, and every new `Error` variant's status.
    #[test]
    fn transport_statuses_enums_and_error_mapping() {
        let statuses = [
            (6, RrDr60Status::RecordingInProgress, "RecordingInProgress"),
            (7, RrDr60Status::PlaybackInProgress, "PlaybackInProgress"),
            (8, RrDr60Status::NotRecording, "NotRecording"),
            (9, RrDr60Status::NotPlaying, "NotPlaying"),
            (10, RrDr60Status::MemoryFull, "MemoryFull"),
            (11, RrDr60Status::NoRecordingSlots, "NoRecordingSlots"),
            (12, RrDr60Status::NoSuchRecording, "NoSuchRecording"),
            (13, RrDr60Status::DoesNotFit, "DoesNotFit"),
            (14, RrDr60Status::UnknownForm, "UnknownForm"),
            (
                15,
                RrDr60Status::UnsupportedFormVersion,
                "UnsupportedFormVersion",
            ),
            (16, RrDr60Status::Damaged, "Damaged"),
            (
                17,
                RrDr60Status::StoredExceedsCapacity,
                "StoredExceedsCapacity",
            ),
            (18, RrDr60Status::AllocationFailed, "AllocationFailed"),
            (19, RrDr60Status::BufferTooSmall, "BufferTooSmall"),
            // Spec 008 contracts/c-api.md.
            (21, RrDr60Status::EncodingDiffers, "EncodingDiffers"),
            (
                22,
                RrDr60Status::UnsupportedCodecModelVersion,
                "UnsupportedCodecModelVersion",
            ),
        ];
        for (value, status, name) in statuses {
            assert_eq!(status as i32, value, "{name}");
            assert_eq!(format!("{status:?}"), name);
        }
        assert_eq!(RrDr60Route::Speaker as u32, 0);
        assert_eq!(RrDr60Route::Earphone as u32, 1);
        assert_eq!(RrDr60State::Idle as u32, 0);
        assert_eq!(RrDr60State::Recording as u32, 1);
        assert_eq!(RrDr60State::Playing as u32, 2);
        assert_eq!(RrDr60StopReason::None as u32, 0);
        assert_eq!(RrDr60StopReason::MemoryFull as u32, 1);
        let errors = [
            (
                Error::RecordingInProgress,
                RrDr60Status::RecordingInProgress,
            ),
            (Error::PlaybackInProgress, RrDr60Status::PlaybackInProgress),
            (Error::NotRecording, RrDr60Status::NotRecording),
            (Error::NotPlaying, RrDr60Status::NotPlaying),
            (Error::MemoryFull, RrDr60Status::MemoryFull),
            (Error::NoRecordingSlots, RrDr60Status::NoRecordingSlots),
            (
                Error::NoSuchRecording { number: 3 },
                RrDr60Status::NoSuchRecording,
            ),
            (Error::DoesNotFit, RrDr60Status::DoesNotFit),
            (Error::UnknownForm, RrDr60Status::UnknownForm),
            (
                Error::UnsupportedFormVersion { version: 2 },
                RrDr60Status::UnsupportedFormVersion,
            ),
            (Error::Damaged, RrDr60Status::Damaged),
            (
                Error::StoredExceedsCapacity,
                RrDr60Status::StoredExceedsCapacity,
            ),
            (Error::AllocationFailed, RrDr60Status::AllocationFailed),
            (
                Error::BufferTooSmall { needed: 40 },
                RrDr60Status::BufferTooSmall,
            ),
            (Error::EncodingDiffers, RrDr60Status::EncodingDiffers),
            (
                Error::UnsupportedCodecModelVersion {
                    major: 0,
                    minor: 7,
                    patch: 0,
                },
                RrDr60Status::UnsupportedCodecModelVersion,
            ),
        ];
        for (e, status) in errors {
            assert_eq!(
                error_to_status_and_field(e),
                (status, RrDr60SettingField::None)
            );
        }
    }

    /// 006 T040: the five new structs are `repr(C)` with fixed-width fields at the contract's
    /// order; their sizes follow from the C layout rules.
    #[test]
    fn transport_struct_layouts() {
        use std::mem::offset_of;
        assert_eq!(offset_of!(RrDr60EngineState, state), 0);
        assert_eq!(offset_of!(RrDr60EngineState, route), 4);
        assert_eq!(offset_of!(RrDr60EngineState, current_recording), 8);
        assert_eq!(offset_of!(RrDr60EngineState, speaker_muted), 12);
        assert_eq!(size_of::<RrDr60EngineState>(), 16);
        let w = size_of::<usize>();
        assert_eq!(offset_of!(RrDr60RecordInfo, stored), 0);
        assert_eq!(offset_of!(RrDr60RecordInfo, events), w);
        assert_eq!(offset_of!(RrDr60RecordInfo, paused), 2 * w);
        assert_eq!(offset_of!(RrDr60RecordInfo, stopped), 2 * w + 1);
        assert_eq!(offset_of!(RrDr60RecordInfo, stop_reason), 2 * w + 4);
        // Spec 008 contracts/c-api.md: the frame fields appended (64-bit figures asserted below).
        assert_eq!(offset_of!(RrDr60RecordInfo, frames), 2 * w + 8);
        assert_eq!(offset_of!(RrDr60StopOutcome, flush), 0);
        assert_eq!(offset_of!(RrDr60PlayInfo, produced), 0);
        assert_eq!(offset_of!(RrDr60PlayInfo, finished), w);
        assert_eq!(offset_of!(RrDr60PlayInfo, frames), 2 * w);
        assert_eq!(offset_of!(RrDr60BlockInfo, frames), 3 * w);
        #[cfg(target_pointer_width = "64")]
        {
            assert_eq!(size_of::<RrDr60BlockInfo>(), 32); // 24 → 32
            assert_eq!(offset_of!(RrDr60RecordInfo, frames_total), 32);
            assert_eq!(size_of::<RrDr60RecordInfo>(), 40); // 24 → 40
            assert_eq!(offset_of!(RrDr60StopOutcome, kept), 40);
            assert_eq!(offset_of!(RrDr60StopOutcome, number), 44);
            assert_eq!(offset_of!(RrDr60StopOutcome, length_samples), 48);
            assert_eq!(offset_of!(RrDr60StopOutcome, silence_fed_samples), 56);
            assert_eq!(size_of::<RrDr60StopOutcome>(), 80); // 40 → 64 → 80 (0.20)
            assert_eq!(offset_of!(RrDr60PlayInfo, frame_index), 24);
            assert_eq!(offset_of!(RrDr60PlayInfo, place), 32); // spec 013
            assert_eq!(size_of::<RrDr60PlayInfo>(), 40); // 16 → 32 → 40 (013)
        }
        assert_eq!(size_of::<RrDr60SpeechCodecInfo>(), 24);
        assert_eq!(offset_of!(RrDr60SpeechCodecInfo, model_version), 16);
        assert_eq!(offset_of!(RrDr60SpeechCodecInfo, reserved), 22);
        assert_eq!(offset_of!(RrDr60MemoryStatus, capacity_samples), 0);
        assert_eq!(offset_of!(RrDr60MemoryStatus, used_samples), 8);
        assert_eq!(offset_of!(RrDr60MemoryStatus, remaining_samples), 16);
        assert_eq!(offset_of!(RrDr60MemoryStatus, max_recordings), 24);
        assert_eq!(offset_of!(RrDr60MemoryStatus, count), 28);
        assert_eq!(offset_of!(RrDr60MemoryStatus, slots_remaining), 32);
        assert_eq!(size_of::<RrDr60MemoryStatus>(), 40);
    }

    /// A 48 kHz handle with a 10 s memory, the VAS off.
    fn small_handle() -> *mut RrDr60Pipeline {
        let mut s = rr_dr60_settings_default(48_000);
        s.memory_capacity_s = 10;
        s.memory_max_recordings = 3;
        s.vas_enabled = false;
        // The samples encoding (spec 008 FR-012): the 006 export and import rules are checked
        // with the codec off; `codec_handle` covers the frames encoding (008 T040).
        s.speech_codec_enabled = false;
        let mut handle: *mut RrDr60Pipeline = std::ptr::null_mut();
        // SAFETY: both pointers are valid for the call.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut handle) }, RrDr60Status::Ok);
        handle
    }

    /// 006 T040: an invalid route value is `INVALID_ARGUMENT` and the route is unchanged.
    #[test]
    fn invalid_route_value_is_rejected() {
        let p = small_handle();
        let mut route = 9u32;
        // SAFETY: live handle; valid out pointer.
        unsafe {
            assert_eq!(rr_dr60_set_route(p, 1), RrDr60Status::Ok);
            assert_eq!(rr_dr60_set_route(p, 7), RrDr60Status::InvalidArgument);
            assert_eq!(rr_dr60_get_route(p, &mut route), RrDr60Status::Ok);
            assert_eq!(route, RrDr60Route::Earphone as u32);
            assert_eq!(
                rr_dr60_get_route(p, std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            rr_dr60_destroy(p);
        }
    }

    /// 006 T040 (rule 2's amendment): `rr_dr60_record`, `rr_dr60_stop_recording` and
    /// `rr_dr60_play` write their info struct on every early return: a NULL handle, a
    /// poisoned handle and `frames == 0`.
    #[test]
    fn info_structs_are_written_on_early_returns() {
        let x = [0.25f32; 48];
        let mut y = [7.0f32; 48];
        let garbage = RrDr60RecordInfo {
            stored: 9,
            events: 9,
            paused: true,
            stopped: true,
            stop_reason: 9,
            frames: 9,
            frames_total: 9,
        };
        let mut rec = garbage;
        let mut play = RrDr60PlayInfo {
            produced: 9,
            finished: true,
            frames: 9,
            frame_index: 9,
            place: 9,
        };
        let mut outcome = RrDr60StopOutcome {
            flush: garbage,
            kept: true,
            number: 9,
            length_samples: 9,
            silence_fed_samples: 9,
            stop_input_position: 9,
            padding_start_sample: 9,
        };
        // SAFETY: a NULL handle is allowed; the buffers are valid.
        unsafe {
            assert_eq!(
                rr_dr60_record(
                    std::ptr::null_mut(),
                    x.as_ptr(),
                    48,
                    &mut rec,
                    std::ptr::null_mut(),
                    0
                ),
                RrDr60Status::NullPointer
            );
            assert_eq!(rec, RrDr60RecordInfo::default());
            assert_eq!(
                rr_dr60_play(std::ptr::null_mut(), y.as_mut_ptr(), 48, &mut play),
                RrDr60Status::NullPointer
            );
            assert_eq!(play, RrDr60PlayInfo::default());
            assert_eq!(
                rr_dr60_stop_recording(std::ptr::null_mut(), &mut outcome, std::ptr::null_mut(), 0),
                RrDr60Status::NullPointer
            );
            assert_eq!(outcome, RrDr60StopOutcome::default());
        }
        let p = small_handle();
        // SAFETY: live handle; valid buffers.
        unsafe {
            // frames == 0 while idle: still NOT_RECORDING / NOT_PLAYING, info written.
            rec = garbage;
            assert_eq!(
                rr_dr60_record(p, std::ptr::null(), 0, &mut rec, std::ptr::null_mut(), 0),
                RrDr60Status::NotRecording
            );
            assert_eq!(rec, RrDr60RecordInfo::default());
            assert_eq!(rr_dr60_start_recording(p), RrDr60Status::Ok);
            rec = garbage;
            assert_eq!(
                rr_dr60_record(p, std::ptr::null(), 0, &mut rec, std::ptr::null_mut(), 0),
                RrDr60Status::Ok
            );
            assert_eq!(rec, RrDr60RecordInfo::default());
            // Poisoned: INTERNAL_ERROR, info written, nothing else changes.
            (*p).poisoned = true;
            rec = garbage;
            assert_eq!(
                rr_dr60_record(p, x.as_ptr(), 48, &mut rec, std::ptr::null_mut(), 0),
                RrDr60Status::InternalError
            );
            assert_eq!(rec, RrDr60RecordInfo::default());
            outcome.kept = true;
            assert_eq!(
                rr_dr60_stop_recording(p, &mut outcome, std::ptr::null_mut(), 0),
                RrDr60Status::InternalError
            );
            assert_eq!(outcome, RrDr60StopOutcome::default());
            play.produced = 9;
            assert_eq!(
                rr_dr60_play(p, y.as_mut_ptr(), 48, &mut play),
                RrDr60Status::InternalError
            );
            assert_eq!(play, RrDr60PlayInfo::default());
            assert!(y.iter().all(|&v| v == 7.0));
            (*p).poisoned = false;
            assert_eq!(rr_dr60_reset(p), RrDr60Status::Ok);
            rr_dr60_destroy(p);
        }
    }

    /// 006 T040 (coach review of US2–US3): `rr_dr60_export` with a NULL buffer is
    /// `NULL_POINTER` (size queries go through `rr_dr60_export_len`); an import while playing
    /// is accepted and appended.
    #[test]
    fn export_null_buffer_and_import_while_playing() {
        let p = small_handle();
        let x = [0.25f32; 4800];
        let mut rec = RrDr60RecordInfo::default();
        let mut outcome = RrDr60StopOutcome::default();
        let mut written = 99usize;
        let mut len = 0usize;
        let mut number = 0u32;
        let mut play = RrDr60PlayInfo::default();
        let mut y = [0.0f32; 512];
        // SAFETY: live handle; valid buffers.
        unsafe {
            assert_eq!(rr_dr60_start_recording(p), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_record(p, x.as_ptr(), x.len(), &mut rec, std::ptr::null_mut(), 0),
                RrDr60Status::Ok
            );
            assert_eq!(
                rr_dr60_stop_recording(p, &mut outcome, std::ptr::null_mut(), 0),
                RrDr60Status::Ok
            );
            assert!(outcome.kept && outcome.number == 1);
            assert_eq!(rr_dr60_export_len(p, 1, &mut len), RrDr60Status::Ok);
            assert_eq!(len, 52 + 4 * outcome.length_samples as usize); // form version 2, samples (008 FR-010)
            assert_eq!(
                rr_dr60_export(p, 1, std::ptr::null_mut(), 0, &mut written),
                RrDr60Status::NullPointer
            );
            assert_eq!(written, 99, "untouched on NULL_POINTER");
            let mut bytes = vec![0u8; len];
            assert_eq!(
                rr_dr60_export(p, 1, bytes.as_mut_ptr(), bytes.len(), &mut written),
                RrDr60Status::Ok
            );
            assert_eq!(written, len);
            assert_eq!(rr_dr60_start_playback(p, 1), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_play(p, y.as_mut_ptr(), y.len(), &mut play),
                RrDr60Status::Ok
            );
            assert_eq!(
                rr_dr60_import(p, bytes.as_ptr(), bytes.len(), &mut number),
                RrDr60Status::Ok
            );
            assert_eq!(number, 2);
            let mut st = RrDr60EngineState::default();
            assert_eq!(rr_dr60_get_state(p, &mut st), RrDr60Status::Ok);
            assert_eq!(st.state, RrDr60State::Playing as u32);
            assert_eq!(st.current_recording, 1);
            assert_eq!(rr_dr60_stop_playback(p), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_import(p, std::ptr::null(), 0, &mut number),
                RrDr60Status::NullPointer
            );
            rr_dr60_destroy(p);
        }
    }

    // ---- Spec 007 User Story 3: the stage manifest through the C API (T024) ----

    #[test]
    fn manifest_struct_layouts() {
        // contracts/c-api.md: five pointers and six u32 in the header; the entry's coverage
        // pointer at 4w + 20 rounded up to a multiple of w.
        use std::mem::offset_of;
        let w = size_of::<usize>();
        assert_eq!(size_of::<RrDr60ManifestHeader>(), 5 * w + 24);
        assert_eq!(offset_of!(RrDr60ManifestHeader, library_version), 0);
        assert_eq!(offset_of!(RrDr60ManifestHeader, device_rate_hz), w);
        assert_eq!(offset_of!(RrDr60ManifestHeader, stage_count), w + 4);
        assert_eq!(offset_of!(RrDr60ManifestHeader, count_not_modeled), w + 8);
        assert_eq!(offset_of!(RrDr60ManifestHeader, count_assumed), w + 12);
        assert_eq!(offset_of!(RrDr60ManifestHeader, count_sourced), w + 16);
        assert_eq!(offset_of!(RrDr60ManifestHeader, count_checked), w + 20);
        assert_eq!(offset_of!(RrDr60ManifestHeader, basis), w + 24);
        assert_eq!(offset_of!(RrDr60ManifestHeader, evidence_link), 2 * w + 24);
        assert_eq!(
            offset_of!(RrDr60ManifestHeader, assumptions_link),
            3 * w + 24
        );
        assert_eq!(offset_of!(RrDr60ManifestHeader, sources_link), 4 * w + 24);
        let coverage = (4 * w + 20).next_multiple_of(w);
        assert_eq!(size_of::<RrDr60StageEntry>(), coverage + 3 * w);
        assert_eq!(offset_of!(RrDr60StageEntry, number), 0);
        assert_eq!(offset_of!(RrDr60StageEntry, identifier), w);
        assert_eq!(offset_of!(RrDr60StageEntry, name), 2 * w);
        assert_eq!(offset_of!(RrDr60StageEntry, description), 3 * w);
        assert_eq!(offset_of!(RrDr60StageEntry, status), 4 * w);
        assert_eq!(offset_of!(RrDr60StageEntry, path), 4 * w + 4);
        assert_eq!(offset_of!(RrDr60StageEntry, confidence), 4 * w + 8);
        assert_eq!(offset_of!(RrDr60StageEntry, source_count), 4 * w + 12);
        assert_eq!(offset_of!(RrDr60StageEntry, assumption_count), 4 * w + 16);
        assert_eq!(offset_of!(RrDr60StageEntry, coverage), coverage);
        assert_eq!(offset_of!(RrDr60StageEntry, controls), coverage + w);
        assert_eq!(
            offset_of!(RrDr60StageEntry, model_version),
            coverage + 2 * w
        );
        if w == 8 {
            assert_eq!(size_of::<RrDr60ManifestHeader>(), 64);
            assert_eq!(size_of::<RrDr60StageEntry>(), 80);
        }
    }

    #[test]
    fn status_code_20_is_no_such_stage() {
        assert_eq!(RrDr60Status::NoSuchStage as i32, 20);
        assert_eq!(RrDr60Status::NoSuchControl as i32, 26); // spec 014
        assert_eq!(
            [
                RR_DR60_CONTROL_PATH_RECORD,
                RR_DR60_CONTROL_PATH_PLAYBACK,
                RR_DR60_CONTROL_PATH_ONE_PASS
            ],
            [
                u32::from(rr_dr60::ControlPaths::RECORD.bits()),
                u32::from(rr_dr60::ControlPaths::PLAYBACK.bits()),
                u32::from(rr_dr60::ControlPaths::ONE_PASS.bits())
            ]
        );
        assert_eq!(
            rr_dr60::ControlKind::HostParameter as u32,
            RrDr60ControlKind::HostParameter as u32
        );
        assert_eq!(
            rr_dr60::ControlTiming::HostFixed as u32,
            RrDr60ControlTiming::HostFixed as u32
        );
    }

    #[test]
    fn enum_values_match_core() {
        // contracts/c-api.md: the three enums carry the core twin's u32 values.
        assert_eq!(RrDr60StageStatus::NotModeled as u32, 0);
        assert_eq!(RrDr60StageStatus::Assumed as u32, 1);
        assert_eq!(RrDr60StageStatus::Sourced as u32, 2);
        assert_eq!(RrDr60StageStatus::Checked as u32, 3);
        assert_eq!(RrDr60StagePath::Record as u32, 0);
        assert_eq!(RrDr60StagePath::Playback as u32, 1);
        assert_eq!(RrDr60StagePath::Both as u32, 2);
        assert_eq!(RrDr60Confidence::NotApplicable as u32, 0);
        assert_eq!(RrDr60Confidence::Low as u32, 1);
        assert_eq!(RrDr60Confidence::Medium as u32, 2);
        assert_eq!(RrDr60Confidence::High as u32, 3);
        for (e, c) in rr_dr60::manifest()
            .stages()
            .iter()
            .zip(rr_dr60::manifest::__c::STAGES.iter())
        {
            assert_eq!(e.status as u32, c.status);
            assert_eq!(e.path as u32, c.path);
            assert_eq!(e.confidence as u32, c.confidence);
        }
    }

    #[test]
    fn no_such_stage_and_null() {
        // contracts/c-api.md: NULL first, then the range, then the index; nothing written on a
        // refusal.
        assert_eq!(rr_dr60_manifest_stage_count(), 15);
        let sentinel = RrDr60StageEntry {
            number: 0xFFFF_FFFF,
            ..RrDr60StageEntry::default()
        };
        let mut e = sentinel;
        // SAFETY: valid out pointer.
        unsafe {
            assert_eq!(rr_dr60_manifest_stage(0, &mut e), RrDr60Status::NoSuchStage);
            assert_eq!(
                rr_dr60_manifest_stage(16, &mut e),
                RrDr60Status::NoSuchStage
            );
            assert_eq!(e.number, 0xFFFF_FFFF);
            assert_eq!(
                rr_dr60_manifest_stage(3, std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_manifest_header(std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(rr_dr60_manifest_stage(3, &mut e), RrDr60Status::Ok);
            assert_eq!(e.number, 3);
            let mut id: *const c_char = std::ptr::null();
            assert_eq!(
                rr_dr60_manifest_stage_source(3, e.source_count, &mut id),
                RrDr60Status::InvalidArgument
            );
            assert!(id.is_null());
            assert_eq!(
                rr_dr60_manifest_stage_assumption(3, e.assumption_count, &mut id),
                RrDr60Status::InvalidArgument
            );
            assert_eq!(
                rr_dr60_manifest_stage_source(0, 0, &mut id),
                RrDr60Status::NoSuchStage
            );
            assert_eq!(
                rr_dr60_manifest_stage_source(3, 0, std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_manifest_stage_source(3, 0, &mut id),
                RrDr60Status::Ok
            );
            assert_eq!(std::ffi::CStr::from_ptr(id).to_str().unwrap(), "S-001");
            let mut h = RrDr60ManifestHeader::default();
            assert_eq!(rr_dr60_manifest_header(&mut h), RrDr60Status::Ok);
            assert_eq!(h.stage_count, 15);
            assert_eq!(
                h.count_not_modeled + h.count_assumed + h.count_sourced + h.count_checked,
                15
            );
            assert_eq!(
                std::ffi::CStr::from_ptr(h.library_version)
                    .to_str()
                    .unwrap(),
                rr_dr60::VERSION
            );
        }
    }

    /// A 48 kHz handle with a 10 s memory, the VAS off, the speech codec on (the frames
    /// encoding).
    fn codec_handle() -> *mut RrDr60Pipeline {
        let mut s = rr_dr60_settings_default(48_000);
        s.memory_capacity_s = 10;
        s.memory_max_recordings = 3;
        s.vas_enabled = false;
        assert!(s.speech_codec_enabled, "on by default (A-004)");
        let mut handle: *mut RrDr60Pipeline = std::ptr::null_mut();
        // SAFETY: both pointers are valid for the call.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut handle) }, RrDr60Status::Ok);
        handle
    }

    /// Records 0.5 s of a ±0.125 square wave on `p`, stops, and returns the exported bytes
    /// with the stop outcome.
    fn record_export(p: *mut RrDr60Pipeline) -> (Vec<u8>, RrDr60StopOutcome) {
        let x: Vec<f32> = (0..24_000)
            .map(|i| if i % 48 < 24 { 0.125 } else { -0.125 })
            .collect();
        let mut info = RrDr60RecordInfo::default();
        let mut outcome = RrDr60StopOutcome::default();
        let mut len = 0usize;
        let mut written = 0usize;
        // SAFETY: live handle; valid buffers.
        unsafe {
            assert_eq!(rr_dr60_start_recording(p), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_record(p, x.as_ptr(), x.len(), &mut info, std::ptr::null_mut(), 0),
                RrDr60Status::Ok
            );
            assert_eq!(
                rr_dr60_stop_recording(p, &mut outcome, std::ptr::null_mut(), 0),
                RrDr60Status::Ok
            );
            assert!(outcome.kept);
            assert_eq!(
                rr_dr60_export_len(p, outcome.number, &mut len),
                RrDr60Status::Ok
            );
            let mut bytes = vec![0u8; len];
            assert_eq!(
                rr_dr60_export(p, outcome.number, bytes.as_mut_ptr(), len, &mut written),
                RrDr60Status::Ok
            );
            assert_eq!(written, len);
            (bytes, outcome)
        }
    }

    /// CRC-32 (IEEE 802.3) as the form contract states it, for the test's re-formed mutants.
    fn crc32(bytes: &[u8]) -> u32 {
        let mut c = 0xFFFF_FFFFu32;
        for &b in bytes {
            c ^= u32::from(b);
            for _ in 0..8 {
                c = if c & 1 != 0 {
                    (c >> 1) ^ 0xEDB8_8320
                } else {
                    c >> 1
                };
            }
        }
        !c
    }

    fn reformed(mut bytes: Vec<u8>) -> Vec<u8> {
        let n = bytes.len();
        let c = crc32(&bytes[..n - 4]);
        bytes[n - 4..].copy_from_slice(&c.to_le_bytes());
        bytes
    }

    /// 008 T040 (contracts/c-api.md): the codec control at 88, default `true`; a 0.7-layout
    /// `struct_size` of 88 is `STRUCT_SIZE`; the decoder tap is 4; the encoding values are the
    /// form's. (The size is 120 since 0.12, spec 012 contracts/c-api.md.)
    #[test]
    fn codec_settings_tap_and_encoding_values() {
        let s = rr_dr60_settings_default(48_000);
        assert_eq!(s.struct_size, 120);
        assert!(s.speech_codec_enabled);
        assert_eq!(s.reserved_008, 0);
        let mut old = s;
        old.struct_size = 88;
        assert_eq!(
            to_settings(&old),
            Err((
                RrDr60Status::InvalidArgument,
                RrDr60SettingField::StructSize
            ))
        );
        assert_eq!(RrDr60Tap::AfterDecoder as u32, 4);
        let mut tap = s;
        tap.tap = RrDr60Tap::AfterDecoder as u32;
        assert_eq!(to_settings(&tap).unwrap().tap, rr_dr60::Tap::AfterDecoder);
        assert_eq!(RrDr60Encoding::Frames as u32, 1);
        assert_eq!(RrDr60Encoding::Samples as u32, 2);
        assert_eq!(
            RrDr60Encoding::Frames as u32,
            rr_dr60::Encoding::Frames.form_code() as u32
        );
        assert_eq!(
            RrDr60Encoding::Samples as u32,
            rr_dr60::Encoding::Samples.form_code() as u32
        );
    }

    /// 008 T040: `rr_dr60_speech_codec_info` equals `speech_codec::info()` field by field;
    /// NULL is `NULL_POINTER`.
    #[test]
    fn speech_codec_info_matches_rust() {
        let mut c = RrDr60SpeechCodecInfo::default();
        // SAFETY: valid out pointer; NULL is the refused case.
        unsafe {
            assert_eq!(
                rr_dr60_speech_codec_info(std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(rr_dr60_speech_codec_info(&mut c), RrDr60Status::Ok);
        }
        let r = rr_dr60::speech_codec::info();
        assert_eq!(c.frame_samples, r.frame_samples);
        assert_eq!(c.frame_ms, r.frame_ms);
        assert_eq!(c.bits_per_frame, r.bits_per_frame);
        assert_eq!(c.delay_samples, r.delay_samples);
        assert_eq!(c.model_version, r.model_version);
        assert_eq!(c.reserved, 0);
        assert_eq!(
            (
                c.frame_samples,
                c.frame_ms,
                c.bits_per_frame,
                c.delay_samples
            ),
            (120, 20, 80, 180)
        );
        assert_eq!(c.model_version, [0, 8, 0]);
    }

    /// 008 T040: `rr_dr60_get_encoding` reads frames on the default and samples when bypassed;
    /// NULL out is `NULL_POINTER`.
    #[test]
    fn get_encoding_on_both_configurations() {
        let on = codec_handle();
        let off = small_handle();
        let mut e = 0u32;
        // SAFETY: live handles; valid out pointer.
        unsafe {
            assert_eq!(rr_dr60_get_encoding(on, &mut e), RrDr60Status::Ok);
            assert_eq!(e, RrDr60Encoding::Frames as u32);
            assert_eq!(rr_dr60_get_encoding(off, &mut e), RrDr60Status::Ok);
            assert_eq!(e, RrDr60Encoding::Samples as u32);
            assert_eq!(
                rr_dr60_get_encoding(on, std::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_get_encoding(std::ptr::null_mut(), &mut e),
                RrDr60Status::NullPointer
            );
            rr_dr60_destroy(on);
            rr_dr60_destroy(off);
        }
    }

    /// 008 T040 (US4 scenarios 1 and 2): the frame fields through C (frames per block, the
    /// total, the silence fed, the playback frames and index), the frames form (52 + 10K), and
    /// the refusals: 15 for a version 1 sequence, 21 for the other encoding (both directions),
    /// 22 for a wrong codec model version, `NULL_POINTER` for a NULL `bytes`.
    #[test]
    fn frames_through_c_and_the_new_import_statuses() {
        let on = codec_handle();
        let off = small_handle();
        let (frames, outcome) = record_export(on);
        let (samples, _) = record_export(off);
        // The frame fields of the outcome and the form.
        assert_eq!(outcome.length_samples % 120, 0);
        let k = outcome.length_samples / 120;
        assert_eq!(outcome.flush.frames_total, k);
        assert!(outcome.silence_fed_samples >= 60 && outcome.silence_fed_samples < 180);
        assert_eq!(frames.len(), 52 + 10 * k as usize);
        assert_eq!(u16::from_le_bytes([frames[22], frames[23]]), 1, "frames");
        assert_eq!(u16::from_le_bytes([samples[22], samples[23]]), 2, "samples");
        // Playback reports the frames decoded and the index.
        let mut buf = vec![0.0f32; 997];
        let mut decoded = 0usize;
        let last_index;
        // SAFETY: live handle; valid buffers.
        unsafe {
            assert_eq!(rr_dr60_start_playback(on, 1), RrDr60Status::Ok);
            loop {
                let mut pi = RrDr60PlayInfo::default();
                assert_eq!(
                    rr_dr60_play(on, buf.as_mut_ptr(), buf.len(), &mut pi),
                    RrDr60Status::Ok
                );
                decoded += pi.frames;
                if pi.finished {
                    last_index = pi.frame_index;
                    break;
                }
            }
        }
        assert_eq!(decoded as u64, k);
        assert_eq!(last_index, k - 1);
        // Refusals.
        let mut number = 0u32;
        let mut v1 = frames[..8].to_vec();
        v1.extend_from_slice(&1u16.to_le_bytes());
        v1.extend_from_slice(&0u16.to_le_bytes());
        v1.extend_from_slice(&6000u32.to_le_bytes());
        v1.extend_from_slice(&[0u8; 6]);
        v1.extend_from_slice(&0u16.to_le_bytes());
        v1.extend_from_slice(&2u64.to_le_bytes());
        v1.extend_from_slice(&0.5f32.to_le_bytes());
        v1.extend_from_slice(&(-0.25f32).to_le_bytes());
        v1.extend_from_slice(&[0u8; 4]);
        let v1 = reformed(v1);
        let mut model = frames.clone();
        model[24..30].copy_from_slice(&[0, 0, 7, 0, 0, 0]);
        let model = reformed(model);
        // SAFETY: live handles; valid buffers and out pointer.
        unsafe {
            assert_eq!(
                rr_dr60_import(off, v1.as_ptr(), v1.len(), &mut number),
                RrDr60Status::UnsupportedFormVersion
            );
            assert_eq!(
                rr_dr60_import(on, v1.as_ptr(), v1.len(), &mut number),
                RrDr60Status::UnsupportedFormVersion
            );
            assert_eq!(
                rr_dr60_import(off, frames.as_ptr(), frames.len(), &mut number),
                RrDr60Status::EncodingDiffers
            );
            assert_eq!(
                rr_dr60_import(on, samples.as_ptr(), samples.len(), &mut number),
                RrDr60Status::EncodingDiffers
            );
            assert_eq!(
                rr_dr60_import(on, model.as_ptr(), model.len(), &mut number),
                RrDr60Status::UnsupportedCodecModelVersion
            );
            assert_eq!(
                rr_dr60_import(on, std::ptr::null(), 0, &mut number),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_import(on, frames.as_ptr(), frames.len(), &mut number),
                RrDr60Status::Ok
            );
            assert_eq!(number, 2);
            let mut st = RrDr60MemoryStatus::default();
            assert_eq!(rr_dr60_memory_status(on, &mut st), RrDr60Status::Ok);
            assert_eq!(st.count, 2);
            assert_eq!(st.used_samples, 2 * outcome.length_samples);
            rr_dr60_destroy(on);
            rr_dr60_destroy(off);
        }
    }
}

/// Spec 016 FR-009 (tasks.md T019): the C read-out's size rules and refusals.
#[cfg(test)]
mod meters_tests {
    use super::*;

    fn handle() -> *mut RrDr60Pipeline {
        let s = rr_dr60_settings_default(48_000);
        let mut h: *mut RrDr60Pipeline = core::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut h) }, RrDr60Status::Ok);
        h
    }

    fn process_some(h: *mut RrDr60Pipeline) {
        let x = [0.5f32; 1024];
        let mut y = [0.0f32; 1024];
        let mut info = RrDr60BlockInfo::default();
        // SAFETY: a live handle and 1024-sample buffers.
        assert_eq!(
            unsafe { rr_dr60_process(h, x.as_ptr(), y.as_mut_ptr(), 1024, &mut info) },
            RrDr60Status::Ok
        );
    }

    #[test]
    fn exact_size_is_filled_and_equals_rust() {
        let h = handle();
        process_some(h);
        let mut m = RrDr60Meters {
            struct_size: 56,
            ..Default::default()
        };
        // SAFETY: a live handle and a valid out struct.
        assert_eq!(unsafe { rr_dr60_meters(h, &mut m) }, RrDr60Status::Ok);
        // SAFETY: a live handle.
        let r = unsafe { &*h }.inner.meters();
        assert_eq!(m.input_peak.to_bits(), r.input_peak.to_bits());
        assert_eq!(m.input_peak, 0.5);
        assert_eq!(m.hang_remaining_samples, r.hang_remaining_samples);
        assert_eq!(m.vas_paused, u32::from(r.vas_paused));
        assert_eq!(m.reserved_016, 0);
        assert_eq!(m.struct_size, 56);
        // Spec 018: a 0.17-sized request leaves the appended fields untouched (the default 0
        // here, not the engine's 1.0 ceiling factor).
        assert_eq!(m.battery_ceiling, 0.0);
        assert_eq!(m.amp_clip_count, 0);
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn smaller_size_is_refused_and_untouched() {
        let h = handle();
        process_some(h);
        let mut m = RrDr60Meters {
            struct_size: 55,
            input_peak: 7.0,
            ..Default::default()
        };
        // SAFETY: as above.
        assert_eq!(
            unsafe { rr_dr60_meters(h, &mut m) },
            RrDr60Status::InvalidArgument
        );
        assert_eq!(m.input_peak, 7.0, "nothing written");
        assert_eq!(m.struct_size, 55);
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn larger_size_is_filled_and_tail_zeroed() {
        let h = handle();
        process_some(h);
        // A 72-byte, 8-aligned buffer with a sentinel-filled tail (spec 018: the struct is 64
        // bytes; the tail past it is zeroed).
        #[repr(C, align(8))]
        struct Big([u8; 72]);
        let mut big = Big([0xA5; 72]);
        big.0[..4].copy_from_slice(&72u32.to_ne_bytes());
        let out = big.0.as_mut_ptr().cast::<RrDr60Meters>();
        // SAFETY: 72 writable, 8-aligned bytes whose first field says 72.
        assert_eq!(unsafe { rr_dr60_meters(h, out) }, RrDr60Status::Ok);
        // SAFETY: the first 64 bytes are a filled struct.
        let m = unsafe { out.read() };
        assert_eq!(m.struct_size, 72);
        assert_eq!(m.input_peak, 0.5);
        assert_eq!(m.battery_ceiling, 1.0, "the default's factor");
        assert!(big.0[64..].iter().all(|&b| b == 0), "the tail is zeroed");
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn null_handle_and_null_out_are_refused() {
        let mut m = RrDr60Meters {
            struct_size: 56,
            ..Default::default()
        };
        // SAFETY: a NULL handle is allowed by contract.
        assert_eq!(
            unsafe { rr_dr60_meters(core::ptr::null_mut(), &mut m) },
            RrDr60Status::NullPointer
        );
        let h = handle();
        // SAFETY: a NULL out is allowed by contract.
        assert_eq!(
            unsafe { rr_dr60_meters(h, core::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn poisoned_handle_is_refused() {
        let h = handle();
        // SAFETY: a live handle.
        unsafe { &mut *h }.poisoned = true;
        let mut m = RrDr60Meters {
            struct_size: 56,
            ..Default::default()
        };
        // SAFETY: as above.
        assert_eq!(
            unsafe { rr_dr60_meters(h, &mut m) },
            RrDr60Status::InternalError
        );
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn rest_before_any_call() {
        let h = handle();
        let mut m = RrDr60Meters {
            struct_size: 56,
            ..Default::default()
        };
        // SAFETY: as above.
        assert_eq!(unsafe { rr_dr60_meters(h, &mut m) }, RrDr60Status::Ok);
        assert_eq!(m.input_peak, 0.0);
        assert_eq!(
            m.hang_remaining_samples, 6000,
            "the configured 1 s hang at 6 kHz"
        );
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }
}

#[cfg(test)]
mod changes_tests {
    use super::*;

    fn handle() -> *mut RrDr60Pipeline {
        let s = rr_dr60_settings_default(48_000);
        let mut h: *mut RrDr60Pipeline = core::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut h) }, RrDr60Status::Ok);
        h
    }

    const ROUTE: u32 = 0;
    const VOLUME: u32 = 1;
    const SPEED: u32 = 2;
    const PLAYBACK: u32 = RrDr60Stream::Playback as u32;
    const ONE_PASS: u32 = RrDr60Stream::OnePass as u32;

    fn schedule(
        h: *mut RrDr60Pipeline,
        stream: u32,
        position: u64,
        control: u32,
        value: f64,
        tag: u64,
    ) -> RrDr60Status {
        // SAFETY: a live handle.
        unsafe { rr_dr60_schedule_change(h, stream, position, control, value, tag) }
    }

    fn pending(h: *mut RrDr60Pipeline, stream: u32) -> u32 {
        let mut n = u32::MAX;
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_pending_changes(h, stream, &mut n) },
            RrDr60Status::Ok
        );
        n
    }

    #[test]
    fn statuses_and_nothing_stored() {
        let h = handle();
        for _ in 0..64 {
            assert_eq!(schedule(h, ONE_PASS, 5, VOLUME, 0.5, 1), RrDr60Status::Ok);
        }
        assert_eq!(
            schedule(h, ONE_PASS, 5, VOLUME, 0.5, 1),
            RrDr60Status::ScheduleFull
        );
        assert_eq!(pending(h, ONE_PASS), 64);
        assert_eq!(
            schedule(h, ONE_PASS, 0, SPEED, 3.0, 1),
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(
            schedule(h, PLAYBACK, 0, 5, 1.0, 1),
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(
            schedule(h, 2, 0, VOLUME, 0.5, 1),
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(
            schedule(h, 9, 0, VOLUME, 0.5, 1),
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(
            schedule(h, PLAYBACK, 0, ROUTE, 2.0, 1),
            RrDr60Status::InvalidArgument
        );
        assert_eq!(
            schedule(h, PLAYBACK, 0, VOLUME, 1.5, 1),
            RrDr60Status::InvalidVolume
        );
        assert_eq!(
            schedule(h, PLAYBACK, 0, SPEED, 6.0, 1),
            RrDr60Status::InvalidSpeedLevel
        );
        assert_eq!(pending(h, PLAYBACK), 0);
        let mut n = 7u32;
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_pending_changes(h, 2, &mut n) },
            RrDr60Status::Ok // 017: the record stream has a schedule
        );
        assert_eq!(n, 0);
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_pending_changes(h, 3, &mut n) },
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(n, 0, "nothing written");
        let mut pos = 7u64;
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_stream_position(h, 9, &mut pos) },
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(pos, 7);
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_clear_schedule(h, 2) },
            RrDr60Status::Ok // 017: the record stream has a schedule
        );
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_clear_schedule(h, 3) },
            RrDr60Status::ControlNotOnStream
        );
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_clear_schedule(h, ONE_PASS) },
            RrDr60Status::Ok
        );
        assert_eq!(pending(h, ONE_PASS), 0);
        // SAFETY: a live handle.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn null_rules() {
        let h = handle();
        let mut n = 0u32;
        let mut pos = 0u64;
        let mut counter = 0u64;
        let mut index = 0u64;
        // SAFETY: NULL handles are refused before any dereference.
        unsafe {
            assert_eq!(
                rr_dr60_schedule_change(core::ptr::null_mut(), 0, 0, 0, 0.0, 0),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_pending_changes(core::ptr::null(), 0, &mut n),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_pending_changes(h, 0, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_stream_position(h, 0, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(rr_dr60_stream_position(h, 0, &mut pos), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_clear_schedule(core::ptr::null_mut(), 0),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_recording_counter(h, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(rr_dr60_recording_counter(h, &mut counter), RrDr60Status::Ok);
            assert_eq!(counter, 0);
            assert_eq!(
                rr_dr60_speed_landing(9, 48_000, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_speed_landing(9, 22_050, &mut index),
                RrDr60Status::InvalidArgument
            );
            assert_eq!(
                rr_dr60_speed_landing(9, 0, &mut index),
                RrDr60Status::InvalidArgument
            );
            assert_eq!(index, 0, "nothing written");
            assert_eq!(
                rr_dr60_speed_landing(9, 48_000, &mut index),
                RrDr60Status::Ok
            );
            assert_eq!(index, 2);
            // A log buffer NULL with a capacity: refused; the count pointer NULL: accepted.
            let x = [0.1f32; 64];
            let mut y = [0.0f32; 64];
            let mut info = RrDr60BlockInfo::default();
            assert_eq!(
                rr_dr60_process_with_events_and_changes(
                    h,
                    x.as_ptr(),
                    y.as_mut_ptr(),
                    64,
                    &mut info,
                    core::ptr::null_mut(),
                    0,
                    core::ptr::null_mut(),
                    4,
                    core::ptr::null_mut()
                ),
                RrDr60Status::NullPointer
            );
            let mut log = [RrDr60ChangeEntry::default(); 4];
            assert_eq!(
                rr_dr60_process_with_events_and_changes(
                    h,
                    x.as_ptr(),
                    y.as_mut_ptr(),
                    64,
                    &mut info,
                    core::ptr::null_mut(),
                    0,
                    log.as_mut_ptr(),
                    4,
                    core::ptr::null_mut()
                ),
                RrDr60Status::Ok
            );
            rr_dr60_destroy(h);
        }
    }

    #[test]
    fn the_log_and_the_counter_through_c() {
        let h = handle();
        assert_eq!(schedule(h, ONE_PASS, 10, VOLUME, 0.25, 5), RrDr60Status::Ok);
        assert_eq!(schedule(h, ONE_PASS, 20, ROUTE, 1.0, 6), RrDr60Status::Ok);
        let x = [0.1f32; 256];
        let mut y = [0.0f32; 256];
        let mut info = RrDr60BlockInfo::default();
        let mut log = [RrDr60ChangeEntry::default(); 1];
        let mut count = 0usize;
        // SAFETY: a live handle and valid buffers.
        assert_eq!(
            unsafe {
                rr_dr60_process_with_events_and_changes(
                    h,
                    x.as_ptr(),
                    y.as_mut_ptr(),
                    256,
                    &mut info,
                    core::ptr::null_mut(),
                    0,
                    log.as_mut_ptr(),
                    1,
                    &mut count,
                )
            },
            RrDr60Status::Ok
        );
        assert_eq!(count, 2, "both applied, one written");
        assert_eq!(
            (log[0].position, log[0].control, log[0].after, log[0].tag),
            (10, VOLUME, 0.25, 5)
        );
        assert_eq!(log[0].reserved, rr_dr60::STREAM_ONE_PASS); // 020 D9
        assert_eq!(pending(h, ONE_PASS), 0);
        let mut pos = 0u64;
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_stream_position(h, ONE_PASS, &mut pos) },
            RrDr60Status::Ok
        );
        assert_eq!(pos, 256);
        // The counter after a recording.
        // SAFETY: a live handle.
        assert_eq!(unsafe { rr_dr60_start_recording(h) }, RrDr60Status::Ok);
        let mut rinfo = RrDr60RecordInfo::default();
        // SAFETY: a live handle and a valid buffer.
        assert_eq!(
            unsafe { rr_dr60_record(h, x.as_ptr(), 256, &mut rinfo, core::ptr::null_mut(), 0) },
            RrDr60Status::Ok
        );
        let mut out = RrDr60StopOutcome::default();
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_stop_recording(h, &mut out, core::ptr::null_mut(), 0) },
            RrDr60Status::Ok
        );
        let mut counter = 0u64;
        // SAFETY: a live handle and a valid out pointer.
        assert_eq!(
            unsafe { rr_dr60_recording_counter(h, &mut counter) },
            RrDr60Status::Ok
        );
        assert_eq!(counter, 1);
        // play_with_changes with a scheduled speed change.
        assert_eq!(schedule(h, PLAYBACK, 3, SPEED, 5.0, 9), RrDr60Status::Ok);
        // SAFETY: a live handle.
        assert_eq!(unsafe { rr_dr60_start_playback(h, 1) }, RrDr60Status::Ok);
        let mut pinfo = RrDr60PlayInfo::default();
        let mut plog = [RrDr60ChangeEntry::default(); 2];
        // SAFETY: a live handle and valid buffers.
        assert_eq!(
            unsafe {
                rr_dr60_play_with_changes(
                    h,
                    y.as_mut_ptr(),
                    256,
                    &mut pinfo,
                    plog.as_mut_ptr(),
                    2,
                    &mut count,
                )
            },
            RrDr60Status::Ok
        );
        assert_eq!(count, 1);
        assert_eq!(
            (
                plog[0].position,
                plog[0].control,
                plog[0].before,
                plog[0].after,
                plog[0].tag
            ),
            (3, SPEED, 3.0, 5.0, 9)
        );
        // SAFETY: a live handle.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn layout_and_constants() {
        assert_eq!(size_of::<RrDr60ChangeEntry>(), 40);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, position), 0);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, before), 8);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, after), 16);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, tag), 24);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, control), 32);
        assert_eq!(core::mem::offset_of!(RrDr60ChangeEntry, reserved), 36);
        assert_eq!(RrDr60Stream::Playback as u32, 0);
        assert_eq!(RrDr60Stream::OnePass as u32, 1);
        assert_eq!(RrDr60Stream::Record as u32, 2);
        assert_eq!(
            RR_DR60_SCHEDULE_CAPACITY,
            rr_dr60::changes::SCHEDULE_CAPACITY
        );
        assert_eq!(
            RR_DR60_MAX_CHANGES_PER_CALL,
            rr_dr60::changes::MAX_CHANGES_PER_CALL
        );
        assert_eq!(RrDr60Status::ScheduleFull as u32, 27);
        assert_eq!(RrDr60Status::ControlNotOnStream as u32, 28);
        assert_eq!(RrDr60Status::NoSuchClock as u32, 29); // spec 017
        assert_eq!(RR_DR60_MAX_CHANGES_PER_CALL, 139); // spec 017 FR-005
        assert_eq!(
            status_from_error(Error::ReservedStream {
                stream: Stream::Record
            }),
            RrDr60Status::ControlNotOnStream
        );
        assert_eq!(
            status_from_error(Error::InvalidControlValue {
                control: 0,
                value: 2.0
            }),
            RrDr60Status::InvalidArgument
        );
    }
}

/// Spec 017 (tasks.md T013): the C surface of the record-side values.
#[cfg(test)]
mod record_tests {
    use super::*;

    fn handle() -> *mut RrDr60Pipeline {
        let mut s = rr_dr60_settings_default(48_000);
        s.speech_codec_enabled = false;
        let mut h: *mut RrDr60Pipeline = core::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut h) }, RrDr60Status::Ok);
        h
    }

    fn index(id: &str) -> u32 {
        rr_dr60::controls()
            .iter()
            .position(|e| e.identifier == id)
            .expect("a control") as u32
    }

    const RECORD: u32 = RrDr60Stream::Record as u32;
    const ONE_PASS: u32 = RrDr60Stream::OnePass as u32;
    const PLAYBACK: u32 = RrDr60Stream::Playback as u32;

    #[test]
    fn statuses_clocks_and_helpers() {
        let h = handle();
        let sens = index("vas.sensitivity");
        let hang = index("vas.hang_ms");
        let volume = index("volume");
        // SAFETY: a live handle.
        unsafe {
            assert_eq!(
                rr_dr60_schedule_change(h, RECORD, 0, sens, 6.0, 1),
                RrDr60Status::InvalidSetting
            );
            assert_eq!(
                rr_dr60_schedule_change(h, ONE_PASS, 0, hang, 20.0, 1),
                RrDr60Status::InvalidSetting
            );
            assert_eq!(
                rr_dr60_schedule_change(h, PLAYBACK, 0, sens, 5.0, 1),
                RrDr60Status::ControlNotOnStream
            );
            assert_eq!(
                rr_dr60_schedule_change(h, RECORD, 0, index("vas.mode"), 1.0, 1),
                RrDr60Status::ControlNotOnStream
            );
            assert_eq!(
                rr_dr60_schedule_change(h, RECORD, 0, volume, 0.5, 1),
                RrDr60Status::ControlNotOnStream
            );
            let mut n = 7u32;
            assert_eq!(rr_dr60_pending_changes(h, RECORD, &mut n), RrDr60Status::Ok);
            assert_eq!(n, 0, "nothing stored");
            let mut pos = 7u64;
            assert_eq!(
                rr_dr60_input_position(h, PLAYBACK, &mut pos),
                RrDr60Status::NoSuchClock
            );
            assert_eq!(pos, 7, "nothing written");
            assert_eq!(
                rr_dr60_stream_position(h, RECORD, &mut pos),
                RrDr60Status::NoSuchClock
            );
            assert_eq!(pos, 7);
            assert_eq!(
                rr_dr60_input_position(h, RECORD, &mut pos),
                RrDr60Status::Ok
            );
            assert_eq!(pos, 0);
            assert_eq!(
                rr_dr60_input_position(h, ONE_PASS, &mut pos),
                RrDr60Status::Ok
            );
            assert_eq!(pos, 0);
            assert_eq!(
                rr_dr60_input_position(h, 9, &mut pos),
                RrDr60Status::ControlNotOnStream
            );
            assert_eq!(
                rr_dr60_input_position(core::ptr::null(), RECORD, &mut pos),
                RrDr60Status::NullPointer
            );
            assert_eq!(
                rr_dr60_input_position(h, RECORD, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            let mut clock = 7u32;
            assert_eq!(rr_dr60_clock_of(sens, &mut clock), RrDr60Status::Ok);
            assert_eq!(clock, RrDr60Clock::Input as u32);
            assert_eq!(rr_dr60_clock_of(volume, &mut clock), RrDr60Status::Ok);
            assert_eq!(clock, RrDr60Clock::Output as u32);
            assert_eq!(
                rr_dr60_clock_of(rr_dr60_control_count(), &mut clock),
                RrDr60Status::NoSuchControl
            );
            assert_eq!(clock, RrDr60Clock::Output as u32, "nothing written");
            assert_eq!(
                rr_dr60_clock_of(sens, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            let mut k = 7u64;
            assert_eq!(rr_dr60_record_landing(9, 48_000, &mut k), RrDr60Status::Ok);
            assert_eq!(k, 2);
            assert_eq!(rr_dr60_record_landing(0, 6000, &mut k), RrDr60Status::Ok);
            assert_eq!(k, 0);
            assert_eq!(
                rr_dr60_record_landing(9, 22_050, &mut k),
                RrDr60Status::InvalidArgument
            );
            assert_eq!(k, 0, "nothing written");
            assert_eq!(
                rr_dr60_record_landing(9, 48_000, core::ptr::null_mut()),
                RrDr60Status::NullPointer
            );
            rr_dr60_destroy(h);
        }
        assert_eq!(RrDr60Clock::Input as u32, rr_dr60::Clock::Input as u32);
        assert_eq!(RrDr60Clock::Output as u32, rr_dr60::Clock::Output as u32);
        assert_eq!(
            status_from_error(Error::NoSuchClock {
                stream: Stream::Record
            }),
            RrDr60Status::NoSuchClock
        );
        assert_eq!(
            status_from_error(Error::NoSuchControl { control: 29 }),
            RrDr60Status::NoSuchControl
        );
    }

    #[test]
    fn a_scheduled_landing_through_record_and_stop() {
        let h = handle();
        let sens = index("vas.sensitivity");
        let knee = index("agc.knee_dbfs");
        let input = vec![0.01f32; 2000];
        let mut entries = [RrDr60ChangeEntry::default(); RR_DR60_MAX_CHANGES_PER_CALL];
        let mut info = RrDr60RecordInfo::default();
        let mut count = 0usize;
        let mut total = 0u64;
        // SAFETY: a live handle and valid buffers.
        unsafe {
            assert_eq!(
                rr_dr60_schedule_change(h, RECORD, 700, sens, 5.0, 11),
                RrDr60Status::Ok
            );
            assert_eq!(rr_dr60_start_recording(h), RrDr60Status::Ok);
            assert_eq!(
                rr_dr60_record_with_changes(
                    h,
                    input.as_ptr(),
                    1000,
                    &mut info,
                    core::ptr::null_mut(),
                    0,
                    entries.as_mut_ptr(),
                    RR_DR60_MAX_CHANGES_PER_CALL,
                    &mut count,
                    &mut total,
                ),
                RrDr60Status::Ok
            );
            assert_eq!(count, 1);
            assert_eq!(total, 1000);
            assert_eq!(
                (entries[0].position, entries[0].control, entries[0].tag),
                (700, sens, 11)
            );
            assert_eq!((entries[0].before, entries[0].after), (3.0, 5.0));
            let mut pos = 0u64;
            assert_eq!(
                rr_dr60_input_position(h, RECORD, &mut pos),
                RrDr60Status::Ok
            );
            assert_eq!(pos, 1000);
            // A change inside the flush, reported by the stop with the final position.
            let mut latency = 0u32;
            assert_eq!(
                rr_dr60_record_latency_samples(h, &mut latency),
                RrDr60Status::Ok
            );
            assert_eq!(
                rr_dr60_schedule_change(h, RECORD, 1000 + u64::from(latency) / 2, knee, -5.0, 12),
                RrDr60Status::Ok
            );
            let mut outcome = RrDr60StopOutcome::default();
            assert_eq!(
                rr_dr60_stop_recording_with_changes(
                    h,
                    &mut outcome,
                    core::ptr::null_mut(),
                    0,
                    entries.as_mut_ptr(),
                    RR_DR60_MAX_CHANGES_PER_CALL,
                    &mut count,
                    &mut total,
                ),
                RrDr60Status::Ok
            );
            assert!(outcome.kept);
            assert_eq!(count, 1);
            assert_eq!(entries[0].tag, 12);
            assert_eq!(total, 1000 + u64::from(latency));
            let mut n = 9u32;
            assert_eq!(rr_dr60_pending_changes(h, RECORD, &mut n), RrDr60Status::Ok);
            assert_eq!(n, 0, "the end clears");
            assert_eq!(
                rr_dr60_stop_recording_with_changes(
                    h,
                    &mut outcome,
                    core::ptr::null_mut(),
                    0,
                    core::ptr::null_mut(),
                    0,
                    &mut count,
                    &mut total,
                ),
                RrDr60Status::NotRecording
            );
            assert_eq!(
                rr_dr60_record_with_changes(
                    h,
                    input.as_ptr(),
                    10,
                    &mut info,
                    core::ptr::null_mut(),
                    0,
                    core::ptr::null_mut(),
                    5,
                    &mut count,
                    &mut total,
                ),
                RrDr60Status::NullPointer
            );
            rr_dr60_destroy(h);
        }
    }
}

/// Spec 018 (tasks.md T015): the battery C API, the defines against the core and the meters'
/// compatible prefix-fill rule.
#[cfg(test)]
mod battery_tests {
    use super::*;

    fn handle() -> *mut RrDr60Pipeline {
        let s = rr_dr60_settings_default(48_000);
        let mut h: *mut RrDr60Pipeline = core::ptr::null_mut();
        // SAFETY: valid pointers.
        assert_eq!(unsafe { rr_dr60_create(&s, &mut h) }, RrDr60Status::Ok);
        h
    }

    fn get(h: *mut RrDr60Pipeline) -> f32 {
        let mut v = f32::NAN;
        // SAFETY: a live handle and a writable out.
        assert_eq!(
            unsafe { rr_dr60_get_battery_volts(h, &mut v) },
            RrDr60Status::Ok
        );
        v
    }

    #[test]
    fn status_value_and_mapping() {
        assert_eq!(RrDr60Status::InvalidBatteryVolts as u32, 30); // spec 018
        assert_eq!(
            status_from_error(Error::InvalidBatteryVolts { volts: 2.1 }),
            RrDr60Status::InvalidBatteryVolts
        );
    }

    #[test]
    fn setter_and_getter() {
        let h = handle();
        assert_eq!(get(h), RR_DR60_BATTERY_VOLTS_DEFAULT);
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_set_battery_volts(h, 2.4) },
            RrDr60Status::Ok
        );
        assert_eq!(get(h), 2.4);
        for bad in [2.1f32, 3.1, f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            // SAFETY: a live handle.
            assert_eq!(
                unsafe { rr_dr60_set_battery_volts(h, bad) },
                RrDr60Status::InvalidBatteryVolts,
                "{bad}"
            );
            assert_eq!(get(h), 2.4, "unchanged after {bad}");
        }
        // The range's ends are accepted (spec 018 FR-001).
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_set_battery_volts(h, 2.2) },
            RrDr60Status::Ok
        );
        // SAFETY: a live handle.
        assert_eq!(
            unsafe { rr_dr60_set_battery_volts(h, 3.0) },
            RrDr60Status::Ok
        );
        // SAFETY: a NULL handle is allowed by contract; a NULL out is refused.
        assert_eq!(
            unsafe { rr_dr60_set_battery_volts(core::ptr::null_mut(), 2.4) },
            RrDr60Status::NullPointer
        );
        // SAFETY: a live handle, a NULL out.
        assert_eq!(
            unsafe { rr_dr60_get_battery_volts(h, core::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
    }

    #[test]
    fn law_is_total_and_refuses_only_non_finite() {
        let mut f = 0.0f32;
        let mut db = 0.0f32;
        for v in [1.8f32, 2.0, 2.2, 2.45, 2.8, 2.96, 3.0, 3.2] {
            // SAFETY: writable outs.
            assert_eq!(
                unsafe { rr_dr60_battery_ceiling_factor(v, &mut f) },
                RrDr60Status::Ok
            );
            assert_eq!(f, rr_dr60::battery::ceiling_factor(v), "{v}");
            // SAFETY: writable out.
            assert_eq!(
                unsafe { rr_dr60_battery_ceiling_db(v, &mut db) },
                RrDr60Status::Ok
            );
            assert_eq!(
                db.to_bits(),
                rr_dr60::battery::ceiling_db(v).to_bits(),
                "{v}"
            );
        }
        // SAFETY: writable out.
        assert_eq!(
            unsafe { rr_dr60_battery_ceiling_factor(3.0, &mut f) },
            RrDr60Status::Ok
        );
        assert_eq!(f, 1.0, "exactly 1 at the default");
        for bad in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            f = 7.0;
            // SAFETY: writable outs.
            assert_eq!(
                unsafe { rr_dr60_battery_ceiling_factor(bad, &mut f) },
                RrDr60Status::InvalidArgument
            );
            assert_eq!(f, 7.0, "nothing written");
            // SAFETY: writable out.
            assert_eq!(
                unsafe { rr_dr60_battery_ceiling_db(bad, &mut db) },
                RrDr60Status::InvalidArgument
            );
        }
        // SAFETY: NULL outs are refused.
        assert_eq!(
            unsafe { rr_dr60_battery_ceiling_factor(2.4, core::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
        // SAFETY: NULL outs are refused.
        assert_eq!(
            unsafe { rr_dr60_battery_ceiling_db(2.4, core::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
    }

    #[test]
    fn trajectory_rows_equal_the_core() {
        let rows = rr_dr60::battery::ALKALINE_TRAJECTORY;
        assert_eq!(rows.len(), RR_DR60_BATTERY_TRAJECTORY_ROWS as usize);
        for (i, &(hours, volts)) in rows.iter().enumerate() {
            let (mut h, mut v) = (-1.0f32, -1.0f32);
            // SAFETY: writable outs.
            assert_eq!(
                unsafe { rr_dr60_battery_trajectory_row(i as u32, &mut h, &mut v) },
                RrDr60Status::Ok
            );
            assert_eq!(
                (h.to_bits(), v.to_bits()),
                (hours.to_bits(), volts.to_bits())
            );
        }
        let (mut h, mut v) = (-1.0f32, -1.0f32);
        // SAFETY: writable outs.
        assert_eq!(
            unsafe {
                rr_dr60_battery_trajectory_row(RR_DR60_BATTERY_TRAJECTORY_ROWS, &mut h, &mut v)
            },
            RrDr60Status::InvalidArgument
        );
        assert_eq!((h, v), (-1.0, -1.0), "nothing written");
        // SAFETY: a NULL out is refused.
        assert_eq!(
            unsafe { rr_dr60_battery_trajectory_row(0, core::ptr::null_mut(), &mut v) },
            RrDr60Status::NullPointer
        );
        // SAFETY: a NULL out is refused.
        assert_eq!(
            unsafe { rr_dr60_battery_trajectory_row(0, &mut h, core::ptr::null_mut()) },
            RrDr60Status::NullPointer
        );
    }

    #[test]
    fn defines_equal_the_core() {
        let (lo, hi) = rr_dr60::battery::BATTERY_VOLTS_RANGE;
        assert_eq!(RR_DR60_BATTERY_VOLTS_MIN.to_bits(), lo.to_bits());
        assert_eq!(RR_DR60_BATTERY_VOLTS_MAX.to_bits(), hi.to_bits());
        assert_eq!(
            RR_DR60_BATTERY_VOLTS_DEFAULT.to_bits(),
            rr_dr60::battery::DEFAULT_BATTERY_VOLTS.to_bits()
        );
        assert_eq!(
            RR_DR60_BATTERY_NIMH_PAIR_VOLTS.to_bits(),
            rr_dr60::battery::NIMH_PAIR_VOLTS.to_bits()
        );
    }

    #[test]
    fn meters_layout() {
        assert_eq!(size_of::<RrDr60Meters>(), 64);
        assert_eq!(core::mem::offset_of!(RrDr60Meters, amp_clip_count), 56);
        assert_eq!(core::mem::offset_of!(RrDr60Meters, battery_ceiling), 60);
    }

    /// The prefix-fill rule on a sentinel-filled 80-byte buffer: the request `size` is written
    /// at offset 0, the call made, and the bytes examined.
    fn fill(size: u32) -> (RrDr60Status, [u8; 80]) {
        let h = handle();
        let x = [0.5f32; 1024];
        let mut y = [0.0f32; 1024];
        let mut info = RrDr60BlockInfo::default();
        // SAFETY: a live handle and 1024-sample buffers.
        assert_eq!(
            unsafe { rr_dr60_process(h, x.as_ptr(), y.as_mut_ptr(), 1024, &mut info) },
            RrDr60Status::Ok
        );
        #[repr(C, align(8))]
        struct Big([u8; 80]);
        let mut big = Big([0xA5; 80]);
        big.0[..4].copy_from_slice(&size.to_ne_bytes());
        // SAFETY: 80 writable, 8-aligned bytes whose first field says `size` ≤ 80.
        let status = unsafe { rr_dr60_meters(h, big.0.as_mut_ptr().cast::<RrDr60Meters>()) };
        // SAFETY: destroying once.
        unsafe { rr_dr60_destroy(h) };
        (status, big.0)
    }

    fn f32_at(b: &[u8; 80], at: usize) -> f32 {
        f32::from_ne_bytes(b[at..at + 4].try_into().unwrap())
    }

    #[test]
    fn prefix_fill_rule() {
        // 55: refused, nothing written (the sentinel stays past the size word).
        let (s, b) = fill(55);
        assert_eq!(s, RrDr60Status::InvalidArgument);
        assert!(b[4..].iter().all(|&x| x == 0xA5));
        // 56: the 0.16 fields filled, bytes 56 … 79 untouched.
        let (s, b) = fill(56);
        assert_eq!(s, RrDr60Status::Ok);
        assert_eq!(f32_at(&b, 4), 0.5, "input_peak");
        assert!(b[56..].iter().all(|&x| x == 0xA5), "nothing past 56");
        // 60: the 0.16 fields filled, nothing past 56 (hardware review B5: never a partial
        // appended field).
        let (s, b) = fill(60);
        assert_eq!(s, RrDr60Status::Ok);
        assert_eq!(f32_at(&b, 4), 0.5, "input_peak");
        assert!(b[56..].iter().all(|&x| x == 0xA5), "nothing past 56");
        // 64: everything filled, nothing past.
        let (s, b) = fill(64);
        assert_eq!(s, RrDr60Status::Ok);
        assert_eq!(f32_at(&b, 60), 1.0, "battery_ceiling at the default");
        assert!(b[64..].iter().all(|&x| x == 0xA5), "nothing past 64");
        // 72: everything filled, 64 … 71 zeroed, 72 … 79 untouched.
        let (s, b) = fill(72);
        assert_eq!(s, RrDr60Status::Ok);
        assert_eq!(f32_at(&b, 60), 1.0);
        assert!(b[64..72].iter().all(|&x| x == 0), "the tail is zeroed");
        assert!(b[72..].iter().all(|&x| x == 0xA5), "nothing past the size");
    }
}

